window.__EVERYPIVOT_PATTERN_SOURCES__ = {
  "CROSS_CLOUD_BUCKET_TO_DOMAINS": "id: CROSS_CLOUD_BUCKET_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: ownership_signal\nhazards:\n- 'Shared agency, reseller, or CDN-managed buckets can legitimately host unrelated domains.'\n- 'Stale CNAME or bucket references can persist after ownership or hosting changes.'\ncapability_requirements:\n  required:\n  - 'passive_dns'\n  - 'cloud_bucket_resolution'\n  optional:\n  - 'web_fingerprinting'\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: Cloud Object Bucket → Domains\ncategory: CROSS\ndescription: Cluster domains/CNAMEs pointing to the same object storage bucket (S3/GCS/Azure).\nsource: cloud:bucket\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: referenced_by\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - bucket.firstseen <= fqdn.seen\n    window_days: 1825\n  degree_caps:\n    cloud:bucket: 20000\n  negative_nodes:\n  - form: cloud:bucket\n    list: public_cdn_buckets\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n- osint_web\n",
  "CTI_APK_SIGNING_CERT_CLUSTER": "id: CTI_APK_SIGNING_CERT_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_APK_SIGNING_CERT_CLUSTER.json\n  sha256: 968e6bc370c8f80ab9eaabbf827b6ec247918009cbe4c8822a28170578e0127e\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- 'Shared OEM, test, default or repackaging credentials can link unrelated APKs without establishing a malware family or common developer.'\n- 'Certificate presence, reported signer association and a scoped source-reported check are distinct claims; this evaluator does not perform cryptographic signature verification.'\n- 'Whole-artifact, scheme-covered content, whole-certificate, SPKI and issuer/serial identities are distinct. Reuse establishes neither publisher trust, control, common ownership nor accepted assessment.'\n- 'Only an actual complete-finding establishment in the supplied collection history is dated. Reprocessing, receipt, validity dates and new sightings do not renew an older finding.'\n- 'Credential class is retained as context by default. Explicit selected class policies preserve unknown and conflicting evidence; a public certificate does not establish public access to its private key.'\n- 'Correction and withdrawal context is retained without replacing or refreshing the historical finding; absence of a supplied amendment does not establish maintained current support.'\ncapability_requirements:\n  required:\n  - 'semantic_evidence_v1'\n  - 'typed_artifact_and_material_identity'\n  - 'source_qualified_signing_or_digest_evidence'\n  - 'collection_finding_history'\n  - 'scoped_amendment_context'\n  optional:\n  - 'apk_signature_extraction'\n  - 'scoped_signature_verification_reports'\n  - 'credential_classification_with_revision'\n  - 'collection_knowledge_witnesses'\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: Certificate Identity or Explicit SPKI → APK Artifact Findings\ncategory: CTI\ndescription: 'Return case-period complete findings connecting an exact source-reported APK artifact to certificate presence, a reported signer, or a scoped source-reported verification check. Whole-certificate identity is distinct from deliberately selected SPKI reuse; actual role, artifact bytes identity and evidence remain attached.'\nsource: x509:cert\ntarget: file:bytes\nassessment_mode: evidence_only\nhops:\n- via: witnessed_in_artifact\n  direction: out\n  form: file:bytes\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- sandbox\n- osint_web\n",
  "CTI_CERT_REUSE_FQDN_CLUSTER": "id: CTI_CERT_REUSE_FQDN_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_CERT_REUSE_FQDN_CLUSTER.json\n  sha256: 18a0e202735fe17328b0253c4e739a058f8ea7899966dc0f81ce856f715db2b7\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- Whole-certificate identity and exact SPKI reuse are separate comparisons; renewal\n  with the same key does not preserve the whole certificate.\n- The explicitly selected older seed relationship remains reference evidence. A name\n  association does not become a seed presentation, and neither leg proves simultaneous\n  use or common ownership.\n- Candidate presentation uses an analyst/case-selected UTC period. Certificate validity,\n  first inventory, receipt and reprocessing do not substitute for that occurrence.\n- Intermediate certificate-class exclusions require an explicit selected filter; unknown\n  or conflicting class evidence is not clearance, and independent qualifying paths\n  remain.\ncapability_requirements:\n  required:\n  - semantic_evidence_v1\n  - certificate_normalization\n  - selected_seed_certificate_relationship\n  - presentation_occurrence_and_name_correspondence\n  optional:\n  - collection_knowledge_witnesses\n  - source_classification_evidence\n  - tls_scanning\n  - ct_history\nreview:\n  last_reviewed: '2026-05-14'\n  review_cadence_days: 90\n  next_review: '2026-08-12'\nname: Selected Certificate Reference or Explicit SPKI Reuse → FQDN Presentations\ncategory: CTI\ndescription: Selected evidenced historical seed relationship to candidate presentations.\n  Whole-certificate and SPKI comparisons, name and presentation reference bases remain\n  separate.\nsource: inet:fqdn\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: selected_certificate_reference\n  direction: out\n  form: x509:cert\n- via: explicit_certificate_or_spki_comparison\n  direction: out\n  form: x509:cert\n- via: observed_certificate_presentation\n  direction: out\n  form: inet:service\n- via: evidenced_presentation_name\n  direction: out\n  form: inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- ct\n- tls\n- pdns\n",
  "CTI_CLOUD_SUBSCRIPTION_TO_TENANT": "id: CTI_CLOUD_SUBSCRIPTION_TO_TENANT\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: ownership_signal\nhazards:\n- 'Subscriptions can move between tenants, be delegated, or be managed by service providers, so observation time must be preserved.'\n- 'Subscription-to-tenant containment is an administrative relationship and must not imply compromise or actor control.'\n- 'Multi-tenant service principals and delegated administration can create legitimate cross-tenant edges.'\n- 'Shared or default provider delegation patterns require corroboration with tenant-specific administrative evidence before clustering.'\ncapability_requirements:\n  required:\n  - 'cloud_subscription_identifier_normalization'\n  - 'cloud_tenant_identifier_normalization'\n  optional:\n  - 'delegated_admin_relationships'\n  - 'cloud_audit_log_access'\nreview:\n  last_reviewed: '2026-05-14'\n  review_cadence_days: 90\n  next_review: '2026-08-12'\nname: Cloud Subscription -> Tenant\ncategory: CTI\ndescription: Pivot from a normalized cloud subscription identifier to the tenant observed as owning or administering that subscription.\nsource: cloud:subscription:uid\ntarget: cloud:tenant:uid\nassessment_mode: evidence_only\nhops:\n- via: contained_by_tenant\n  direction: out\n  form: cloud:tenant:uid\nconstraints:\n  temporal:\n    order:\n    - subscription.observed <= tenant.observed\n    window_days: 30\n  degree_caps:\n    cloud:subscription:uid: 100000\n    cloud:tenant:uid: 100000\n  negative_nodes:\n  - form: cloud:tenant:uid\n    list: provider_service_or_support_tenants\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- subscription_tenant_match\n- delegated_admin_flag\n- tenant_age\n- temporal_consistency\n- provider_scope\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cloud_inventory\n- cloud_audit_logs\n",
  "CTI_CLOUD_TENANT_UID_TO_AUTH_EVENTS": "id: CTI_CLOUD_TENANT_UID_TO_AUTH_EVENTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'Cloud tenant pivots can cross administrative, customer, service-principal, guest-user, shared-service, and multi-tenant application boundaries.'\n- 'Auth events can be generated by service principals, automation, health checks, delegated access, and federation flows rather than direct user action.'\n- 'A tenant-to-auth-event relationship is control-plane context, not ownership, compromise, or actor attribution without corroborating evidence.'\n- 'Provider, demo, and synthetic-or-healthcheck tenants/events inflate fan-out and must be suppressed via the published negative-node lists rather than presented as normal user traversals.'\n- 'Stale or historical auth-event context outside the temporal window is not current access; downstream systems must treat it as audit or lifecycle context, not active session evidence.'\ncapability_requirements:\n  required:\n  - 'cloud_tenant_uid_normalization'\n  - 'cloud_auth_event_telemetry'\n  optional:\n  - 'service_principal_classification'\n  - 'guest_user_context'\nreview:\n  last_reviewed: '2026-06-01'\n  review_cadence_days: 90\n  next_review: '2026-08-30'\nname: Cloud Tenant UID -> Auth Events\ncategory: CTI\ndescription: Pivot from a normalized cloud tenant identifier to authentication events observed within that tenant context. First-hop single-step scope; associated-session multi-hop expansion remains deferred for a separate review.\nsource: cloud:tenant:uid\ntarget: auth:event\nassessment_mode: evidence_only\nhops:\n- via: contains_auth_event\n  direction: out\n  form: auth:event\nconstraints:\n  temporal:\n    order:\n    - tenant.observed <= auth_event.observed\n    window_days: 30\n  degree_caps:\n    cloud:tenant:uid: 100000\n    auth:event: 1000000\n  negative_nodes:\n  - form: auth:event\n    list: synthetic_or_healthcheck_auth_events\n  - form: identity:user:uid\n    list: guest_or_service_principal_accounts\n  - form: cloud:tenant:uid\n    list: multi_tenant_provider_or_demo_tenants\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- principal_role\n- tenant_relationship\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cloud_audit_logs\n- auth_logs\n- identity\n",
  "CTI_CLOUD_WEBAPP_TO_SUBSCRIPTION": "id: CTI_CLOUD_WEBAPP_TO_SUBSCRIPTION\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: ownership_signal\nhazards:\n- 'Cloud web app hostnames can be reassigned, disabled, recycled, or fronted by shared platform infrastructure.'\n- 'A web app to subscription join describes administrative containment, not proof of malicious use or actor ownership.'\n- 'Provider-specific IDs and product names must remain adapter metadata.'\ncapability_requirements:\n  required:\n  - 'cloud_webapp_inventory'\n  - 'cloud_subscription_identifier_normalization'\n  optional:\n  - 'cloud_audit_log_access'\n  - 'hostname_to_resource_mapping'\nreview:\n  last_reviewed: '2026-05-14'\n  review_cadence_days: 90\n  next_review: '2026-08-12'\nname: Cloud Web App -> Subscription\ncategory: CTI\ndescription: Pivot from a normalized cloud web app hostname or resource identifier to the cloud subscription that contains it.\nsource: cloud:webapp|inet:fqdn|inet:url\ntarget: cloud:subscription:uid\nassessment_mode: evidence_only\nhops:\n- via: belongs_to_subscription\n  direction: out\n  form: cloud:subscription:uid\nconstraints:\n  temporal:\n    order:\n    - webapp.observed <= subscription.observed\n    window_days: 30\n  degree_caps:\n    cloud:webapp: 1000\n    cloud:subscription:uid: 100000\n  negative_nodes:\n  - form: cloud:webapp\n    list: provider_default_or_recycled_webapps\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- resource_id_match\n- hostname_match\n- subscription_age\n- temporal_consistency\n- provider_scope\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cloud_inventory\n- cloud_audit_logs\n- dns\n",
  "CTI_CODESIGN_CERT_SERIAL_ISSUER_CLUSTER_STRICT": "id: CTI_CODESIGN_CERT_SERIAL_ISSUER_CLUSTER_STRICT\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_CODESIGN_CERT_SERIAL_ISSUER_CLUSTER_STRICT.json\n  sha256: 1b558fce8e746eff5d22728e39a74cee8786e301de0c7d7ad17597bbe22bcada\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- 'Issuer/serial is an exact declared tuple link, not a whole-certificate or SPKI identity guarantee. Issuer namespace and normalization must remain explicit.'\n- 'The version 2 blanket signing-service exclusion is replaced by a visible context default and explicit reusable class policy; consumers must migrate this behaviour with the version.'\n- 'Certificate presence, reported signer association and a scoped source-reported check are distinct claims; this evaluator does not perform cryptographic signature verification.'\n- 'Whole-artifact, scheme-covered content, whole-certificate, SPKI and issuer/serial identities are distinct. Reuse establishes neither publisher trust, control, common ownership nor accepted assessment.'\n- 'Only an actual complete-finding establishment in the supplied collection history is dated. Reprocessing, receipt, validity dates and new sightings do not renew an older finding.'\n- 'Credential class is retained as context by default. Explicit selected class policies preserve unknown and conflicting evidence; a public certificate does not establish public access to its private key.'\n- 'Correction and withdrawal context is retained without replacing or refreshing the historical finding; absence of a supplied amendment does not establish maintained current support.'\ncapability_requirements:\n  required:\n  - 'semantic_evidence_v1'\n  - 'typed_artifact_and_material_identity'\n  - 'source_qualified_signing_or_digest_evidence'\n  - 'collection_finding_history'\n  - 'scoped_amendment_context'\n  optional:\n  - 'codesign_certificate_parsing'\n  - 'scoped_signature_verification_reports'\n  - 'credential_classification_with_revision'\n  - 'collection_knowledge_witnesses'\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: Exact Issuer/Serial → Artifact Findings (Explicit Filters)\ncategory: CTI\ndescription: 'Return case-period artifact findings matched by an explicit exact issuer namespace and serial radix, with certificate presence, reported signer and scoped source-reported verification purposes kept separate. Version 3 retains credential context by default; exclusions require an explicit applicable class policy. The historical STRICT identifier does not promise an automatic blanket filter.'\nsource: x509:cert\ntarget: file:bytes\nassessment_mode: evidence_only\nhops:\n- via: issuer_serial_witness_in_artifact\n  direction: out\n  form: file:bytes\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- sandbox\n- osint_web\n",
  "CTI_EMAIL_PROTECTED_URL_TO_ORIGINAL_URL": "id: CTI_EMAIL_PROTECTED_URL_TO_ORIGINAL_URL\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: domain_expansion\nhazards:\n- 'Protected URL decoders can fail or produce partial output when providers change encodings, nest wrappers, or omit destination parameters.'\n- 'Decoded destinations can still be benign intermediary links that redirect again at click time.'\n- 'Common redirectors and shared security wrappers can create false joins; corroborate decoded destinations with message context.'\ncapability_requirements:\n  required:\n  - 'protected_url_decoding'\n  - 'url_normalization'\n  optional:\n  - 'redirect_resolution'\n  - 'provider_adapter_metadata'\nreview:\n  last_reviewed: '2026-05-14'\n  review_cadence_days: 90\n  next_review: '2026-08-12'\nname: Email Protected URL -> Original URL\ncategory: CTI\ndescription: Decode a protected or rewritten email URL into the original embedded destination URL while preserving provider and adapter provenance.\nsource: email:protected_url\ntarget: inet:url\nassessment_mode: evidence_only\nhops:\n- via: decodes_to\n  direction: out\n  form: inet:url\nconstraints:\n  temporal:\n    order:\n    - protected_url.observed <= original_url.decoded\n    window_days: 1\n  degree_caps:\n    email:protected_url: 100\n  negative_nodes:\n  - form: email:protected_url\n    list: malformed_or_unsupported_protected_urls\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- decoder_confidence\n- nested_wrapper_depth\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- url_corpus\n",
  "CTI_SAMPLE_CODESIGN_CERT_CLUSTER": "id: CTI_SAMPLE_CODESIGN_CERT_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_SAMPLE_CODESIGN_CERT_CLUSTER.json\n  sha256: 12ed8ebde892e0f9db6cfbe7ebe400e9098ecf4efcbe9da6dc421f7962448d02\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- 'Shared signing and release services can link unrelated products, while compromised or reused credentials do not identify their current operator.'\n- 'Certificate presence, reported signer association and a scoped source-reported check are distinct claims; this evaluator does not perform cryptographic signature verification.'\n- 'Whole-artifact, scheme-covered content, whole-certificate, SPKI and issuer/serial identities are distinct. Reuse establishes neither publisher trust, control, common ownership nor accepted assessment.'\n- 'Only an actual complete-finding establishment in the supplied collection history is dated. Reprocessing, receipt, validity dates and new sightings do not renew an older finding.'\n- 'Credential class is retained as context by default. Explicit selected class policies preserve unknown and conflicting evidence; a public certificate does not establish public access to its private key.'\n- 'Correction and withdrawal context is retained without replacing or refreshing the historical finding; absence of a supplied amendment does not establish maintained current support.'\ncapability_requirements:\n  required:\n  - 'semantic_evidence_v1'\n  - 'typed_artifact_and_material_identity'\n  - 'source_qualified_signing_or_digest_evidence'\n  - 'collection_finding_history'\n  - 'scoped_amendment_context'\n  optional:\n  - 'codesign_certificate_parsing'\n  - 'scoped_signature_verification_reports'\n  - 'credential_classification_with_revision'\n  - 'collection_knowledge_witnesses'\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: Certificate Identity or Explicit SPKI → Sample Findings\ncategory: CTI\ndescription: 'Return case-period complete findings connecting exact sample bytes to certificate presence, a reported signer, or a scoped source-reported verification check. Select whole-certificate or SPKI comparison explicitly and retain the particular signature, role and covered-content scope required by that purpose.'\nsource: x509:cert\ntarget: file:bytes\nassessment_mode: evidence_only\nhops:\n- via: witnessed_in_artifact\n  direction: out\n  form: file:bytes\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- sandbox\n- osint_web\n",
  "CTI_SAMPLE_CONFIG_KEY_CLUSTER": "id: CTI_SAMPLE_CONFIG_KEY_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- 'Default builder keys, campaign IDs, or templated config material can overcluster adjacent operations.'\n- 'Common builder defaults and shared malware frameworks can reuse config key material across unrelated samples.'\n- 'Parser or extraction errors can create false exact matches if config fields are not normalized carefully.'\ncapability_requirements:\n  required:\n  - 'config_extraction'\n  - 'sample_collection'\n  optional:\n  - 'sandbox_analysis'\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: Malware Config Key/ID → Sample Cluster\ncategory: CTI\ndescription: Cluster malware sharing exact C2 crypto keys, campaign IDs, or license/public keys from config.\nsource: c2:config:key\ntarget: file:bytes\nassessment_mode: evidence_only\nhops:\n- via: observed_in\n  direction: out\n  form: file:bytes\nconstraints:\n  temporal:\n    order:\n    - config.firstseen <= sample.firstseen\n    window_days: 1825\n  degree_caps:\n    c2:config:key: 20000\n  negative_nodes:\n  - form: c2:config:key\n    list: default_builder_keys\n  - form: c2:config:key\n    list: templated_campaign_ids\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- sandbox\n",
  "CTI_SAMPLE_IMPHASH_CLUSTER": "id: CTI_SAMPLE_IMPHASH_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Common packers, frameworks, malware builders, and benign software families can share import hashes without shared operation.'\n- 'Import hashes can change with minor build changes and can be distorted by packing, import reconstruction, or damaged PE metadata.'\ncapability_requirements:\n  required:\n  - 'pe_metadata_extraction'\n  - 'sample_hash_normalization'\n  optional:\n  - 'sandbox'\n  - 'malware_family_labels'\nreview:\n  last_reviewed: '2026-05-14'\n  review_cadence_days: 90\n  next_review: '2026-08-12'\nname: PE ImpHash -> Sample Cluster\ncategory: CTI\ndescription: Cluster Windows PE samples that share the same import hash, preserving file hashes and collection provenance.\nsource: file:pe:imphash\ntarget: file:bytes\nassessment_mode: evidence_only\nhops:\n- via: observed_in\n  direction: out\n  form: file:bytes\nconstraints:\n  temporal:\n    order:\n    - imphash.firstseen <= sample.firstseen\n    window_days: 3650\n  degree_caps:\n    file:pe:imphash: 10000\n  negative_nodes:\n  - form: file:pe:imphash\n    list: common_benign_imphashes\n  - form: file:pe:imphash\n    list: common_packer_imphashes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- packer_penalty\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- malware_corpus\n- sandbox\n- edr\n",
  "CTI_SAMPLE_PDB_PATH_CLUSTER": "id: CTI_SAMPLE_PDB_PATH_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Leaked builders, copied projects, and generic folder names can produce weak build-path overlaps.'\n- 'Canonicalization mistakes can merge distinct paths or split true matches if normalization is inconsistent.'\ncapability_requirements:\n  required:\n  - 'pe_metadata_extraction'\n  - 'pdb_path_extraction'\n  optional:\n  - 'path_normalization'\n  - 'common_build_path_suppression'\nreview:\n  last_reviewed: '2026-05-21'\n  review_cadence_days: 90\n  next_review: '2026-08-19'\nname: PDB Path -> Sample Cluster\ncategory: CTI\ndescription: Cluster malware samples reusing the same embedded PDB path or canonicalized build-path string.\nsource: it:dev:pdb:path\ntarget: file:bytes\nassessment_mode: evidence_only\nhops:\n- via: observed_in\n  direction: out\n  form: file:bytes\nconstraints:\n  temporal:\n    order:\n    - pdb.firstseen <= sample.firstseen\n    window_days: 3650\n  degree_caps:\n    it:dev:pdb:path: 5000\n  negative_nodes:\n  - form: it:dev:pdb:path\n    list: common_benign_pdb_paths\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- sandbox\n- malware_corpus\n",
  "OSINT_CERT_SHA_TO_DOMAINS": "id: OSINT_CERT_SHA_TO_DOMAINS\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/OSINT_CERT_SHA_TO_DOMAINS.json\n  sha256: 68ef8f8110867bef1d0e8153fe064b19a4a8c230ebe72fdf180b6b0cf24fe30f\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- 'Managed certificates and shared web hosts can create benign overlap between unrelated domains.'\n- 'Scanner lag and historical cert retention can preserve stale domain relationships after rotation.'\n- 'Certificate name fields and CT/precertificate records do not establish network presentation; supplied source assertions remain source-qualified.'\n- 'Presentation inquiries require case-selected UTC dates. Certificate validity, receipt and reprocessing do not refresh presentation time.'\n- 'Source and address class exclusions are explicit contract query policies; missing or conflicting classification is not clearance.'\ncapability_requirements:\n  required:\n  - 'certificate_normalization'\n  - 'semantic_evidence_v1'\n  optional:\n  - 'tls_scanning'\n  - 'ct_history'\n  - 'presentation_occurrence_and_name_correspondence'\n  - 'collection_knowledge_witnesses'\nreview:\n  last_reviewed: '2026-05-14'\n  review_cadence_days: 90\n  next_review: '2026-08-12'\nname: Certificate Identity or Explicit SPKI Reuse → Named Domains\ncategory: OSINT\ndescription: Return explicitly selected certificate/CT name associations or observed presentation in a named service context. Whole-certificate identity and deliberately selected SPKI reuse have distinct match reasons; neither implies endpoint identity, ownership or control.\nsource: x509:cert\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: named_in_certificate|presented_in_named_context\n  direction: out\n  form: inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- ct\n- tls\n",
  "OSINT_CERT_TO_SERVERS": "id: OSINT_CERT_TO_SERVERS\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/OSINT_CERT_TO_SERVERS.json\n  sha256: 4089cee02f6bfde495b13dd0b1ca5ced17487e7d3e1387545970ef87b5e2dc77\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- 'Managed certificates and shared load balancers can join unrelated hosts behind the same delivery surface.'\n- 'CT and scanner coverage can be incomplete or stale, so absence should not be interpreted as disproof.'\n- 'Certificate name fields and CT/precertificate records do not establish network presentation; supplied source assertions remain source-qualified.'\n- 'Presentation inquiries require case-selected UTC dates. Certificate validity, receipt and reprocessing do not refresh presentation time.'\n- 'Source and address class exclusions are explicit contract query policies; missing or conflicting classification is not clearance.'\ncapability_requirements:\n  required:\n  - 'certificate_normalization'\n  - 'semantic_evidence_v1'\n  optional:\n  - 'tls_scanning'\n  - 'ct_history'\n  - 'presentation_occurrence_and_name_correspondence'\n  - 'collection_knowledge_witnesses'\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: Certificate Identity or Explicit SPKI Reuse → Observed Servers\ncategory: OSINT\ndescription: Return IPv4 addresses or FQDNs linked to an actual certificate presentation occurrence. Whole-certificate identity and explicitly selected SPKI reuse remain distinct; a renewed certificate sharing a key is a different certificate.\nsource: x509:cert\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: observed_certificate_presentation\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- ct\n- tls\n",
  "OSINT_DKIM_KEY_CLUSTER": "id: OSINT_DKIM_KEY_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- 'Bulk mail providers can legitimately host many customer domains behind the same DKIM selector or key material.'\n- 'Delegated mail operations can obscure whether the link reflects direct ownership or outsourced sending.'\n- 'Common selectors and shared provider defaults require corroboration with domain control and mail configuration context.'\ncapability_requirements:\n  required:\n  - 'dns_mail_enrichment'\n  - 'dkim_key_extraction'\n  optional:\n  - 'mail_flow_analysis'\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: DKIM Public Key → Domain Cluster\ncategory: OSINT\ndescription: Cluster sending domains sharing the exact same DKIM public key (selector/keypair).\nsource: mail:dkim:key\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: used_by\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - dkim.firstseen <= fqdn.seen\n    window_days: 1095\n  degree_caps:\n    mail:dkim:key: 10000\n  negative_nodes:\n  - form: mail:dkim:key\n    list: provider_managed_dkim_keys\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n- osint_web\n",
  "OSINT_DMARC_RUA_TO_DOMAINS": "id: OSINT_DMARC_RUA_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Managed reporting providers legitimately aggregate DMARC traffic for many unrelated domains.'\n- 'Mailbox reuse can reflect outsourced email operations rather than direct affiliation between the senders.'\n- 'Common reporting mailboxes and shared provider defaults require corroboration with domain ownership and current DNS.'\ncapability_requirements:\n  required:\n  - 'dns_public_lookup'\n  - 'dns_mail_enrichment'\n  optional:\n  - 'dmarc_record_parsing'\n  - 'managed_mail_provider_suppression'\nreview:\n  last_reviewed: '2026-05-21'\n  review_cadence_days: 90\n  next_review: '2026-08-19'\nname: DMARC RUA Mailbox -> Domains\ncategory: OSINT\ndescription: Cluster domains that send aggregate DMARC reports to the same reporting mailbox, filtering provider-managed collection endpoints.\nsource: mail:dmarc:rua\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: receives_reports_for\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - rua.firstseen <= fqdn.seen\n    window_days: 1825\n  degree_caps:\n    mail:dmarc:rua: 5000\n  negative_nodes:\n  - form: mail:dmarc:rua\n    list: provider_managed_dmarc_mailboxes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- dns\n- osint_web\n",
  "OSINT_PRIVATE_NS_TO_DOMAINS": "id: OSINT_PRIVATE_NS_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: ownership_signal\nhazards:\n- 'White-label DNS resellers and managed hosting can create shared private nameservers for unrelated customers.'\n- 'Delegation records can remain stale after migrations, parking, or account turnover.'\ncapability_requirements:\n  required:\n  - 'passive_dns'\n  - 'delegation_resolution'\n  optional:\n  - 'whois_rdap'\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: Private Authoritative NS → Domains\ncategory: OSINT\ndescription: Enumerate domains delegated to a non‑provider (private) authoritative nameserver.\nsource: inet:fqdn:ns\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: authoritative_for\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - ns.seen <= fqdn.seen\n    window_days: 1825\n  degree_caps:\n    inet:fqdn:ns: 10000\n  negative_nodes:\n  - form: inet:fqdn:ns\n    list: public_ns_providers\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n",
  "OSINT_RDP_CERT_THUMBPRINT_CLUSTER": "id: OSINT_RDP_CERT_THUMBPRINT_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/OSINT_RDP_CERT_THUMBPRINT_CLUSTER.json\n  sha256: 43b7fa68c13650a1dc478821394d2e633b164f20134fa81335b3dc9e9498b5e4\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- Default images, cloned deployments, gateways and NAT can create shared certificate\n  observations without common host identity or control.\n- The pattern requires actual RDP presentation of the selected whole certificate.\n  Generic TLS presentation, a certificate name or SPKI reuse cannot substitute.\n- The analyst/case selects an inclusive UTC presentation period. Receipt, reprocessing\n  and certificate validity do not refresh the observed occurrence.\n- An explicitly selected CDN-address filter applies only through evidenced correspondence\n  to the same occurrence; unknown or conflicting membership is not clearance.\ncapability_requirements:\n  required:\n  - semantic_evidence_v1\n  - certificate_normalization\n  - rdp_presentation_occurrence_and_endpoint_correspondence\n  optional:\n  - collection_knowledge_witnesses\n  - source_classification_evidence\n  - rdp_scanning\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: Exact Certificate Identity → Observed RDP Endpoints\ncategory: OSINT\ndescription: Exact selected whole-certificate identity on actual RDP presentations\n  in the selected occurrence period; no TLS-only, endpoint-control or current-use\n  inference.\nsource: x509:cert\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: observed_rdp_certificate_presentation\n  direction: out\n  form: inet:service\n- via: evidenced_occurrence_endpoint\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- shodan_censys\n- tls\n",
  "OSINT_SSH_HOSTKEY_CLUSTER": "id: OSINT_SSH_HOSTKEY_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- 'Golden images and failed key rotation can legitimately duplicate SSH host keys across unrelated environments.'\n- 'Shared bastions or fronted services can hide the true endpoint population behind one observed key.'\ncapability_requirements:\n  required:\n  - 'ssh_scanning'\n  - 'hostkey_normalization'\n  optional:\n  - 'asset_allowlists'\nreview:\n  last_reviewed: '2026-04-04'\n  review_cadence_days: 90\n  next_review: '2026-07-03'\nname: SSH Host Key Fingerprint → Host Cluster\ncategory: OSINT\ndescription: Cluster servers that present the exact same SSH host key (e.g., ed25519/rsa SHA256).\nsource: ssh:hostkey\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: presented_by\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - hostkey.seen <= host.seen\n    window_days: 730\n  degree_caps:\n    ssh:hostkey: 5000\n  negative_nodes:\n  - form: inet:ipv4\n    list: known_scanner_asns\n  - form: inet:ipv4\n    list: shared_hosting_ranges\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- shodan_censys\n",
  "SUPPLY_CODESIGN_CERT_TO_PACKAGES": "id: SUPPLY_CODESIGN_CERT_TO_PACKAGES\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/SUPPLY_CODESIGN_CERT_TO_PACKAGES.json\n  sha256: 1e05f7813abd010591ed5ec4ad858eeaada9a722e54113a4eb897632f3e81375\nvalidation_state: validated\nprecision_tier: high\nrobustness_class: exact_cryptographic\nhazards:\n- 'Shared signing services and release pipelines can link unrelated products; signing reuse does not establish source provenance, maintainer identity or current signing control.'\n- 'Filename, version text or a current download URL cannot substitute for the exact artifact/version join. Detached, catalogue and manifest evidence retains the actual covered object rather than transferring a signature to every member.'\n- 'Certificate presence, reported signer association and a scoped source-reported check are distinct claims; this evaluator does not perform cryptographic signature verification.'\n- 'Whole-artifact, scheme-covered content, whole-certificate, SPKI and issuer/serial identities are distinct. Reuse establishes neither publisher trust, control, common ownership nor accepted assessment.'\n- 'Only an actual complete-finding establishment in the supplied collection history is dated. Reprocessing, receipt, validity dates and new sightings do not renew an older finding.'\n- 'Credential class is retained as context by default. Explicit selected class policies preserve unknown and conflicting evidence; a public certificate does not establish public access to its private key.'\n- 'Correction and withdrawal context is retained without replacing or refreshing the historical finding; absence of a supplied amendment does not establish maintained current support.'\ncapability_requirements:\n  required:\n  - 'semantic_evidence_v1'\n  - 'typed_artifact_and_material_identity'\n  - 'source_qualified_signing_or_digest_evidence'\n  - 'collection_finding_history'\n  - 'scoped_amendment_context'\n  - 'exact_distribution_artifact_mapping'\n  optional:\n  - 'code_signing_certificate_extraction'\n  - 'scoped_signature_verification_reports'\n  - 'package_registry_history'\n  - 'credential_classification_with_revision'\n  - 'collection_knowledge_witnesses'\nreview:\n  last_reviewed: '2026-05-14'\n  review_cadence_days: 90\n  next_review: '2026-08-12'\nname: Certificate Identity or Explicit SPKI → Package Artifact Findings\ncategory: SUPPLY\ndescription: 'Return case-period complete findings through an exact certificate-to-artifact-to-package/version connection, retaining ecosystem, namespace and distribution variant. Certificate presence, reported signer and scoped source-reported check purposes remain distinct; an installer finding does not establish that an entire version or product is signed.'\nsource: x509:cert\ntarget: it:prod:softver\nassessment_mode: evidence_only\nhops:\n- via: witnessed_in_artifact\n  direction: out\n  form: file:bytes\n- via: distributed_as\n  direction: out\n  form: it:prod:softver\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- package_registry\n- binary_metadata\n",
  "SUPPLY_SBOM_DEPENDENCY_TO_PRODUCTS": "id: SUPPLY_SBOM_DEPENDENCY_TO_PRODUCTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: validated\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- Common transitive dependencies, vendored packages, and version-range drift can make SBOM links overstate actual exposure.\n- Corroborate dependency reachability with product version, build metadata, and exploitability context; dependency presence alone is not compromise.\n- Ubiquitous base libraries inflate downstream-consumer fan-out and must be suppressed via the ubiquitous_base_libraries negative-node list rather than presented as positive clusters.\n- Stale or historical SBOM-declared dependencies are not current exposure; downstream systems must treat them as audit or lifecycle context, not runtime confidence.\ncapability_requirements:\n  required:\n  - 'sbom_ingestion'\n  - 'dependency_graph_resolution'\n  optional:\n  - 'package_metadata_collection'\n  - 'version_range_resolution'\nreview:\n  last_reviewed: '2026-06-01'\n  review_cadence_days: 90\n  next_review: '2026-08-30'\nname: Dependency -> Downstream Product Exposure\ncategory: SUPPLY\ndescription: Enumerate downstream products inheriting exposure through an SBOM-declared dependency relationship.\nsource: it:prod:softver\ntarget: it:prod:softver\nassessment_mode: evidence_only\nhops:\n- via: depended_on_by\n  direction: out\n  form: it:prod:softver\nconstraints:\n  temporal:\n    order:\n    - dependency.seen <= product.seen\n    window_days: 3650\n  degree_caps:\n    it:prod:softver: 50000\n  negative_nodes:\n  - form: it:prod:softver\n    list: ubiquitous_base_libraries\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- sbom\n- package_registry\n- vuln_db\n",
  "ADTECH_AD_REQUEST_TO_INFECTION_HIT": "id: ADTECH_AD_REQUEST_TO_INFECTION_HIT\nversion: 0.2.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: multi_hop_inference\nhazards:\n- 'Short temporal proximity between an ad request and a suspicious endpoint can reflect normal redirect, verification, or analytics flows unless the downstream endpoint is independently suspicious.'\n- 'Device or session identifiers may be redacted, hashed, or rotated, so identity continuity must be handled conservatively.'\n- 'Shared vendor redirects, tracking tags, and common verification pixels are false-positive sources; corroborate with endpoint risk and campaign context.'\ncapability_requirements:\n  required:\n  - 'web_request_telemetry'\n  - 'browser_client_uid_normalization'\n  optional:\n  - 'web_fingerprinting'\n  - 'endpoint_risk_context'\nname: Ad Request -> Suspicious Infection Hit\ncategory: ADTECH\ndescription: Link an ad-tech delivery or qualification request to a suspicious downstream endpoint when the two events share a device/session identifier and occur within a short time window.\nsource: http:request\ntarget: risk:incident\nassessment_mode: candidate_assessment\nassessment:\n  claim: indicates\n  basis: assessed\n  scope: incident_level\n  subject_role: observation\n  object_role: incident\nassessment_requirements:\n- \"Bind the observation subject to the recorded ad request; retain the downstream request chain as supporting evidence, including request times, source-scoped identifiers, collection provenance, and evidence paths.\"\n- \"Bind the incident object to an independently identified incident, and verify that the downstream endpoint is associated with that incident during the observation window; do not invent an incident from the match.\"\n- \"Verify device or session continuity and the bounded event sequence using source-specific identifier semantics; address identifier rotation, collisions, shared devices, replay, and clock uncertainty.\"\n- \"Require independent endpoint, file, or browser evidence corroborating the connection from the observed request chain to malicious delivery or execution in that incident; address normal redirects, ad verification, analytics, tracking pixels, and shared vendor infrastructure as alternative explanations.\"\n- \"Use the compatible hint only as a candidate assessment shape after these requirements are evaluated; downstream evidence review, contradictions, confidence, and acceptance policy remain separate, and the match alone establishes neither infection nor actor attribution.\"\nhops:\n- via: carries_identifier\n  direction: out\n  form: adtech:identifier\n- via: seen_in\n  direction: in\n  form: http:request\n- via: reaches\n  direction: out\n  form: inet:url\n- via: associated_with\n  direction: out\n  form: risk:incident\nconstraints:\n  temporal:\n    order:\n    - ad_request.seen <= downstream_request.seen\n    window_days: 1\n  sequence:\n    max_gap_seconds: 10\n    min_events: 2\n  degree_caps:\n    adtech:identifier: 500\n    inet:url: 1000\n  negative_nodes:\n  - form: inet:fqdn\n    list: commodity_ad_verification_pixels\n  - form: inet:fqdn\n    list: high_volume_ad_exchange_endpoints\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- identifier_continuity\n- seconds_between_events\n- downstream_endpoint_risk\n- publisher_context\n- user_agent_consistency\n- geo_consistency\n- path_count_capped\n- negative_pixel_penalty\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- proxy_logs\n- browser_telemetry\n- cti_reports\n- adtech_logs\n",
  "ADTECH_IMPRESSION_ID_REUSE_CLUSTER": "id: ADTECH_IMPRESSION_ID_REUSE_CLUSTER\nversion: 0.2.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: ownership_signal\nhazards:\n- 'Impression IDs can be propagated through legitimate verification, billing, or analytics partners without implying operator control.'\n- 'Malformed URL parsing can overcluster unrelated impressions if parameter boundaries are not normalized.'\n- 'Shared tracking vendors, redirects, and common verification pixels can create false reuse; corroborate with additional campaign evidence.'\ncapability_requirements:\n  required:\n  - 'web_request_telemetry'\n  - 'adtech_identifier_normalization'\n  optional:\n  - 'browser_client_uid_normalization'\n  - 'campaign_context_enrichment'\nreview:\n  last_reviewed: '2026-05-20'\n  review_cadence_days: 90\n  next_review: '2026-08-18'\nname: Impression ID Reuse -> Ad-Tech Domain Cluster\ncategory: ADTECH\ndescription: Cluster domains, analytics endpoints, and campaign surfaces that carry the same ad impression or auction identifier.\nsource: adtech:impression:id\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: observed_in\n  direction: in\n  form: inet:url\n- via: hosted_by\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - impression.firstseen <= fqdn.seen\n    window_days: 30\n  degree_caps:\n    adtech:impression:id: 200\n    inet:fqdn: 1000\n  negative_nodes:\n  - form: inet:fqdn\n    list: known_measurement_vendors\n  - form: inet:fqdn\n    list: high_volume_ad_exchange_endpoints\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- exact_identifier_match\n- domain_role_diversity\n- path_count_capped\n- first_seen_delta\n- publisher_overlap\n- campaign_parameter_overlap\n- measurement_vendor_penalty\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- proxy_logs\n- url_corpus\n- adtech_logs\n- cti_reports\n",
  "ADTECH_PIPELINE_PHASE_MISMATCH": "id: ADTECH_PIPELINE_PHASE_MISMATCH\nversion: 0.3.0\npattern_schema_version: 1.6\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: multi_hop_inference\nhazards:\n- Domain names often reflect legacy product names rather than current ad-pipeline\n  function.\n- Some exchanges intentionally reuse event, prebid, or creative endpoints across multiple\n  phases.\n- Shared vendors, CDNs, redirects, and common tracking endpoints can create false\n  phase mismatches; corroborate with observed request flow.\ncapability_requirements:\n  required:\n  - web_request_telemetry\n  - endpoint_role_classification\n  - semantic_execution_contract_v1\n  - preserved_request_correspondence\n  - source_qualified_endpoint_roles\n  - exact_content_hash_reproduction\n  - scoped_control_evaluation\n  optional:\n  - web_fingerprinting\n  - phase_classification\nname: Ad Pipeline Phase Mismatch\ncategory: ADTECH\ndescription: Compare one actual request phase with source-qualified endpoint roles\n  under an explicit preserved rule. Mismatch, compatible and contested witnesses remain\n  distinct; no accepted risk assessment is constructed.\nsource: http:request\ntarget: risk:observation|evidence:phase_comparison\nassessment_mode: evidence_only\nhops:\n- via: yields_evidence_for\n  direction: out\n  form: risk:observation|evidence:phase_comparison\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- browser_telemetry\n- proxy_logs\n- adtech_logs\n- url_corpus\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/ADTECH_PIPELINE_PHASE_MISMATCH.json\n  sha256: 855983c7cb4052fc9b2f4e1620140b546ed38ae40774f48c6fd0de3b4e6d3a77\n",
  "ADTECH_RTB_URL_PARAMS_TO_CAMPAIGN_CLUSTER": "id: ADTECH_RTB_URL_PARAMS_TO_CAMPAIGN_CLUSTER\nversion: 0.2.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: multi_hop_inference\nhazards:\n- 'Campaign, DSP, auction, and device parameters can be opaque vendor-local IDs that collide across platforms.'\n- 'Precise geolocation parameters may be estimated, rounded, or inherited from upstream bid streams rather than directly selected by the advertiser.'\n- 'Shared vendor namespaces, redirects, and tracking macros can create false parameter clusters; corroborate with advertiser and campaign evidence.'\ncapability_requirements:\n  required:\n  - 'web_request_telemetry'\n  - 'query_parameter_normalization'\n  optional:\n  - 'browser_client_uid_normalization'\n  - 'campaign_context_enrichment'\nname: RTB URL Parameters -> Campaign Cluster\ncategory: ADTECH\ndescription: Cluster ad-tech requests into candidate campaigns using recurring RTB query parameters such as campaign IDs, DSP IDs, impression IDs, device IDs, location, OS, browser, and auction fields.\nsource: inet:url\ntarget: risk:campaign\nassessment_mode: evidence_only\nhops:\n- via: has_query_param\n  direction: out\n  form: url:query:param\n- via: groups\n  direction: out\n  form: adtech:campaign:key\n- via: observed_as\n  direction: in\n  form: risk:campaign\nconstraints:\n  temporal:\n    order:\n    - request.firstseen <= campaign.lastseen\n    window_days: 90\n  degree_caps:\n    url:query:param: 5000\n    adtech:campaign:key: 1000\n  negative_nodes:\n  - form: url:query:param\n    list: generic_cachebuster_params\n  - form: inet:fqdn\n    list: high_volume_ad_exchange_endpoints\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- campaign_id_match\n- dsp_id_match\n- impression_id_overlap\n- device_id_overlap\n- geo_parameter_consistency\n- os_browser_consistency\n- auction_id_overlap\n- publisher_overlap\n- param_entropy\n- generic_param_penalty\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- proxy_logs\n- browser_telemetry\n- adtech_logs\n- url_corpus\n",
  "ADTECH_WEBAPP_SOURCEMAP_TO_ADMIN_SURFACE": "id: ADTECH_WEBAPP_SOURCEMAP_TO_ADMIN_SURFACE\nversion: 0.3.0\npattern_schema_version: 1.6\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Exposed JavaScript bundles and source maps can identify benign SaaS administration surfaces.'\n- 'Recovered route names are evidence of application capability, not proof that the surface is used in a specific operation.'\n- 'Shared SaaS vendors, CDNs, and common admin-route names can create false matches; corroborate with tenant-specific artifacts.'\ncapability_requirements:\n  required:\n  - web_fingerprinting\n  - web_script_extraction\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - dynamic_rendering\n  - route_recovery\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 96\n  next_review: '2026-08-30'\nname: Webapp Source Map -> Admin Surface\ncategory: ADTECH\ndescription: Return source-qualified routes recovered from preserved artifacts, with\n  explicit bundle/map content correspondence for referenced artifacts. An administrative\n  surface additionally requires interface-role evidence; a route alone does not prove\n  reachability or administration.\nsource: web:asset\ntarget: web:route|web:admin:surface\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/ADTECH_WEBAPP_SOURCEMAP_TO_ADMIN_SURFACE.json\n  sha256: 03f4585892a9c7e7af7e18449dafbd61abbf7eca79b78ef56d9b6940c322b9c1\nhops:\n- via: references\n  direction: out\n  form: web:asset\n- via: exposes_route\n  direction: out\n  form: web:route\n- via: belongs_to\n  direction: out\n  form: web:admin:surface\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- osint_web\n- url_corpus\n- web_crawl\n- cti_reports\n",
  "CROSS_CLOUD_ACCOUNT_TO_DOMAIN_INFRA": "id: CROSS_CLOUD_ACCOUNT_TO_DOMAIN_INFRA\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Shared reseller, MSP, or umbrella cloud accounts can host assets for unrelated tenants.'\n- 'Infrastructure expansion from parent-account data should be corroborated with billing, admin, or deployment evidence.'\ncapability_requirements:\n  required:\n  - 'cloud_control_telemetry'\n  - 'cloud_asset_inventory'\n  optional:\n  - 'dns_public_lookup'\n  - 'passive_dns'\n  - 'cloud_audit_log_access'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 90\n  next_review: '2026-08-24'\nname: Cloud Account -> Domain or Infra\ncategory: CROSS\ndescription: Expand from a parent cloud account or project to the domains and infrastructure it operates through owned services and assets.\nsource: cloud:account\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: owns\n  direction: out\n  form: cloud:bucket|cloud:service\n- via: referenced_by|hosts\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - account.firstseen <= asset.firstseen <= infra.seen\n    window_days: 1825\n  degree_caps:\n    cloud:account: 5000\n  negative_nodes:\n  - form: cloud:account\n    list: shared_platform_cloud_accounts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cloud_asset_inventory\n- pdns\n- osint_web\n",
  "CROSS_FQDN_TO_ORG_LEI": "id: CROSS_FQDN_TO_ORG_LEI\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: domain_expansion\nhazards:\n- 'RDAP and corporate registry data can be stale, privacy-filtered, or registrar-noisy.'\n- 'Legal-entity resolution may identify an intermediary, hoster, or service provider rather than the operational controller.'\n- 'Common registrant strings and shared service-provider records require corroboration with current RDAP and LEI evidence before clustering.'\ncapability_requirements:\n  required:\n  - 'rdap_enrichment'\n  - 'lei_resolution'\n  optional:\n  - 'registrar_reseller_context'\n  - 'privacy_service_suppression'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 97\n  next_review: '2026-08-31'\nname: FQDN -> Org -> LEI\ncategory: CROSS\ndescription: Resolve a domain to an identified legal entity record without requiring a sanctions overlay.\nsource: inet:fqdn\ntarget: lei:record\nassessment_mode: evidence_only\nhops:\n- via: registered_to\n  direction: out\n  form: org:org\n- via: identified_by\n  direction: out\n  form: lei:record\nconstraints:\n  temporal:\n    order:\n    - fqdn.created <= org.seen <= lei.issued\n    window_days: 3650\n  degree_caps:\n    inet:fqdn: 10000\n  negative_nodes:\n  - form: org:org\n    list: privacy_redacted_registrants\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- rdap\n- lei\n",
  "CTI_ACTIVE_C2_PROTOCOL_RESPONSE_TO_CONTROLLERS": "id: CTI_ACTIVE_C2_PROTOCOL_RESPONSE_TO_CONTROLLERS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: multi_hop_inference\nhazards:\n- 'Active protocol probes require authorization, scope control, and careful rate limiting; the pattern only models the observed relationship.'\n- 'Protocol emulation can trigger decoys, sinkholes, honeypots, middleboxes, or replayed responses that do not represent an operator-controlled controller.'\n- 'A matching response is infrastructure evidence, not actor attribution.'\n- 'Common or default protocol banners and shared test infrastructure can produce false matches; corroborate with independent malware or network evidence.'\ncapability_requirements:\n  required:\n  - 'active_protocol_probe_result_normalization'\n  - 'controller_endpoint_extraction'\n  optional:\n  - 'payload_decoding'\n  - 'sinkhole_honeypot_suppression'\n  - 'internet_scan_archive_lookup'\nname: Active C2 Protocol Response -> Controllers\ncategory: CTI\ndescription: Pivot from a normalized active protocol probe response to controller endpoints that emitted the same distinctive response or handshake.\nsource: network:service:probe_response\ntarget: inet:ipv4|inet:fqdn|inet:url\nassessment_mode: evidence_only\nhops:\n- via: emitted_by\n  direction: out\n  form: network:service\n- via: hosted_at\n  direction: out\n  form: inet:ipv4|inet:fqdn|inet:url\nconstraints:\n  temporal:\n    order:\n    - probe.sent <= response.observed\n    window_days: 30\n  degree_caps:\n    network:service:probe_response: 10000\n    inet:ipv4: 10000\n  negative_nodes:\n  - form: inet:ipv4\n    list: known_sinkholes_honeypots\n  - form: inet:fqdn\n    list: benign_protocol_testbeds\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- protocol_family\n- response_marker_rarity\n- temporal_consistency\n- sinkhole_penalty\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- active_discovery_results\n- internet_scan_archives\n- malware_analysis\n",
  "CTI_ACTIVE_C2_PROTOCOL_RESPONSE_TO_PAYLOADS": "id: CTI_ACTIVE_C2_PROTOCOL_RESPONSE_TO_PAYLOADS\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: multi_hop_inference\nhazards:\n- 'Decoded payloads can be generated by sandboxes, decoys, replay services, or defensive research infrastructure.'\n- 'A payload returned by a controller can be ephemeral and may not remain available for later verification.'\n- 'Protocol response reuse links observations, but it does not prove common operator control.'\ncapability_requirements:\n  required:\n  - active_protocol_probe_result_normalization\n  - payload_decoding\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - sample_hashing\n  - payload_family_classification\nname: Active C2 Protocol Response -> Payloads\ncategory: CTI\ndescription: Return preserved payload or configuration bytes evidenced as recovered\n  from a particular protocol response. Direct configuration, payload-derived configuration\n  and the payload hash have explicit bindings; a marker alone does not classify bytes\n  or prove maliciousness.\nsource: network:service:probe_response\ntarget: malware:payload|file:hash|malware:config\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_ACTIVE_C2_PROTOCOL_RESPONSE_TO_PAYLOADS.json\n  sha256: d14e09a0f11eb4b7c682b8eae04e61d6a8c21fb9227d104229fe169ec31361cf\nhops:\n- via: contains_payload\n  direction: out\n  form: malware:payload\n- via: hashes_to\n  direction: out\n  form: file:hash\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- active_discovery_results\n- malware_analysis\n- file_reputation\n",
  "CTI_AUTH_SESSION_TO_DOMAINS": "id: CTI_AUTH_SESSION_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Authentication-session pivots must stay time-bounded; a domain touched during auth is not proof of account ownership or actor control.'\n- 'Auth-session domains can include common or shared identity providers, redirects, CDNs, captive portals, telemetry beacons, and security-product probes, so corroborating request role is required.'\n- 'Session-to-domain expansion should retain request role and timing so benign login infrastructure is not clustered as adversary infrastructure.'\ncapability_requirements:\n  required:\n  - 'auth_session_telemetry'\n  - 'domain_normalization'\n  optional:\n  - 'redirect_chain_extraction'\n  - 'identity_provider_domain_suppression'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 98\n  next_review: '2026-09-01'\nname: Auth Session -> Domains\ncategory: CTI\ndescription: Pivot from a bounded authentication session to domains observed during that session.\nsource: auth:session\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: touched_domain\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - auth_session.started <= domain.observed <= auth_session.ended\n    window_days: 1\n  degree_caps:\n    auth:session: 1000000\n    inet:fqdn: 1000000\n  negative_nodes:\n  - form: inet:fqdn\n    list: identity_provider_or_sso_domains\n  - form: inet:fqdn\n    list: common_cdn_domains\n  - form: inet:fqdn\n    list: captive_portal_or_probe_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- request_role\n- redirect_depth\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- auth_logs\n- proxy_logs\n- dns\n",
  "CTI_AUTH_SESSION_TO_IDENTITIES": "id: CTI_AUTH_SESSION_TO_IDENTITIES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: domain_expansion\nhazards:\n- 'Authentication sessions can be reused, merged, replayed, or associated with multiple identities through shared accounts, delegated access, and service principals.'\n- 'A session-to-identity join is account telemetry context, not proof that a human user controlled every event in the session.'\n- 'Session identifiers must remain time-bounded and source-scoped to avoid joining unrelated authentication records.'\ncapability_requirements:\n  required:\n  - 'auth_session_telemetry'\n  - 'identity_uid_normalization'\n  optional:\n  - 'service_principal_classification'\n  - 'delegated_access_context'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 90\n  next_review: '2026-08-24'\nname: Auth Session -> Identities\ncategory: CTI\ndescription: Pivot from a bounded authentication session to normalized user or principal identities associated with that session.\nsource: auth:session\ntarget: identity:user:uid\nassessment_mode: evidence_only\nhops:\n- via: associated_identity\n  direction: out\n  form: identity:user:uid\nconstraints:\n  temporal:\n    order:\n    - auth_session.started <= identity.observed <= auth_session.ended\n    window_days: 1\n  degree_caps:\n    auth:session: 1000000\n    identity:user:uid: 100000\n  negative_nodes:\n  - form: identity:user:uid\n    list: shared_or_service_accounts\n  - form: auth:session\n    list: stale_or_merged_session_records\n  - form: auth:session\n    list: synthetic_or_healthcheck_sessions\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- auth_method\n- principal_role\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- auth_logs\n- identity\n",
  "CTI_C2_CERT_TO_SAMPLE_CLUSTER": "id: CTI_C2_CERT_TO_SAMPLE_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_C2_CERT_TO_SAMPLE_CLUSTER.json\n  sha256: 45465eabb9136cf39a864c303e9b37de198905c441a1d85a7dc4a157e0588b57\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: multi_hop_inference\nhazards:\n- An attributable sample-associated certificate encounter and a separately supported\n  endpoint-mediated lead have different claims. A scanner observation or report co-mention\n  cannot supply an encounter.\n- Exact whole-artifact sample identity, actual sample execution/connection attribution,\n  certificate role and service or explicitly narrower address correspondence remain\n  required.\n- The selected UTC period concerns established finding availability in a named collection\n  with preserved history. Old activity remains old, and replay or renamed normalized\n  records do not refresh an equivalent finding.\n- Shared material, laboratory provenance and the C2 label establish no malicious function,\n  common actor, control, confidence or accepted assessment. Controlled-occurrence\n  and shared-certificate exclusions are explicit query choices.\ncapability_requirements:\n  required:\n  - semantic_evidence_v1\n  - certificate_normalization\n  - whole_artifact_identity\n  - attributable_sample_connection_evidence\n  - finding_history_v1\n  optional:\n  - collection_knowledge_witnesses\n  - source_classification_evidence\n  - malware_sandbox_summary\n  - tls_scanning\n  - controlled_occurrence_evidence\nname: Certificate Encounter or Endpoint-Mediated Lead → Sample Findings\ncategory: CTI\ndescription: Collection-scoped first availability of separately supported sample encounters\n  and endpoint-mediated leads. Actual event dates remain separate; a later scan alone\n  is never a sample encounter.\nsource: x509:cert\ntarget: file:bytes\nassessment_mode: evidence_only\nhops:\n- via: observed_certificate_presentation\n  direction: out\n  form: inet:service\n- via: attributable_sample_encounter_or_declared_endpoint_lead\n  direction: in\n  form: file:bytes\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- sandbox\n- tls_scans\n- pdns\n",
  "CTI_CLOUD_APP_ID_TO_AUTH_EVENTS": "id: CTI_CLOUD_APP_ID_TO_AUTH_EVENTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: domain_expansion\nhazards:\n- 'Application identifiers can represent legitimate multi-tenant applications, first-party services, delegated apps, or attacker-created resources.'\n- 'Auth events can reflect testing, consent, token replay, service activity, or benign automation rather than direct user action.'\n- 'An app ID to auth-event join is not proof of application ownership or compromise.'\n- 'Common first-party or shared SaaS application IDs can produce false joins; corroborate with tenant-specific consent and timing.'\ncapability_requirements:\n  required:\n  - 'cloud_application_identifier_normalization'\n  - 'auth_event_telemetry'\n  optional:\n  - 'consent_event_telemetry'\n  - 'service_principal_inventory'\n  - 'first_party_app_suppression'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 90\n  next_review: '2026-08-24'\nname: Cloud App ID -> Auth Events\ncategory: CTI\ndescription: Pivot from a normalized cloud or OAuth application identifier to authentication, consent, or token-use events involving that application.\nsource: cloud:application:uid|oauth:application:uid\ntarget: auth:event\nassessment_mode: evidence_only\nhops:\n- via: observed_in_auth_event\n  direction: out\n  form: auth:event\nconstraints:\n  temporal:\n    order:\n    - application.observed <= auth_event.observed\n    window_days: 90\n  degree_caps:\n    cloud:application:uid: 100000\n    auth:event: 1000000\n  negative_nodes:\n  - form: cloud:application:uid\n    list: common_first_party_or_managed_apps\n  - form: auth:event\n    list: expected_service_automation_events\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- tenant_diversity\n- user_diversity\n- first_party_app_penalty\n- consent_context\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- auth_logs\n- cloud_audit_logs\n- cloud_inventory\n",
  "CTI_EMAIL_ATTACHMENT_HASH_TO_MESSAGES": "id: CTI_EMAIL_ATTACHMENT_HASH_TO_MESSAGES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Mail attachment pivots can be inflated by forwarding, detonation, bulk mail, shared mailboxes, and rewritten attachment metadata.'\n- 'Common documents, logos, signatures, invoices, and benign software attachments can connect unrelated messages.'\n- 'Attachment reuse is message evidence, not actor attribution; corroborate with sender, recipient, timing, and file context.'\ncapability_requirements:\n  required:\n  - 'mail_attachment_telemetry'\n  - 'file_hash_normalization'\n  optional:\n  - 'message_trace_join'\n  - 'detonation_artifact_suppression'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 90\n  next_review: '2026-08-24'\nname: Email Attachment Hash -> Messages\ncategory: CTI\ndescription: Pivot from a normalized attachment file hash to email messages where that attachment was observed.\nsource: file:hash\ntarget: email:message\nassessment_mode: evidence_only\nhops:\n- via: attached_to\n  direction: out\n  form: email:message\nconstraints:\n  temporal:\n    order:\n    - file.firstseen <= message.received\n    window_days: 365\n  degree_caps:\n    file:hash: 1000000\n    email:message: 1000000\n  negative_nodes:\n  - form: file:hash\n    list: common_benign_attachment_hashes\n  - form: email:message\n    list: bulk_or_newsletter_messages\n  - form: email:message\n    list: detonation_generated_messages\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- attachment_count\n- sender_recipient_context\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- malware_corpus\n- sandbox\n",
  "CTI_EMAIL_EMBEDDED_URL_TO_MESSAGES": "id: CTI_EMAIL_EMBEDDED_URL_TO_MESSAGES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Common embedded URLs such as unsubscribe endpoints, social links, image CDNs, and sender infrastructure can appear in unrelated messages.'\n- 'URL normalization choices can overjoin messages when query parameters, fragments, or protection wrappers are stripped too aggressively.'\ncapability_requirements:\n  required:\n  - 'email_url_extraction'\n  - 'url_normalization'\n  optional:\n  - 'campaign_message_clustering'\n  - 'protected_url_decoding'\nname: Embedded URL -> Email Messages\ncategory: CTI\ndescription: Pivot from an embedded URL to email messages that contained it, retaining normalized and raw URL forms.\nsource: inet:url\ntarget: email:message\nassessment_mode: evidence_only\nhops:\n- via: embedded_in\n  direction: out\n  form: email:message\nconstraints:\n  temporal:\n    order:\n    - url.firstseen <= message.received\n    window_days: 365\n  degree_caps:\n    inet:url: 100000\n  negative_nodes:\n  - form: inet:url\n    list: high_volume_email_service_urls\n  - form: inet:fqdn\n    list: common_marketing_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- url_normalization_level\n- tenant_spread\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- url_corpus\n",
  "CTI_EMAIL_FINAL_URL_TO_MESSAGES": "id: CTI_EMAIL_FINAL_URL_TO_MESSAGES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Final URLs can vary by time, geography, user agent, authentication state, or security-sandbox handling.'\n- 'Final destinations may be benign shared services or interstitials rather than adversary-controlled infrastructure.'\ncapability_requirements:\n  required:\n  - 'redirect_resolution'\n  - 'message_trace_join'\n  optional:\n  - 'protected_url_decoding'\n  - 'browser_sandbox_resolution'\nname: Email Final URL -> Messages\ncategory: CTI\ndescription: Pivot from a click-time or detonation-resolved final URL to email messages and original embedded URLs that reached it.\nsource: email:final_url\ntarget: email:message|inet:url\nassessment_mode: evidence_only\nhops:\n- via: resolved_from\n  direction: out\n  form: inet:url\n- via: embedded_in\n  direction: out\n  form: email:message\nconstraints:\n  temporal:\n    order:\n    - message.received <= final_url.observed\n    window_days: 90\n  degree_caps:\n    email:final_url: 100000\n  negative_nodes:\n  - form: inet:fqdn\n    list: common_url_redirectors\n  - form: inet:fqdn\n    list: benign_shared_landing_services\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- redirect_chain_depth\n- final_url_stability\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- mail_click_telemetry\n- url_corpus\n",
  "CTI_EMAIL_FIRST_HOP_MTA_TO_MESSAGES": "id: CTI_EMAIL_FIRST_HOP_MTA_TO_MESSAGES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Shared mail relays, cloud mail platforms, mailing lists, and security gateways can connect many unrelated messages.'\n- 'First-hop MTA observations can be rewritten or normalized differently across mail telemetry sources.'\n- 'Message expansion from an MTA must use time windows and degree caps to avoid overjoining campaigns.'\ncapability_requirements:\n  required:\n  - 'mailflow_header_normalization'\n  - 'message_identifier_normalization'\n  optional:\n  - 'bulk_sender_suppression'\n  - 'tenant_or_recipient_domain_filtering'\n  - 'relay_chain_parsing'\nname: First-Hop MTA -> Email Messages\ncategory: CTI\ndescription: Pivot from a first-hop mail transfer agent IP or host to email messages observed using that relay within a bounded window.\nsource: inet:ipv4|inet:fqdn\ntarget: email:message\nassessment_mode: evidence_only\nhops:\n- via: first_hop_mta_for\n  direction: in\n  form: email:message\nconstraints:\n  temporal:\n    order:\n    - mta.observed <= message.received\n    window_days: 14\n  degree_caps:\n    inet:ipv4: 100000\n    email:message: 100000\n  negative_nodes:\n  - form: inet:ipv4\n    list: common_bulk_mail_relays\n  - form: inet:fqdn\n    list: managed_mail_gateway_hosts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- message_count\n- recipient_domain_diversity\n- sender_domain_diversity\n- bulk_sender_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- dns\n- asn_registry\n",
  "CTI_EMAIL_MESSAGE_TO_EMBEDDED_URLS": "id: CTI_EMAIL_MESSAGE_TO_EMBEDDED_URLS\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: domain_expansion\nhazards:\n- 'Marketing, notification, and newsletter emails can contain many benign tracking, unsubscribe, image, and CDN URLs.'\n- 'Security gateways may rewrite or enrich URLs, so extraction must distinguish original message content from protected or detonation-added links.'\n- 'Common tracking and CDN links should be suppressed or corroborated before treating URL overlap as meaningful.'\ncapability_requirements:\n  required:\n  - email_url_extraction\n  - url_normalization\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - message_body_parsing\n  - protected_url_decoding\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 90\n  next_review: '2026-08-24'\nname: Email Message -> Embedded URLs\ncategory: CTI\ndescription: Return URLs actually contained in a particular preserved message representation.\n  Gateway rewrites may qualify as contained URLs; decoded originals and later navigation\n  destinations require their own evidence relations.\nsource: email:message\ntarget: inet:url\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_EMAIL_MESSAGE_TO_EMBEDDED_URLS.json\n  sha256: b40d6ab7f60483546b7712ede173eeb1b02a33f450439f60d0d48c938712cd82\nhops:\n- via: contains_url\n  direction: out\n  form: inet:url\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- mail_telemetry\n- url_corpus\n",
  "CTI_EMAIL_MESSAGE_TO_FIRST_HOP_MTA": "id: CTI_EMAIL_MESSAGE_TO_FIRST_HOP_MTA\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: domain_expansion\nhazards:\n- 'First-hop MTA fields can be absent, rewritten, spoofed, relayed, or hidden by mail gateways and privacy controls.'\n- 'Bulk senders, mailing lists, and shared relays can produce high-degree benign joins.'\n- 'An MTA IP observed in mailflow is not proof of sender identity or actor control.'\ncapability_requirements:\n  required:\n  - 'mailflow_header_normalization'\n  - 'ip_normalization'\n  optional:\n  - 'relay_chain_parsing'\n  - 'bulk_sender_suppression'\n  - 'asn_enrichment'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 90\n  next_review: '2026-08-24'\nname: Email Message -> First-Hop MTA\ncategory: CTI\ndescription: Pivot from a normalized email message to the first-hop mail transfer agent IP or host observed for that message.\nsource: email:message\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: first_hop_mta\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - message.received <= mta.observed\n    window_days: 7\n  degree_caps:\n    email:message: 5000\n    inet:ipv4: 100000\n  negative_nodes:\n  - form: inet:ipv4\n    list: common_bulk_mail_relays\n  - form: inet:fqdn\n    list: managed_mail_gateway_hosts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- relay_position\n- asn_context\n- bulk_sender_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- dns\n- asn_registry\n",
  "CTI_EMAIL_ORIGINATING_IP_TO_MESSAGES": "id: CTI_EMAIL_ORIGINATING_IP_TO_MESSAGES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Originating IP headers can be spoofed, stripped, rewritten, or unavailable depending on the mail path and privacy controls.'\n- 'VPNs, proxies, NAT, compromised hosts, and shared senders can connect unrelated messages to one IP.'\n- 'An originating IP match is delivery-path evidence, not proof of sender identity.'\ncapability_requirements:\n  required:\n  - 'mailflow_header_normalization'\n  - 'originating_ip_extraction'\n  optional:\n  - 'proxy_vpn_suppression'\n  - 'sender_domain_filtering'\n  - 'asn_enrichment'\nname: Email Originating IP -> Messages\ncategory: CTI\ndescription: Pivot from an email-originating IP address to messages that expose the same originating IP in normalized mailflow telemetry.\nsource: inet:ipv4\ntarget: email:message\nassessment_mode: evidence_only\nhops:\n- via: originating_ip_for\n  direction: in\n  form: email:message\nconstraints:\n  temporal:\n    order:\n    - ip.observed <= message.received\n    window_days: 30\n  degree_caps:\n    inet:ipv4: 50000\n    email:message: 100000\n  negative_nodes:\n  - form: inet:ipv4\n    list: common_vpn_proxy_egress\n  - form: inet:ipv4\n    list: common_bulk_mail_relays\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- sender_domain_diversity\n- recipient_domain_diversity\n- vpn_proxy_penalty\n- bulk_sender_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- asn_registry\n- proxy_reputation\n",
  "CTI_EMAIL_PROTECTED_URL_CLICK_TO_USERS": "id: CTI_EMAIL_PROTECTED_URL_CLICK_TO_USERS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: domain_expansion\nhazards:\n- 'Security scanners, link detonation systems, prefetchers, and mailbox protection services can generate click telemetry that does not represent user action.'\n- 'Shared mailboxes, aliases, forwarding, and delegated access can obscure which human actually clicked a URL.'\ncapability_requirements:\n  required:\n  - 'protected_url_click_telemetry'\n  - 'identity_normalization'\n  optional:\n  - 'security_scanner_filtering'\n  - 'message_trace_join'\nname: Protected URL Click -> Users\ncategory: CTI\ndescription: Pivot from a protected email URL click event to the user identity and message context associated with the click.\nsource: email:url_click\ntarget: identity:user|email:message\nassessment_mode: evidence_only\nhops:\n- via: clicked_by\n  direction: out\n  form: identity:user\n- via: associated_message\n  direction: out\n  form: email:message\nconstraints:\n  temporal:\n    order:\n    - message.received <= click.observed\n    window_days: 90\n  degree_caps:\n    email:url_click: 1000\n    identity:user: 100000\n  negative_nodes:\n  - form: identity:user\n    list: automated_security_mailboxes\n  - form: email:url_click\n    list: security_scanner_clicks\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- user_action_confidence\n- scanner_penalty\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_click_telemetry\n- identity\n- mail_telemetry\n",
  "CTI_EMAIL_URL_COMPONENT_HASH_CLUSTER": "id: CTI_EMAIL_URL_COMPONENT_HASH_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'URL component hashes can overcluster benign services when generic paths, empty queries, tracking parameters, or CDN paths dominate.'\n- 'Canonicalization differences across products can make equivalent URLs fail to match or unrelated URLs collide after aggressive normalization.'\ncapability_requirements:\n  required:\n  - 'url_canonicalization'\n  - 'email_url_extraction'\n  optional:\n  - 'redirect_resolution'\n  - 'campaign_message_clustering'\nname: Email URL Component Hash -> URL Cluster\ncategory: CTI\ndescription: Cluster embedded or final email URLs by normalized component hashes such as canonical URL, host, path, query, or final URL hash.\nsource: url:component_hash\ntarget: inet:url|email:message\nassessment_mode: evidence_only\nhops:\n- via: component_of\n  direction: out\n  form: inet:url\n- via: embedded_in\n  direction: out\n  form: email:message\nconstraints:\n  temporal:\n    order:\n    - component_hash.firstseen <= url.firstseen <= message.received\n    window_days: 365\n  degree_caps:\n    url:component_hash: 100000\n  negative_nodes:\n  - form: url:component_hash\n    list: generic_url_component_hashes\n  - form: inet:fqdn\n    list: common_marketing_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- component_specificity\n- normalization_level\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- url_corpus\n",
  "CTI_ENDPOINT_FILE_ORIGIN_URL_TO_FILES": "id: CTI_ENDPOINT_FILE_ORIGIN_URL_TO_FILES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: domain_expansion\nhazards:\n- 'File origin metadata can be missing, copied, spoofed, inherited from referrers, or rewritten by browsers and download managers.'\n- 'Common software CDNs and update endpoints can connect unrelated files and endpoints unless provider controls are applied.'\ncapability_requirements:\n  required:\n  - 'endpoint_file_origin_telemetry'\n  - 'file_hash_normalization'\n  optional:\n  - 'mark_of_the_web_parsing'\n  - 'download_referrer_extraction'\nname: Endpoint File Origin URL -> Files\ncategory: CTI\ndescription: Pivot from endpoint file-origin URL metadata to downloaded files, file paths, and endpoint identities.\nsource: file:origin:url\ntarget: file:bytes|file:path|endpoint:uid\nassessment_mode: evidence_only\nhops:\n- via: downloaded_as\n  direction: out\n  form: file:bytes\n- via: observed_at\n  direction: out\n  form: file:path|endpoint:uid\nconstraints:\n  temporal:\n    order:\n    - origin_url.observed <= file.created\n    window_days: 30\n  degree_caps:\n    file:origin:url: 100000\n  negative_nodes:\n  - form: inet:fqdn\n    list: common_software_cdn_domains\n  - form: file:origin:url\n    list: browser_internal_urls\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- endpoint_spread\n- referrer_consistency\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- edr\n- endpoint\n- proxy_logs\n",
  "CTI_ENDPOINT_UID_TO_DEVICE_UID_CLUSTER": "id: CTI_ENDPOINT_UID_TO_DEVICE_UID_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: ownership_signal\nhazards:\n- 'Endpoint and device identifiers can reset, collide, be scrubbed, be cloned across images, or represent different identity layers in different sources.'\n- 'Device UID clustering is many-to-many and needs degree caps, noisy-ID suppression, and cross-source provenance before promotion.'\n- 'A shared endpoint or device UID cluster is not actor attribution and should be corroborated with independent endpoint or identity evidence.'\ncapability_requirements:\n  required:\n  - 'endpoint_identity_normalization'\n  - 'device_identity_mapping'\n  optional:\n  - 'asset_inventory_join'\n  - 'edr_device_identity_resolution'\n  - 'image_clone_detection'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 90\n  next_review: '2026-08-24'\nname: Endpoint UID -> Device UID Cluster\ncategory: CTI\ndescription: Pivot from a normalized endpoint identifier to device-level identifiers that may group endpoint telemetry across identity namespaces.\nsource: endpoint:uid\ntarget: device:uid\nassessment_mode: evidence_only\nhops:\n- via: maps_to_device_uid\n  direction: out\n  form: device:uid\nconstraints:\n  temporal:\n    order:\n    - endpoint.observed <= device_identity.observed\n    window_days: 365\n  degree_caps:\n    endpoint:uid: 100000\n    device:uid: 100000\n  negative_nodes:\n  - form: device:uid\n    list: default_or_null_device_identifiers\n  - form: device:uid\n    list: cloned_image_device_identifiers\n  - form: endpoint:uid\n    list: shared_kiosk_or_lab_endpoints\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- identity_namespace_count\n- clone_indicator\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- edr\n- endpoint\n- asset_inventory\n",
  "CTI_ENDPOINT_UID_TO_DNS_CACHE_NAMES": "id: CTI_ENDPOINT_UID_TO_DNS_CACHE_NAMES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Endpoint DNS cache and recent-resolution data can include prefetches, retries, stale cache entries, captive portals, sinkholes, and benign shared services.'\n- 'Endpoint identifiers can reset, collide, be scrubbed, or represent different identity layers across telemetry sources.'\n- 'A DNS cache name observed on an endpoint is context for further investigation, not proof of actor control or intent.'\ncapability_requirements:\n  required:\n  - 'endpoint_dns_cache_telemetry'\n  - 'endpoint_identity_normalization'\n  optional:\n  - 'dns_query_deduplication'\n  - 'sinkhole_or_captive_portal_suppression'\nname: Endpoint UID -> DNS Cache Names\ncategory: CTI\ndescription: Pivot from a normalized endpoint identifier to DNS names observed in endpoint DNS cache or recent-resolution telemetry.\nsource: endpoint:uid\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: resolved_or_cached\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - endpoint.observed <= dns_cache.observed\n    window_days: 30\n  degree_caps:\n    endpoint:uid: 100000\n    inet:fqdn: 1000000\n  negative_nodes:\n  - form: inet:fqdn\n    list: captive_portal_or_probe_domains\n  - form: inet:fqdn\n    list: dns_sinkhole_or_blockpage_domains\n  - form: inet:fqdn\n    list: common_os_update_or_telemetry_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- cache_observation_type\n- dns_result_context\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- edr\n- endpoint\n- dns\n",
  "CTI_ENDPOINT_UID_TO_EGRESS_IPS": "id: CTI_ENDPOINT_UID_TO_EGRESS_IPS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Endpoint egress IPs are weak ownership evidence because NAT, VPN, proxy, corporate or shared egress, DHCP churn, and cloud-hosted workloads can overjoin unrelated endpoints without corroboration.'\n- 'Endpoint identifiers can reset, collide, be scrubbed, or represent different identity layers across telemetry sources.'\n- 'An endpoint-to-egress-IP observation is network context, not actor attribution or proof of endpoint ownership.'\ncapability_requirements:\n  required:\n  - 'endpoint_network_telemetry'\n  - 'endpoint_identity_normalization'\n  optional:\n  - 'proxy_chain_parsing'\n  - 'vpn_or_proxy_enrichment'\n  - 'egress_ip_suppression'\nname: Endpoint UID -> Egress IPs\ncategory: CTI\ndescription: Pivot from a normalized endpoint identifier to public IP addresses observed as endpoint egress or source IP context.\nsource: endpoint:uid\ntarget: inet:ipv4\nassessment_mode: evidence_only\nhops:\n- via: sourced_from\n  direction: out\n  form: inet:ipv4\nconstraints:\n  temporal:\n    order:\n    - endpoint.observed <= network.observed\n    window_days: 30\n  degree_caps:\n    endpoint:uid: 100000\n    inet:ipv4: 100000\n  negative_nodes:\n  - form: inet:ipv4\n    list: private_or_reserved_ranges\n  - form: inet:ipv4\n    list: high_volume_corporate_egress_ips\n  - form: inet:ipv4\n    list: known_vpn_proxy_or_tor_egress\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- source_ip_role\n- egress_context\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- edr\n- endpoint\n- proxy_logs\n- netflow\n",
  "CTI_ENDPOINT_UID_TO_FILE_PATHS": "id: CTI_ENDPOINT_UID_TO_FILE_PATHS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'File paths, directories, process names, and command-line fragments can be generic, localized, user-specific, copied, or privacy-sensitive.'\n- 'Endpoint file-path observations can reflect benign software layout, user profile naming, installer defaults, or temporary extraction paths.'\n- 'A shared path on an endpoint is context for follow-on file or process evidence, not actor attribution.'\ncapability_requirements:\n  required:\n  - 'endpoint_file_inventory'\n  - 'file_path_normalization'\n  optional:\n  - 'user_profile_path_minimization'\n  - 'process_context_join'\nname: Endpoint UID -> File Paths\ncategory: CTI\ndescription: Pivot from a normalized endpoint identifier to file paths observed on that endpoint.\nsource: endpoint:uid\ntarget: file:path\nassessment_mode: evidence_only\nhops:\n- via: observed_path\n  direction: out\n  form: file:path\nconstraints:\n  temporal:\n    order:\n    - endpoint.observed <= file_path.observed\n    window_days: 180\n  degree_caps:\n    endpoint:uid: 100000\n    file:path: 1000000\n  negative_nodes:\n  - form: file:path\n    list: default_os_or_program_paths\n  - form: file:path\n    list: temporary_extraction_or_cache_paths\n  - form: file:path\n    list: privacy_sensitive_user_profile_paths\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- path_depth\n- profile_scope\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- edr\n- endpoint\n",
  "CTI_FAVICON_HASH_CLUSTER": "id: CTI_FAVICON_HASH_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'Common frameworks, panel kits, and copied web templates reuse favicons widely across unrelated sites.'\n- 'Favicon hashes are exploratory and should be paired with infra, certificate, or content corroboration.'\ncapability_requirements:\n  required:\n  - 'web_fingerprinting'\n  - 'http_probe'\n  optional:\n  - 'passive_dns'\n  - 'tls_scanning'\nname: HTTP Favicon Hash → FQDN Cluster\ncategory: CTI\ndescription: Pivot by identical HTTP favicon hash to discover co-hosted panels or cloned kits.\nsource: web:site\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: http_favicon_hash\n  direction: out\n  form: hash:md5|hash:sha1\n- via: http_favicon_hash\n  direction: in\n  form: web:site\n- via: hosts\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - site.seen <= fqdn.seen\n    window_days: 365\n  degree_caps:\n    hash:md5: 5000\n  negative_nodes:\n  - form: web:site\n    list: popular_cms_default_icons\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- tls\n- osint_web\n- pdns\n- shodan_censys\n",
  "CTI_FILE_HASH_TO_ENDPOINT_UIDS": "id: CTI_FILE_HASH_TO_ENDPOINT_UIDS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'File-hash-to-endpoint pivots can reflect common benign software, shared installers, test files, or malware-sandbox artifacts.'\n- 'Prevalence and endpoint spread are context, not attribution; common files need suppression before clustering.'\n- 'Endpoint observations can be stale, deduplicated, or copied between telemetry products, so timing and source provenance must be retained.'\ncapability_requirements:\n  required:\n  - 'endpoint_file_inventory'\n  - 'file_hash_normalization'\n  optional:\n  - 'software_prevalence_enrichment'\n  - 'sandbox_artifact_suppression'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 90\n  next_review: '2026-08-24'\nname: File Hash -> Endpoint UIDs\ncategory: CTI\ndescription: Pivot from a normalized file hash to endpoint identifiers where the file was observed.\nsource: file:hash\ntarget: endpoint:uid\nassessment_mode: evidence_only\nhops:\n- via: observed_on\n  direction: out\n  form: endpoint:uid\nconstraints:\n  temporal:\n    order:\n    - file.firstseen <= endpoint.observed\n    window_days: 365\n  degree_caps:\n    file:hash: 1000000\n    endpoint:uid: 100000\n  negative_nodes:\n  - form: file:hash\n    list: common_benign_software_hashes\n  - form: file:hash\n    list: shared_installer_or_update_hashes\n  - form: endpoint:uid\n    list: malware_sandbox_or_lab_endpoints\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- endpoint_prevalence\n- software_reputation\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- edr\n- endpoint\n- malware_corpus\n",
  "CTI_FILE_REALPATH_CLUSTER": "id: CTI_FILE_REALPATH_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: multi_hop_inference\nhazards:\n- 'Runtime paths can be generic, installer-created, user-specific, localized, or inherited from shared tooling.'\n- 'Real paths can expose sensitive host or user details and should be normalized and minimized before publication.'\n- 'A shared path supports clustering only when paired with prevalence, temporal, and host-context controls.'\ncapability_requirements:\n  required:\n  - 'endpoint_file_path_telemetry'\n  - 'path_normalization'\n  optional:\n  - 'common_path_suppression'\n  - 'file_hash_enrichment'\n  - 'endpoint_context'\nname: File Real Path Cluster\ncategory: CTI\ndescription: Cluster file hashes or endpoint file observations that share the same normalized runtime or real filesystem path.\nsource: file:path\ntarget: file:hash|endpoint:file\nassessment_mode: evidence_only\nhops:\n- via: observed_at_path\n  direction: in\n  form: endpoint:file\n- via: hashes_to\n  direction: out\n  form: file:hash\nconstraints:\n  temporal:\n    order:\n    - path.observed <= file.observed\n    window_days: 180\n  degree_caps:\n    file:path: 10000\n    file:hash: 100000\n    endpoint:file: 1000000\n  negative_nodes:\n  - form: file:path\n    list: common_system_or_application_paths\n  - form: file:hash\n    list: common_benign_file_hashes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- normalized_path_depth\n- endpoint_diversity\n- common_path_penalty\n- prevalence\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- endpoint_telemetry\n- malware_analysis\n- file_reputation\n",
  "CTI_FILE_SOURCE_PATH_CLUSTER": "id: CTI_FILE_SOURCE_PATH_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'Source paths can be copied, templated, localized, redacted, or produced by common build systems.'\n- 'Paths can contain user names, project names, or sensitive local filesystem details and require minimization before publication.'\n- 'A shared source path is build-context evidence, not actor attribution.'\ncapability_requirements:\n  required:\n  - file_metadata_extraction\n  - path_normalization\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - pdb_path_extraction\n  - sample_prevalence_enrichment\nname: File Source Path Cluster\ncategory: CTI\ndescription: Find particular preserved files with a source-qualified extraction of\n  the selected path representation. The 365-day window uses first complete finding\n  availability; later analysis neither invents a new file sighting nor backdates path\n  knowledge.\nsource: file:source_path\ntarget: file:hash\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_FILE_SOURCE_PATH_CLUSTER.json\n  sha256: 8c9d1c52d1e2cb557264cf3aaf72a52302998adfe05ce5242b76fcebd000857c\nhops:\n- via: embedded_in_file\n  direction: in\n  form: file:hash\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- malware_analysis\n- file_reputation\n- endpoint_telemetry\n",
  "CTI_HASSH_FINGERPRINT_CLUSTER": "id: CTI_HASSH_FINGERPRINT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'Common SSH clients, libraries, automation frameworks, and scanning tools can reuse HASSH fingerprints across unrelated activity.'\n- 'HASSH is sensitive to protocol implementation and capture quality, and should be corroborated with service, timing, or infrastructure context.'\ncapability_requirements:\n  required:\n  - 'ssh_fingerprint_telemetry'\n  - 'network_session_normalization'\n  optional:\n  - 'honeypot_telemetry'\n  - 'ssh_banner_collection'\nname: HASSH Fingerprint -> Host Cluster\ncategory: CTI\ndescription: Cluster hosts or services observed with the same SSH HASSH client/server fingerprint while filtering common tools and scanners.\nsource: network:fingerprint:hassh\ntarget: inet:ipv4|inet:fqdn|network:service\nassessment_mode: evidence_only\nhops:\n- via: observed_on\n  direction: out\n  form: network:service\n- via: hosted_by\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - hassh.firstseen <= service.lastseen\n    window_days: 365\n  degree_caps:\n    network:fingerprint:hassh: 5000\n  negative_nodes:\n  - form: network:fingerprint:hassh\n    list: common_ssh_client_fingerprints\n  - form: inet:ipv4\n    list: known_scanner_asns\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- ssh_banner_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- honeypot\n- netflow\n- shodan_censys\n",
  "CTI_HTTP_BODY_HASH_CLUSTER": "id: CTI_HTTP_BODY_HASH_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'HTTP body hashes are weak fingerprints when default pages, parked domains, error pages, CDN responses, WAF blocks, and scanner artifacts dominate.'\n- 'Body hashing can vary with compression, localization, A/B tests, timestamps, personalization, and fetch context.'\n- 'A shared HTTP body hash is clustering evidence only; corroborate with infrastructure, timing, or content context before drawing conclusions.'\ncapability_requirements:\n  required:\n  - 'http_body_capture'\n  - 'http_body_hashing'\n  optional:\n  - 'dynamic_content_normalization'\n  - 'scanner_artifact_suppression'\nname: HTTP Body Hash Cluster\ncategory: CTI\ndescription: Cluster URLs, hosts, or HTTP observations by a normalized hash of the HTTP response body.\nsource: http:body:hash\ntarget: inet:url|inet:fqdn|http:response\nassessment_mode: evidence_only\nhops:\n- via: body_of\n  direction: out\n  form: http:response\n- via: served_by\n  direction: out\n  form: inet:url|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - response.observed <= body_hash.observed\n    window_days: 90\n  degree_caps:\n    http:body:hash: 100000\n    inet:fqdn: 1000000\n  negative_nodes:\n  - form: http:body:hash\n    list: default_or_error_page_body_hashes\n  - form: http:body:hash\n    list: parked_domain_or_cdn_body_hashes\n  - form: http:response\n    list: scanner_or_security_product_responses\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- response_status\n- content_length_bucket\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- http_scans\n- proxy_logs\n- osint_web\n",
  "CTI_HTTP_HREF_TO_LINKED_DOMAIN": "id: CTI_HTTP_HREF_TO_LINKED_DOMAIN\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'Most web pages link to common benign services such as analytics, social media, CDNs, payment processors, and consent platforms.'\n- 'A linked domain is weak evidence of shared operation unless supported by link context, repeated co-occurrence, or additional infrastructure pivots.'\ncapability_requirements:\n  required:\n  - 'web_crawling'\n  - 'url_normalization'\n  optional:\n  - 'content_extraction'\n  - 'link_context_classification'\nname: HTTP Href -> Linked Domain\ncategory: CTI\ndescription: Pivot from a crawled web page to external FQDNs referenced in href, script, image, form, or embedded resource links.\nsource: web:page\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: links_to\n  direction: out\n  form: inet:url\n- via: has_host\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - page.observed <= link.observed\n    window_days: 30\n  degree_caps:\n    web:page: 10000\n    inet:fqdn: 50000\n  negative_nodes:\n  - form: inet:fqdn\n    list: social_media_platforms\n  - form: inet:fqdn\n    list: analytics_platforms\n  - form: inet:fqdn\n    list: common_cdn_domains\n  - form: inet:fqdn\n    list: payment_and_consent_platforms\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- link_context_weight\n- common_domain_penalty\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- proxy_logs\n- url_corpus\n",
  "CTI_HTTP_REDIRECT_FINGERPRINT_CLUSTER": "id: CTI_HTTP_REDIRECT_FINGERPRINT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: multi_hop_inference\nhazards:\n- 'Generic redirect frameworks, WAFs, captive portals, and SaaS front doors can share the same HTTP redirect fingerprint across unrelated infrastructure.'\n- 'Scanner coverage and banner parsing can miss conditional redirects, JavaScript redirects, or host-specific routing behaviour.'\ncapability_requirements:\n  required:\n  - 'http_header_collection'\n  - 'http_redirect_extraction'\n  optional:\n  - 'tls_scanning'\n  - 'web_fingerprinting'\nname: HTTP Redirect Fingerprint -> Infra Cluster\ncategory: CTI\ndescription: Cluster infrastructure exposing the same HTTP redirect fingerprint, including status, redirect headers, and adjacent banner traits.\nsource: http:redirect:fingerprint\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: observed_on\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - fingerprint.seen <= infra.seen\n    window_days: 365\n  degree_caps:\n    http:redirect:fingerprint: 5000\n  negative_nodes:\n  - form: inet:fqdn\n    list: common_saas_redirectors\n  - form: inet:ipv4\n    list: cdn_edges\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- shodan_censys\n- osint_web\n- tls\n",
  "CTI_HTTP_REDIRECT_TARGET_TO_FQDN": "id: CTI_HTTP_REDIRECT_TARGET_TO_FQDN\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: multi_hop_inference\nhazards:\n- 'Redirect chains often traverse benign SaaS, WAF, link-shortener, tracking, payment, consent, and CDN infrastructure.'\n- 'Conditional redirects can vary by geography, user agent, cookie state, or time and may not represent stable operator infrastructure.'\n- 'Common redirectors and shared tracking or CDN services can create false destination clusters; corroborate with source-page context.'\ncapability_requirements:\n  required:\n  - 'http_redirect_extraction'\n  - 'url_normalization'\n  optional:\n  - 'http_header_collection'\n  - 'web_fingerprinting'\nname: HTTP Redirect Target -> FQDN\ncategory: CTI\ndescription: Pivot from a URL or host to FQDNs observed as redirect targets in HTTP, meta-refresh, or JavaScript redirect chains.\nsource: inet:url|inet:fqdn\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: redirects_to\n  direction: out\n  form: inet:url\n- via: has_host\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - source.observed <= redirect.observed <= target.observed\n    window_days: 90\n  degree_caps:\n    inet:url: 1000\n    inet:fqdn: 5000\n  negative_nodes:\n  - form: inet:fqdn\n    list: common_saas_redirectors\n  - form: inet:fqdn\n    list: link_shorteners\n  - form: inet:fqdn\n    list: analytics_and_consent_platforms\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- redirect_chain_position\n- same_origin_flag\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- shodan_censys\n- proxy_logs\n",
  "CTI_HTTP_SERVER_BANNER_CLUSTER": "id: CTI_HTTP_SERVER_BANNER_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'Server banners are often default, forged, normalized by proxies, or shared by common hosting stacks.'\n- 'Internet scan data can be stale, incomplete, or affected by transient middleware and CDN behavior.'\n- 'Banner reuse is a weak clustering signal unless paired with rarer content, certificate, or hosting evidence.'\ncapability_requirements:\n  required:\n  - 'http_header_collection'\n  - 'server_banner_normalization'\n  optional:\n  - 'internet_scan_archive_lookup'\n  - 'common_banner_suppression'\n  - 'tls_certificate_enrichment'\nname: HTTP Server Banner Cluster\ncategory: CTI\ndescription: Cluster hosts or URLs that expose the same distinctive HTTP server banner or platform header value.\nsource: http:server_header\ntarget: inet:fqdn|inet:ipv4|inet:url\nassessment_mode: evidence_only\nhops:\n- via: observed_on_service\n  direction: in\n  form: network:service\n- via: hosted_at\n  direction: out\n  form: inet:fqdn|inet:ipv4|inet:url\nconstraints:\n  temporal:\n    order:\n    - banner.observed <= service.observed\n    window_days: 90\n  degree_caps:\n    http:server_header: 100000\n    inet:fqdn: 100000\n  negative_nodes:\n  - form: http:server_header\n    list: common_default_server_banners\n  - form: inet:fqdn\n    list: common_cdn_or_hosting_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- banner_normalized\n- version_specificity\n- common_banner_penalty\n- scan_archive_count\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- internet_scan_archives\n",
  "CTI_HTTP_STATUS_LINE_CLUSTER": "id: CTI_HTTP_STATUS_LINE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'HTTP status lines are very weak fingerprints; default servers, middleware, scanners, redirects, CDNs, and WAFs can reuse the same status behavior.'\n- 'Status-line observations can vary by method, path, user agent, authentication state, region, and time.'\n- 'A shared status line is triage context only and must not be treated as ownership, compromise, or actor attribution.'\ncapability_requirements:\n  required:\n  - 'http_response_capture'\n  - 'http_status_normalization'\n  optional:\n  - 'scanner_artifact_suppression'\n  - 'request_context_preservation'\nname: HTTP Status Line Cluster\ncategory: CTI\ndescription: Cluster HTTP observations by normalized response status line while preserving request context.\nsource: http:status_line\ntarget: inet:url|inet:fqdn|http:response\nassessment_mode: evidence_only\nhops:\n- via: status_of\n  direction: out\n  form: http:response\n- via: observed_on\n  direction: out\n  form: inet:url|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - response.observed <= status_line.observed\n    window_days: 30\n  degree_caps:\n    http:status_line: 1000000\n    inet:fqdn: 1000000\n  negative_nodes:\n  - form: http:status_line\n    list: common_http_status_lines\n  - form: inet:fqdn\n    list: common_cdn_or_waf_domains\n  - form: http:response\n    list: scanner_or_security_product_responses\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- request_method\n- response_role\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- http_scans\n- proxy_logs\n- osint_web\n",
  "CTI_HTTP_TITLE_TEMPLATE_CLUSTER": "id: CTI_HTTP_TITLE_TEMPLATE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'Generic placeholder titles, CMS defaults, and reused web themes create obvious false positives unless paired with stronger infra evidence.'\n- 'HTTP titles are easy to change, localization-sensitive, and often absent or inconsistent across scanners.'\ncapability_requirements:\n  required:\n  - 'http_title_collection'\n  optional:\n  - 'content_fingerprinting'\n  - 'passive_dns'\nname: HTTP Title Template -> FQDN Cluster\ncategory: CTI\ndescription: Cluster websites and hosted domains that expose the same distinctive HTTP title or placeholder template marker.\nsource: web:http:title\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: titled_page\n  direction: out\n  form: web:site\n- via: hosts\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - title.seen <= fqdn.seen\n    window_days: 365\n  degree_caps:\n    web:http:title: 5000\n  negative_nodes:\n  - form: web:http:title\n    list: popular_cms_default_titles\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- shodan_censys\n- pdns\n",
  "CTI_HTTP_URI_PATH_PATTERN_CLUSTER": "id: CTI_HTTP_URI_PATH_PATTERN_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'URI paths are often default framework routes, CMS files, static resources, or copied phishing-kit paths.'\n- 'Path-only matches lose query, method, body, and server-context evidence.'\n- 'High-degree common paths require aggressive negative controls before clustering is useful.'\ncapability_requirements:\n  required:\n  - 'http_request_or_scan_path_extraction'\n  - 'uri_path_normalization'\n  optional:\n  - 'query_parameter_normalization'\n  - 'common_path_suppression'\n  - 'http_body_fingerprinting'\nname: HTTP URI Path Pattern Cluster\ncategory: CTI\ndescription: Cluster URLs or hosts that expose the same distinctive HTTP URI path pattern across telemetry or scan observations.\nsource: http:uri:path_pattern\ntarget: inet:url|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: path_observed_on_url\n  direction: in\n  form: inet:url\n- via: has_host\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - path.observed <= url.observed\n    window_days: 90\n  degree_caps:\n    http:uri:path_pattern: 100000\n    inet:url: 1000000\n  negative_nodes:\n  - form: http:uri:path_pattern\n    list: common_framework_or_cms_paths\n  - form: inet:fqdn\n    list: common_hosting_or_cdn_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- normalized_path_depth\n- query_shape\n- common_path_penalty\n- scan_source_count\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- proxy_logs\n- osint_web\n- internet_scan_archives\n",
  "CTI_IDENTITY_UID_TO_AUTH_SESSIONS": "id: CTI_IDENTITY_UID_TO_AUTH_SESSIONS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: domain_expansion\nhazards:\n- 'Authentication-session pivots must stay time-bounded; stale or merged sessions can connect unrelated identity activity.'\n- 'A session associated with an identity can reflect shared accounts, delegated access, service principals, replay, or compromised credentials.'\n- 'Identity-to-session context is not proof of actor control and should retain source, time, and authentication-method evidence.'\ncapability_requirements:\n  required:\n  - 'identity_uid_normalization'\n  - 'auth_session_telemetry'\n  optional:\n  - 'mfa_context_join'\n  - 'service_principal_classification'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 91\n  next_review: '2026-08-25'\nname: Identity UID -> Auth Sessions\ncategory: CTI\ndescription: Pivot from a normalized user identity identifier to authentication sessions observed for that identity.\nsource: identity:user:uid\ntarget: auth:session\nassessment_mode: evidence_only\nhops:\n- via: authenticated_in\n  direction: out\n  form: auth:session\nconstraints:\n  temporal:\n    order:\n    - identity.observed <= auth_session.started\n    window_days: 30\n  degree_caps:\n    identity:user:uid: 100000\n    auth:session: 1000000\n  negative_nodes:\n  - form: identity:user:uid\n    list: shared_or_service_accounts\n  - form: auth:session\n    list: synthetic_or_healthcheck_sessions\n  - form: auth:session\n    list: stale_or_merged_session_records\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- auth_method\n- session_duration\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- identity\n- auth_logs\n",
  "CTI_IDENTITY_UID_TO_USER_AGENTS": "id: CTI_IDENTITY_UID_TO_USER_AGENTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'User-Agent strings are weak identifiers and can be common, spoofed, normalized, truncated, or generated by security products.'\n- 'Identity-to-User-Agent pivots can be inflated by shared accounts, delegated access, service principals, and browser or app updates.'\n- 'A User-Agent observed with an identity is context, not actor attribution or proof of a specific endpoint.'\ncapability_requirements:\n  required:\n  - 'identity_uid_normalization'\n  - 'user_agent_extraction'\n  optional:\n  - 'user_agent_normalization'\n  - 'security_product_user_agent_suppression'\nname: Identity UID -> User-Agents\ncategory: CTI\ndescription: Pivot from a normalized user identity identifier to User-Agent strings observed in authentication or web telemetry.\nsource: identity:user:uid\ntarget: http:user_agent\nassessment_mode: evidence_only\nhops:\n- via: observed_with\n  direction: out\n  form: http:user_agent\nconstraints:\n  temporal:\n    order:\n    - identity.observed <= user_agent.observed\n    window_days: 30\n  degree_caps:\n    identity:user:uid: 100000\n    http:user_agent: 10000\n  negative_nodes:\n  - form: http:user_agent\n    list: common_browser_user_agents\n  - form: http:user_agent\n    list: security_product_user_agents\n  - form: identity:user:uid\n    list: shared_or_service_accounts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- ua_family\n- auth_context\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- identity\n- auth_logs\n- proxy_logs\n",
  "CTI_INTEL_OBSERVABLE_TO_TELEMETRY_SIGHTINGS": "id: CTI_INTEL_OBSERVABLE_TO_TELEMETRY_SIGHTINGS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Broad, stale, low-confidence, or commodity observables can match large amounts of unrelated telemetry.'\n- 'A telemetry sighting of an observable is not actor attribution and should not inherit the source report confidence automatically.'\n- 'Common or generic observables require corroboration with freshness, sighting context, and confidence before analyst action.'\ncapability_requirements:\n  required:\n  - 'intel_observable_normalization'\n  - 'telemetry_sighting_index'\n  optional:\n  - 'stix_mapping'\n  - 'sighting_deduplication'\nname: Intel Observable -> Telemetry Sightings\ncategory: CTI\ndescription: Pivot from a normalized intelligence observable to matching sightings across endpoint, mail, network, DNS, or proxy telemetry.\nsource: intel:observable\ntarget: telemetry:sighting\nassessment_mode: evidence_only\nhops:\n- via: matched_by\n  direction: out\n  form: telemetry:sighting\nconstraints:\n  temporal:\n    order:\n    - observable.ingested <= sighting.matched\n    window_days: 3650\n  degree_caps:\n    intel:observable: 1000000\n  negative_nodes:\n  - form: intel:observable\n    list: noisy_or_expired_observables\n  - form: inet:ipv4\n    list: private_or_reserved_ranges\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- sighting_count\n- telemetry_dataset_diversity\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- threat_intel\n- siem\n- edr\n- mail_telemetry\n- proxy_logs\n- dns\n",
  "CTI_LOGIN_PAGE_SCRIPT_FINGERPRINT_CLUSTER": "id: CTI_LOGIN_PAGE_SCRIPT_FINGERPRINT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: multi_hop_inference\nhazards:\n- 'Login-page scripts can be copied from templates, frameworks, phishing kits, legitimate portals, or security products.'\n- 'Conditional rendering can depend on server replies, cookies, geography, time, or user agent.'\n- 'A script fingerprint can identify a kit or template, but it does not prove infrastructure ownership.'\n- 'Common framework scripts and default kit templates create false matches; corroborate with page content and infrastructure context.'\ncapability_requirements:\n  required:\n  - 'web_script_extraction'\n  - 'script_fingerprinting'\n  optional:\n  - 'dynamic_rendering'\n  - 'phishing_template_suppression'\n  - 'redirect_chain_extraction'\nname: Login Page Script Fingerprint Cluster\ncategory: CTI\ndescription: Cluster login pages or hosts that expose the same distinctive JavaScript fingerprint or conditional-rendering script marker.\nsource: javascript:hash|web:behavior:fingerprint\ntarget: inet:url|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: embedded_in_page\n  direction: in\n  form: inet:url\n- via: has_host\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - script.observed <= page.observed\n    window_days: 90\n  degree_caps:\n    javascript:hash: 100000\n    inet:url: 100000\n  negative_nodes:\n  - form: javascript:hash\n    list: common_login_framework_scripts\n  - form: inet:fqdn\n    list: legitimate_identity_provider_hosts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- script_hash\n- behavior_marker\n- template_penalty\n- dynamic_rendering_flag\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- url_corpus\n- internet_scan_archives\n",
  "CTI_MARKETPLACE_SOLD_DOMAIN_CERT_CLUSTER": "id: CTI_MARKETPLACE_SOLD_DOMAIN_CERT_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_MARKETPLACE_SOLD_DOMAIN_CERT_CLUSTER.json\n  sha256: df6e411b553b448fe8a952df02e35b1807b20f857f906f06dfef09e6881408ed\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: multi_hop_inference\nhazards:\n- A genuine historical reported sale may be corrected, disputed or withdrawn. Retained\n  report-based leads do not establish that a sale or registration transfer occurred,\n  or identify a buyer or controller.\n- The exact claimed-domain-to-certificate association and actual candidate presentation\n  remain separate joins. A request for another name on the certificate does not prove\n  deployment of the sold domain.\n- Candidate presentation uses a selected UTC period and separately supported reported-sale\n  chronology. Pre-existing certificates are eligible; validity or CT discovery is\n  not issuance time.\n- Explicit sale-report status, certificate-class and address-class filters retain\n  their distinct subjects and reasons. Source counts are documentary metadata, not\n  independent corroboration.\ncapability_requirements:\n  required:\n  - semantic_evidence_v1\n  - certificate_normalization\n  - reported_sale_revision_evidence\n  - certificate_name_correspondence\n  - presentation_occurrence_and_endpoint_correspondence\n  optional:\n  - collection_knowledge_witnesses\n  - source_classification_evidence\n  - marketplace_sale_history\n  - tls_scanning\n  - ct_history\n  - assertion_amendment_history_v1\nname: Selected Historical Sale Report → Certificate-Linked Presentation Leads\ncategory: CTI\ndescription: Selected genuine historical reported sale, exact domain-to-certificate\n  association and later candidate presentation. Pre-existing certificates are eligible;\n  revisions, status and asserted chronology remain visible.\nsource: osint:marketplace:sale\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: selected_reported_sale_domain\n  direction: out\n  form: inet:fqdn\n- via: explicit_certificate_name_association\n  direction: out\n  form: x509:cert\n- via: observed_certificate_presentation\n  direction: out\n  form: inet:service\n- via: evidenced_occurrence_endpoint\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 2\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- marketplace\n- tls\n- ct\n- pdns\n",
  "CTI_OPEN_REDIRECT_URL_TO_FINAL_HOSTS": "id: CTI_OPEN_REDIRECT_URL_TO_FINAL_HOSTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Open redirect chains often traverse benign websites, SaaS platforms, tracking systems, and security products.'\n- 'Redirect behavior can depend on geography, user agent, cookies, time, and server-side state.'\n- 'A redirect target is delivery-chain evidence, not proof that the redirector owner participated.'\n- 'Common redirect services and shared tracking infrastructure can create false final-host clusters; corroborate with lure and timing evidence.'\ncapability_requirements:\n  required:\n  - 'redirect_chain_extraction'\n  - 'url_normalization'\n  optional:\n  - 'open_redirect_parameter_detection'\n  - 'conditional_redirect_replay'\n  - 'common_redirector_suppression'\nname: Open Redirect URL -> Final Hosts\ncategory: CTI\ndescription: Pivot from a URL with open-redirect behavior to final destination hosts observed in redirect chains.\nsource: inet:url\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: redirects_to\n  direction: out\n  form: inet:url\n- via: final_host\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - source.observed <= redirect.observed <= target.observed\n    window_days: 30\n  degree_caps:\n    inet:url: 10000\n    inet:fqdn: 100000\n  negative_nodes:\n  - form: inet:fqdn\n    list: common_saas_redirectors\n  - form: inet:fqdn\n    list: link_shorteners\n  - form: inet:fqdn\n    list: analytics_and_consent_platforms\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- redirect_chain_position\n- same_origin_flag\n- redirect_parameter_name\n- common_redirector_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- proxy_logs\n- url_corpus\n",
  "CTI_SAMPLE_C2_INFRA": "id: CTI_SAMPLE_C2_INFRA\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: multi_hop_inference\nhazards:\n- 'Detonation output can include sinkholes, researcher infrastructure, or dead configs that never represented live operator control.'\n- 'Shared hosting and short-lived VPS infrastructure can make malware-adjacent overlap look stronger than it is.'\ncapability_requirements:\n  required:\n  - 'malware_sandbox_summary'\n  - 'sample_hash_normalization'\n  optional:\n  - 'passive_dns'\n  - 'tls_scanning'\nname: Malware Sample → Sandbox C2 → Infra (IP/FQDN)\ncategory: CTI\ndescription: Detonation-derived C2 infrastructure from file:bytes samples.\nsource: file:bytes\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: sandbox_observed\n  direction: out\n  form: c2:endpoint\n- via: resolves|connects\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - sample.firstseen <= c2.firstseen <= infra.seen\n    window_days: 365\n  degree_caps:\n    c2:endpoint: 1000\n  negative_nodes:\n  - form: inet:fqdn\n    list: cdn_edges\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- sandbox\n- siem\n- pdns\n- abuse_ch\n",
  "CTI_SAMPLE_MUTEX_CLUSTER": "id: CTI_SAMPLE_MUTEX_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nname: Mutex Name -> Sample Cluster\ncategory: CTI\ndescription: Cluster samples reusing mutex names or mutex families while filtering common installer and commodity-software values.\nhazards:\n- 'Generic mutex names and framework defaults can cluster unrelated malware or even benign software.'\n- 'Unpacking and normalization errors can overcount mutex reuse if strings are not canonicalized carefully.'\ncapability_requirements:\n  required:\n  - 'malware_static_analysis'\n  - 'sample_hash_normalization'\n  optional:\n  - 'common_string_suppression'\n  - 'sample_prevalence_enrichment'\nsource: it:exec:mutex\ntarget: file:bytes\nassessment_mode: evidence_only\nhops:\n- via: observed_in\n  direction: out\n  form: file:bytes\nconstraints:\n  temporal:\n    order:\n    - mutex.firstseen <= sample.firstseen\n    window_days: 3650\n  degree_caps:\n    it:exec:mutex: 10000\n  negative_nodes:\n  - form: it:exec:mutex\n    list: common_benign_mutexes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- sandbox\n- malware_corpus\n",
  "CTI_SAMPLE_RICHPE_CLUSTER": "id: CTI_SAMPLE_RICHPE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Common toolchains, packers, or vendor build environments can legitimately share RichPE fingerprints.'\n- 'Packed, stripped, or corrupted samples can reduce coverage and bias the cluster toward better-preserved binaries.'\ncapability_requirements:\n  required:\n  - 'pe_metadata_extraction'\n  - 'resource_section_hashing'\n  optional:\n  - 'packer_detection'\n  - 'sample_prevalence_enrichment'\nname: RichPE Fingerprint -> Sample Cluster\ncategory: CTI\ndescription: Cluster Windows samples sharing the same Rich header fingerprint or canonicalized RichPE hash.\nsource: pe:rich:hash\ntarget: file:bytes\nassessment_mode: evidence_only\nhops:\n- via: observed_in\n  direction: out\n  form: file:bytes\nconstraints:\n  temporal:\n    order:\n    - richpe.firstseen <= sample.firstseen\n    window_days: 3650\n  degree_caps:\n    pe:rich:hash: 10000\n  negative_nodes:\n  - form: pe:rich:hash\n    list: common_compiler_richpe_hashes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- sandbox\n- malware_corpus\n",
  "CTI_WEB_CLIENT_UID_TO_IPS": "id: CTI_WEB_CLIENT_UID_TO_IPS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Browser/client identifiers can be reset, synced, shared, replayed, truncated, hashed, or scoped to one vendor telemetry source.'\n- 'NAT, VPN, proxy, carrier-grade NAT, and corporate egress can overjoin many unrelated users or browsers to one IP address.'\n- 'A browser/client UID to IP match is not actor attribution and should not be treated as proof of endpoint ownership.'\ncapability_requirements:\n  required:\n  - 'browser_client_uid_normalization'\n  - 'web_request_source_ip_extraction'\n  optional:\n  - 'proxy_chain_parsing'\n  - 'egress_ip_suppression'\n  - 'vpn_or_proxy_enrichment'\nname: Web Client UID -> IPs\ncategory: CTI\ndescription: Pivot from a normalized browser or web client identifier to source IP addresses observed with that identifier.\nsource: web:client:uid\ntarget: inet:ipv4\nassessment_mode: evidence_only\nhops:\n- via: observed_in_request\n  direction: out\n  form: http:request\n- via: sourced_from\n  direction: out\n  form: inet:ipv4\nconstraints:\n  temporal:\n    order:\n    - client_uid.firstseen <= request.observed\n    window_days: 90\n  degree_caps:\n    web:client:uid: 100000\n    inet:ipv4: 100000\n  negative_nodes:\n  - form: inet:ipv4\n    list: private_or_reserved_ranges\n  - form: inet:ipv4\n    list: high_volume_corporate_egress_ips\n  - form: inet:ipv4\n    list: known_vpn_proxy_or_tor_egress\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- ip_role_context\n- egress_degree\n- geo_asn_consistency\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- proxy_logs\n- browser_telemetry\n",
  "CTI_WEB_CLIENT_UID_TO_URLS": "id: CTI_WEB_CLIENT_UID_TO_URLS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Browser/client identifiers can be reset, synced, shared, replayed, truncated, hashed, or scoped to one vendor telemetry source.'\n- 'URL telemetry can include prefetches, scanners, redirects, embedded resources, and background requests rather than deliberate user navigation.'\n- 'A browser/client UID match is not actor attribution.'\ncapability_requirements:\n  required:\n  - 'browser_client_uid_normalization'\n  - 'web_request_telemetry'\n  optional:\n  - 'url_normalization'\n  - 'redirect_chain_extraction'\n  - 'scanner_prefetch_suppression'\nname: Web Client UID -> URLs\ncategory: CTI\ndescription: Pivot from a normalized browser or web client identifier to URLs and HTTP requests observed with that identifier.\nsource: web:client:uid\ntarget: inet:url|http:request\nassessment_mode: evidence_only\nhops:\n- via: observed_in_request\n  direction: out\n  form: http:request\n- via: requested\n  direction: out\n  form: inet:url\nconstraints:\n  temporal:\n    order:\n    - client_uid.firstseen <= request.observed\n    window_days: 90\n  degree_caps:\n    web:client:uid: 100000\n    http:request: 1000000\n  negative_nodes:\n  - form: inet:fqdn\n    list: browser_prefetch_or_update_domains\n  - form: http:request\n    list: scanner_or_security_product_requests\n  - form: inet:url\n    list: static_embedded_resource_urls\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- request_context\n- navigation_type\n- redirect_chain_position\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- proxy_logs\n- browser_telemetry\n- url_corpus\n",
  "CTI_WEB_CLIENT_UID_TO_USER_AGENTS": "id: CTI_WEB_CLIENT_UID_TO_USER_AGENTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'Browser/client identifiers can represent a browser profile, account, cookie jar, device, or product telemetry identity depending on source.'\n- 'User-Agent strings are weak identifiers and can be common, spoofed, normalized, truncated, or generated by security products.'\n- 'A browser/client UID to User-Agent match supports context expansion only; it is not actor attribution.'\ncapability_requirements:\n  required:\n  - 'browser_client_uid_normalization'\n  - 'user_agent_extraction'\n  optional:\n  - 'user_agent_normalization'\n  - 'browser_telemetry_deduplication'\nname: Web Client UID -> User-Agents\ncategory: CTI\ndescription: Pivot from a normalized browser or web client identifier to User-Agent strings observed with that identifier.\nsource: web:client:uid\ntarget: http:user_agent\nassessment_mode: evidence_only\nhops:\n- via: observed_in_request\n  direction: out\n  form: http:request\n- via: has_user_agent\n  direction: out\n  form: http:user_agent\nconstraints:\n  temporal:\n    order:\n    - client_uid.firstseen <= request.observed\n    window_days: 90\n  degree_caps:\n    web:client:uid: 100000\n    http:user_agent: 10000\n  negative_nodes:\n  - form: http:user_agent\n    list: common_browser_user_agents\n  - form: http:user_agent\n    list: security_product_user_agents\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- user_agent_family\n- user_agent_stability\n- normalized_user_agent_flag\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- proxy_logs\n- browser_telemetry\n",
  "CTI_WEB_CONTENT_EMBEDDED_CONFIG_STRING_CLUSTER": "id: CTI_WEB_CONTENT_EMBEDDED_CONFIG_STRING_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: multi_hop_inference\nhazards:\n- 'Embedded web strings can be comments, templates, copied code, analytics markers, or benign application configuration.'\n- 'High-traffic or compromised sites can host unrelated embedded content, so page ownership and content provenance must stay separate.'\n- 'A shared embedded config string is clustering evidence, not proof that the page owner controls malware infrastructure.'\ncapability_requirements:\n  required:\n  - web_content_collection\n  - config_string_extraction\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - html_comment_extraction\n  - script_body_hashing\nname: Web Content Embedded Config String Cluster\ncategory: CTI\ndescription: Find preserved resource captures containing the selected representation-qualified\n  token. Retain URI identity alongside an eligible URL view; an FQDN result requires\n  the actual DNS host component and its own qualification. Resource reuse does not\n  establish domain compromise or ownership.\nsource: malware:config:string|web:content:token\ntarget: inet:url|evidence:resource_content|inet:fqdn\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_WEB_CONTENT_EMBEDDED_CONFIG_STRING_CLUSTER.json\n  sha256: bd530b4f78b13da623c3e1d71b7a5b3798c2518533826a4b62954279a4e25b2b\nhops:\n- via: embedded_in_web_content\n  direction: in\n  form: inet:url\n- via: has_host\n  direction: out\n  form: inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- osint_web\n- internet_scan_archives\n- url_corpus\n",
  "FIN_DEVICE_FINGERPRINT_TO_ACCOUNT_CLUSTER": "id: FIN_DEVICE_FINGERPRINT_TO_ACCOUNT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Shared devices, emulators, and device-farm infrastructure can connect unrelated users.'\n- 'Fingerprint drift across SDK or browser updates can fragment true reuse or create synthetic matches.'\n- 'Account-linking from fingerprints needs KYC or transaction corroboration because false positives are common in shared device pools.'\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'device_fingerprint_normalization'\n  optional:\n  - 'identity_records'\n  - 'emulator_device_farm_suppression'\nreview:\n  last_reviewed: '2026-05-20'\n  review_cadence_days: 90\n  next_review: '2026-08-18'\nname: Device Fingerprint -> Account Cluster\ncategory: FIN\ndescription: Cluster fraud-linked accounts or identities reusing the same device fingerprint or canonical device profile.\nsource: it:device:fingerprint\ntarget: fin:account|person\nassessment_mode: evidence_only\nhops:\n- via: used_by\n  direction: out\n  form: fin:account|person\nconstraints:\n  temporal:\n    order:\n    - device.firstseen <= account.seen\n    window_days: 1825\n  degree_caps:\n    it:device:fingerprint: 1000\n  negative_nodes:\n  - form: it:device:fingerprint\n    list: shared_enterprise_device_profiles\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- device_graph\n- bank_txn\n- kyc\n",
  "FIN_DROP_ADDRESS_CLUSTER": "id: FIN_DROP_ADDRESS_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Apartments, forwarding centres, and commercial mail drops can create benign many-to-one reuse.'\n- 'Address normalization errors can collapse near-matches or under-segment suites and unit identifiers.'\n- 'Shared addresses and account records need temporal KYC corroboration to avoid false positives from mail services.'\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'address_normalization'\n  optional:\n  - 'identity_records'\n  - 'forwarder_classification'\nreview:\n  last_reviewed: '2026-05-20'\n  review_cadence_days: 90\n  next_review: '2026-08-18'\nname: Drop Address -> Entity Cluster\ncategory: FIN\ndescription: Cluster accounts, sellers, or identities sharing the same shipping, forwarding, or drop address.\nsource: geo:address\ntarget: org:org|person\nassessment_mode: evidence_only\nhops:\n- via: ships_to|registered_at\n  direction: out\n  form: org:org|person\nconstraints:\n  temporal:\n    order:\n    - address.created <= entity.seen\n    window_days: 1825\n  degree_caps:\n    geo:address: 500\n  negative_nodes:\n  - form: geo:address\n    list: fulfillment_centers_and_forwarders\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- ecommerce\n- shipping\n- kyc\n",
  "FIN_ENTITY_SHARED_ACCOUNT_CLUSTER": "id: FIN_ENTITY_SHARED_ACCOUNT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Processor settlement accounts, treasury sweeps, or shared finance operations can reflect legitimate pooling.'\n- 'KYC or beneficiary data can be stale or incomplete, so the visible account holder may not be the controlling party.'\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'account_identifier_normalization'\n  optional:\n  - 'identity_records'\n  - 'kyc_context'\n  - 'settlement_account_suppression'\nreview:\n  last_reviewed: '2026-05-20'\n  review_cadence_days: 90\n  next_review: '2026-08-18'\nname: Financial Account -> Shared Entity Cluster\ncategory: FIN\ndescription: Cluster people or organisations sharing the same bank, payout, or beneficiary account after filtering processor settlement noise.\nsource: fin:account\ntarget: org:org|person\nassessment_mode: evidence_only\nhops:\n- via: held_by|used_by\n  direction: out\n  form: org:org|person\nconstraints:\n  temporal:\n    order:\n    - account.firstseen <= entity.seen\n    window_days: 3650\n  degree_caps:\n    fin:account: 200\n  negative_nodes:\n  - form: fin:account\n    list: known_settlement_accounts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- bank_txn\n- kyc\n",
  "FIN_MERCHANT_DESCRIPTOR_CLUSTER": "id: FIN_MERCHANT_DESCRIPTOR_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'Acquirer-side truncation and generic descriptors can collide across unrelated merchants.'\n- 'Descriptor reuse alone is weaker than payout, ownership, or settlement evidence and should be treated as supporting context.'\n- 'Temporal account and KYC context are needed to avoid false positives from shared or generic descriptors.'\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'descriptor_normalization'\n  optional:\n  - 'merchant_profile_context'\n  - 'acquirer_context'\nname: Merchant Descriptor -> Merchant Cluster\ncategory: FIN\ndescription: Cluster merchants or storefronts reusing the same descriptor string or canonical billing descriptor.\nsource: fin:merchant:descriptor\ntarget: fin:merchant\nassessment_mode: evidence_only\nhops:\n- via: observed_on\n  direction: out\n  form: fin:merchant\nconstraints:\n  temporal:\n    order:\n    - descriptor.firstseen <= merchant.seen\n    window_days: 1825\n  degree_caps:\n    fin:merchant:descriptor: 2000\n  negative_nodes:\n  - form: fin:merchant:descriptor\n    list: common_processor_descriptors\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- payments\n- ecommerce\n",
  "FIN_SHARED_PAYOUT_ACCOUNT_CLUSTER": "id: FIN_SHARED_PAYOUT_ACCOUNT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Marketplaces, payment processors, or payroll intermediaries can consolidate payouts for many legitimate recipients.'\n- 'Account reuse may reflect an upstream intermediary rather than common control by the observed merchants or people.'\n- 'Temporal KYC and account ownership evidence is needed to avoid false positives from shared payout services.'\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'payout_account_normalization'\n  optional:\n  - 'identity_records'\n  - 'settlement_account_suppression'\nreview:\n  last_reviewed: '2026-05-20'\n  review_cadence_days: 90\n  next_review: '2026-08-18'\nname: Payout Account -> Merchant Cluster\ncategory: FIN\ndescription: Cluster merchants, sellers, or beneficiaries routing payouts into the same destination account.\nsource: fin:account\ntarget: fin:merchant|person\nassessment_mode: evidence_only\nhops:\n- via: receives_payout_for\n  direction: out\n  form: fin:merchant|person\nconstraints:\n  temporal:\n    order:\n    - account.firstseen <= merchant.seen\n    window_days: 3650\n  degree_caps:\n    fin:account: 500\n  negative_nodes:\n  - form: fin:account\n    list: processor_master_settlement_accounts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- payments\n- bank_txn\n",
  "OSINT_ACTIVE_SUBDOMAIN_ENUMERATION": "id: OSINT_ACTIVE_SUBDOMAIN_ENUMERATION\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Active enumeration discovers names under a root, not proof that each hostname is live, malicious, or independently controlled.'\n- 'Wildcard DNS, default virtual hosts, resolver poisoning, and stale wordlists can produce false hostnames.'\n- 'Shared hosting, managed DNS, parking, and provider defaults can surface broad hostname sets that need suppression before expansion.'\ncapability_requirements:\n  required:\n  - 'active_subdomain_enumeration'\n  - 'dns_wildcard_detection'\n  optional:\n  - 'active_resolution'\n  - 'http_probe'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 92\n  next_review: '2026-08-26'\nname: Active Subdomain Enumeration\ncategory: OSINT\ndescription: Discover candidate subdomains under a registrable root using active enumeration tools such as subfinder-style source aggregation and DNS confirmation.\nsource: inet:fqdn\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: enumerated_subdomain\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - scan.started <= fqdn.confirmed\n    window_days: 30\n  degree_caps:\n    inet:fqdn: 25000\n  negative_nodes:\n  - form: inet:fqdn\n    list: wildcard_dns_roots\n  - form: inet:fqdn\n    list: generated_wordlist_artifacts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- wildcard_penalty\n- resolver_confirmation_ratio\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- active_dns\n- subdomain_osint\n- dns\n",
  "OSINT_ASN_TO_IP_BLOCKS": "id: OSINT_ASN_TO_IP_BLOCKS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Transit ASNs and cloud or CDN aggregators announce IP space on behalf of many unrelated customers; a shared ASN is not a shared operator.'\n- 'BGP origin is the announcing ASN, not the assigned or owning organization; reseller and customer assignments are not visible at this layer.'\n- 'Prefix delegation can change over time; historical IP/ASN bindings should be timestamped and not treated as current ownership.'\ncapability_requirements:\n  required:\n  - 'rir_whois_or_rdap'\n  - 'bgp_history'\n  optional:\n  - 'passive_dns'\n  - 'active_resolution'\nname: ASN → IP Blocks\ncategory: OSINT\ndescription: Enumerate prefixes and live IPs announced by an ASN.\nsource: net:asn\ntarget: inet:ipv4\nassessment_mode: evidence_only\nhops:\n- via: announces\n  direction: out\n  form: inet:ipv4\nconstraints:\n  temporal:\n    order:\n    - asn.firstseen <= ip.seen\n    window_days: 1825\n  degree_caps:\n    net:asn: 1\n  negative_nodes:\n  - form: net:asn\n    list: hyperscaler_asns\n  - form: net:asn\n    list: transit_provider_asns\n  - form: net:asn\n    list: cdn_asns\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- bgp\n",
  "OSINT_CRT_SH_SUBDOMAINS": "id: OSINT_CRT_SH_SUBDOMAINS\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/OSINT_CRT_SH_SUBDOMAINS.json\n  sha256: e03f3b9f81d9430c4bb73696fe1b2b703c45064316db8f4333f0bb008db4a9f6\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- CT certificate or precertificate fields support explicit name associations, not\n  DNS resolution, live service, ownership or control.\n- Literal wildcard entries are separately typed scope clues. They do not enumerate\n  guessed children or suppress concrete names explicitly recorded alongside them.\n- The selected UTC period follows the supported CT-record event meaning. Validity,\n  domain creation, receipt and replay do not substitute for that record occurrence.\n- Shared-CDN or hosting classification is retained as source-qualified context; exclusion\n  is explicitly selected and cannot be inferred from wildcard presence, SAN count\n  or issuer labels.\ncapability_requirements:\n  required:\n  - semantic_evidence_v1\n  - certificate_normalization\n  - ct_record_occurrence_and_name_correspondence\n  - typed_ct_name_scope\n  optional:\n  - collection_knowledge_witnesses\n  - source_classification_evidence\n  - ct_history\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 93\n  next_review: '2026-08-27'\nname: CT Records → Explicit Names and Separate Wildcard Clues\ncategory: OSINT\ndescription: Explicit names and separately typed wildcard clues from source-bound\n  CT records in the chosen record-occurrence period. No wildcard expansion, DNS answer\n  or service presentation is inferred.\nsource: inet:fqdn\ntarget: inet:fqdn|evidence:ct_wildcard_scope\nassessment_mode: evidence_only\nhops:\n- via: ct_name_scope_record\n  direction: out\n  form: x509:ct_record\n- via: explicit_typed_certificate_name\n  direction: out\n  form: inet:fqdn|evidence:ct_wildcard_scope\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- ct\n",
  "OSINT_DOMAIN_TO_MX_HOSTS": "id: OSINT_DOMAIN_TO_MX_HOSTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'MX records can be delegated to managed mail providers and usually do not imply domain ownership beyond DNS configuration.'\n- 'Historical MX records can be stale, parked, sinkholed, or changed after the activity window.'\n- 'Shared mail providers create high-degree nodes that need suppression for clustering use cases.'\ncapability_requirements:\n  required:\n  - 'dns_mx_lookup'\n  - 'dns_name_normalization'\n  optional:\n  - 'passive_dns_history'\n  - 'managed_mail_provider_suppression'\n  - 'rdap_enrichment'\nname: Domain -> MX Hosts\ncategory: OSINT\ndescription: Enumerate MX hosts configured for a domain using current or historical DNS observations while preserving observation time.\nsource: inet:fqdn\ntarget: dns:mx|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: has_mx\n  direction: out\n  form: dns:mx\n- via: points_to_host\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - domain.observed <= mx.observed\n    window_days: 365\n  degree_caps:\n    inet:fqdn: 10000\n    dns:mx: 100000\n  negative_nodes:\n  - form: inet:fqdn\n    list: managed_mail_provider_hosts\n  - form: dns:mx\n    list: parked_or_sinkhole_mx_records\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- mx_preference\n- temporal_consistency\n- managed_provider_flag\n- mx_host_rarity\n- historical_consistency\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- dns\n- pdns\n- rdap\n",
  "OSINT_FQDN_TO_DNS_A_HISTORY": "id: OSINT_FQDN_TO_DNS_A_HISTORY\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: domain_expansion\nhazards:\n- 'DNS A records can be transient, CDN-backed, sinkholed, parked, or reassigned long before later investigation.'\n- 'A single historical resolution does not imply operator control unless the timing overlaps the investigated activity.'\n- 'Common CDN, parking, and shared-hosting IPs require corroboration with contemporaneous DNS and service evidence.'\ncapability_requirements:\n  required:\n  - 'passive_dns'\n  - 'dns_record_normalization'\n  optional:\n  - 'active_resolution'\n  - 'asn_enrichment'\nname: FQDN -> DNS A History\ncategory: OSINT\ndescription: Pivot from an FQDN to IPv4 addresses observed in passive or current DNS A records, preserving observation windows.\nsource: inet:fqdn\ntarget: inet:ipv4\nassessment_mode: evidence_only\nhops:\n- via: resolved_to\n  direction: out\n  form: inet:ipv4\nconstraints:\n  temporal:\n    order:\n    - fqdn.firstseen <= dns_a.lastseen\n    window_days: 1095\n  degree_caps:\n    inet:fqdn: 1000\n    inet:ipv4: 10000\n  negative_nodes:\n  - form: inet:ipv4\n    list: cdn_edges\n  - form: inet:ipv4\n    list: parking_infrastructure\n  - form: inet:ipv4\n    list: shared_hosting_edges\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- ttl_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n- dns\n- asn\n",
  "OSINT_IP_TO_ASN_ORG": "id: OSINT_IP_TO_ASN_ORG\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'BGP origin, RIR allocation, hosting reseller, and customer assignment can point to different organizations for the same IP.'\n- 'Anycast, cloud providers, and reassigned address space can make current ASN/org context misleading for historical investigations.'\n- 'Common cloud and shared-hosting ASNs require corroboration with customer-level or temporal allocation evidence.'\ncapability_requirements:\n  required:\n  - 'ip_to_asn_mapping'\n  - 'rir_whois_or_rdap'\n  optional:\n  - 'bgp_history'\n  - 'hosting_provider_classification'\nname: IP -> ASN Organization\ncategory: OSINT\ndescription: Pivot from an IP address to its observed origin ASN and owning or operating organization, preserving observation time.\nsource: inet:ipv4\ntarget: net:asn|org:org\nassessment_mode: evidence_only\nhops:\n- via: announced_by\n  direction: out\n  form: net:asn\n- via: operated_by\n  direction: out\n  form: org:org\nconstraints:\n  temporal:\n    order:\n    - ip.seen <= asn.observed\n    window_days: 30\n  degree_caps:\n    inet:ipv4: 10\n    net:asn: 1000000\n  negative_nodes:\n  - form: net:asn\n    list: public_cloud_and_cdn_asns\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- allocation_specificity\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- bgp\n- rir\n- rdap\n",
  "OSINT_IP_TO_EXPOSED_RDP": "id: OSINT_IP_TO_EXPOSED_RDP\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Scanner snapshots can miss ephemeral services or record stale exposure after an endpoint changed state.'\n- 'NAT, protocol gateways, and shared jump hosts can make one IP appear more representative of an operator environment than it really is.'\ncapability_requirements:\n  required:\n  - 'rdp_scanning'\n  optional:\n  - 'certificate_normalization'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 94\n  next_review: '2026-08-28'\nname: IP -> Exposed RDP Service\ncategory: OSINT\ndescription: Determine whether an IP exposes RDP and enumerate the observed RDP service surface.\nsource: inet:ipv4\ntarget: it:service:rdp\nassessment_mode: evidence_only\nhops:\n- via: exposes\n  direction: out\n  form: it:service:rdp\nconstraints:\n  temporal:\n    order:\n    - ip.seen <= rdp.seen\n    window_days: 365\n  degree_caps:\n    inet:ipv4: 10\n  negative_nodes:\n  - form: inet:ipv4\n    list: shared_rdp_gateway_ips\n  - form: inet:ipv4\n    list: scanner_honeypot_or_research_ranges\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- shodan_censys\n",
  "OSINT_MARKETPLACE_LISTING_TO_DOMAINS": "id: OSINT_MARKETPLACE_LISTING_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Reseller and auction platforms are broad inventory sources, not threat-only collections, so most listed domains are benign.'\n- 'Relisting, duplicate feeds, and stale marketplace cache data can preserve domains after a listing changed or disappeared.'\n- 'Common marketplace inventory and shared reseller feeds require corroboration with current listing details.'\ncapability_requirements:\n  required:\n  - 'marketplace_listing_collection'\n  optional:\n  - 'domain_normalization'\nname: Marketplace Listing -> Domains\ncategory: OSINT\ndescription: Enumerate domains observed on reseller or auction marketplace listing feeds.\nsource: osint:marketplace:listing\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: lists|offers\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - listing.seen <= fqdn.seen\n    window_days: 90\n  degree_caps:\n    osint:marketplace:listing: 50000\n  negative_nodes:\n  - form: osint:marketplace:listing\n    list: bulk_reseller_inventory_feeds\n  - form: osint:marketplace:listing\n    list: parking_or_broker_listing_sources\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- marketplace\n",
  "OSINT_MARKETPLACE_SALE_TO_DOMAINS": "id: OSINT_MARKETPLACE_SALE_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'A sold marker indicates a marketplace transaction, not who acquired the domain or whether the transfer actually completed.'\n- 'Marketplace feeds can lag transfers or preserve sale records after re-registration, parking, or benign resale activity.'\n- 'Common reseller workflows and shared marketplace feeds require corroboration with transfer and registration evidence.'\ncapability_requirements:\n  required:\n  - 'marketplace_sale_history'\n  optional:\n  - 'domain_normalization'\nname: Marketplace Sale -> Domains\ncategory: OSINT\ndescription: Enumerate domains observed as sold or transacted on reseller or auction marketplaces.\nsource: osint:marketplace:sale\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: sold_domain|transacted_domain\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - sale.seen <= fqdn.seen\n    window_days: 180\n  degree_caps:\n    osint:marketplace:sale: 50000\n  negative_nodes:\n  - form: osint:marketplace:sale\n    list: bulk_reseller_sale_feeds\n  - form: osint:marketplace:sale\n    list: parking_or_broker_transfer_records\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- marketplace\n",
  "OSINT_MX_TO_DOMAINS": "id: OSINT_MX_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nhazards:\n- 'Managed mail providers serve millions of unrelated tenants; a shared MX is not a shared operator.'\n- 'MX records reflect mail-routing configuration, not domain ownership or operator control.'\n- 'Email forwarding and DNS-default providers create wide-degree MX clusters that should not be interpreted as adversary infrastructure.'\ncapability_requirements:\n  required:\n  - 'dns_public_lookup'\n  - 'dns_mx_lookup'\n  optional:\n  - 'passive_dns'\n  - 'managed_mail_provider_suppression'\nname: Mail Exchanger → Domains\ncategory: OSINT\ndescription: Find domains pointing to a specific MX; helps detect mass-hosted kits or throwaway mail setups.\nsource: inet:fqdn:mx\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: mx_for\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - mx.seen <= fqdn.seen\n    window_days: 1825\n  degree_caps:\n    inet:fqdn:mx: 5000\n  negative_nodes:\n  - form: inet:fqdn:mx\n    list: public_mx_providers\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n",
  "OSINT_NS_TO_DOMAINS": "id: OSINT_NS_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Provider and reseller nameservers can host large numbers of unrelated zones.'\n- 'Historical DNS data can retain delegations long after an operator moved or abandoned a domain.'\n- 'Common provider defaults and shared nameservers require corroboration with domain-specific records and timing.'\ncapability_requirements:\n  required:\n  - 'dns_public_lookup'\n  - 'nameserver_enrichment'\n  optional:\n  - 'passive_dns'\n  - 'public_suffix_normalization'\nname: Nameserver → Domains\ncategory: OSINT\ndescription: Find domains delegated to a given NS; useful for clustering adversary-managed zones.\nsource: inet:fqdn:ns\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: authoritative_for\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - ns.seen <= fqdn.seen\n    window_days: 1825\n  degree_caps:\n    inet:fqdn:ns: 5000\n  negative_nodes:\n  - form: inet:fqdn:ns\n    list: public_or_managed_dns_provider_nameservers\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n",
  "OSINT_PDNS_ROOT_TO_SUBDOMAINS": "id: OSINT_PDNS_ROOT_TO_SUBDOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: enumeration\nhazards:\n- 'Passive DNS coverage is uneven across resolvers, geographies, and time windows, so absence of a subdomain is not evidence that it never existed.'\n- 'Wildcard DNS, parking platforms, managed hosting, and scanner artifacts can produce large numbers of low-value hostnames under a root.'\n- 'Common wildcard and shared-hosting patterns should be corroborated with current DNS and service context before clustering.'\ncapability_requirements:\n  required:\n  - 'passive_dns'\n  - 'public_suffix_normalization'\n  optional:\n  - 'dns_wildcard_detection'\n  - 'active_resolution'\nreview:\n  last_reviewed: '2026-05-26'\n  review_cadence_days: 95\n  next_review: '2026-08-29'\nname: Passive DNS Root -> Subdomains\ncategory: OSINT\ndescription: Enumerate FQDNs observed under a registrable root or apex domain using passive DNS observations.\nsource: inet:fqdn\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: passive_dns_subdomain\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - root.firstseen <= fqdn.lastseen\n    window_days: 1825\n  degree_caps:\n    inet:fqdn: 25000\n  negative_nodes:\n  - form: inet:fqdn\n    list: wildcard_dns_roots\n  - form: inet:fqdn\n    list: parked_domain_roots\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- wildcard_penalty\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n- dns\n",
  "OSINT_RDAP_EMAIL_TO_DOMAINS": "id: OSINT_RDAP_EMAIL_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Privacy services, forwarding aliases, and shared admin mailboxes can overcluster unrelated domains.'\n- 'Many registries redact or inconsistently expose email data, which can bias the visible link graph.'\ncapability_requirements:\n  required:\n  - 'rdap_enrichment'\n  - 'email_normalization'\n  optional:\n  - 'privacy_service_suppression'\n  - 'registrar_reseller_context'\nreview:\n  last_reviewed: '2026-05-20'\n  review_cadence_days: 90\n  next_review: '2026-08-18'\nname: RDAP Registrant Email → Domains\ncategory: OSINT\ndescription: Pivot by registrant email (where disclosed) to enumerate domains; filter privacy/proxy.\nsource: rdap:email\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: registered\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - email.created <= fqdn.created\n    window_days: 1825\n  degree_caps:\n    rdap:email: 5000\n  negative_nodes:\n  - form: rdap:email\n    list: privacy_protect_whois\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- rdap\n",
  "OSINT_RDAP_REGISTRANT_TO_DOMAINS": "id: OSINT_RDAP_REGISTRANT_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Corporate service providers and privacy layers can appear as registrants for unrelated customers.'\n- 'Registrant entities can change without immediate RDAP updates, leaving stale resolution trails.'\n- 'RDAP disclosure quality varies sharply by registrar and TLD, so nulls and redactions are common.'\ncapability_requirements:\n  required:\n  - 'rdap_enrichment'\n  - 'registrant_normalization'\n  optional:\n  - 'entity_normalization'\n  - 'privacy_service_suppression'\nreview:\n  last_reviewed: '2026-05-20'\n  review_cadence_days: 90\n  next_review: '2026-08-18'\nname: RDAP Registrant -> Domains\ncategory: OSINT\ndescription: Pivot by disclosed RDAP registrant entity to enumerate domains while filtering privacy and registrar-noise cases.\nsource: rdap:registrant\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: registered\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - registrant.created <= fqdn.created\n    window_days: 3650\n  degree_caps:\n    rdap:registrant: 2000\n  negative_nodes:\n  - form: rdap:registrant\n    list: privacy_proxy_registrants\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- rdap\n",
  "OSINT_TLS_JA3S_TO_FQDNS": "id: OSINT_TLS_JA3S_TO_FQDNS\nversion: 1.0.0\npattern_schema_version: 1.6\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nname: Server JA3S → Domains Associated with Observed Responses\ncategory: OSINT\ndescription: Find domains explicitly associated with actual server TLS responses matching a selected JA3S, retaining the exact observed exchange and leg. A named response is not proof of application success, origin-server identity, control or ownership.\nhazards:\n- 'Shared server TLS configurations and interception proxies can produce the same JA3S across unrelated services and observed legs.'\n- 'JA3 client classes cannot classify JA3S responses, including when their hexadecimal values happen to agree.'\n- 'A request, planned scan, DNS co-occurrence or certificate SAN cannot supply a missing server response or its domain association.'\n- 'Reported fingerprints, clocks and source assertions retain their provenance limitations. Matches establish no unique endpoint, maliciousness, corroboration or accepted assessment.'\ncapability_requirements:\n  required:\n  - 'observed_server_tls_response_evidence'\n  - 'typed_ja3s_selector_and_source_revision'\n  - 'exchange_leg_domain_correspondence'\n  - 'semantic_execution_contract_v1'\n  optional:\n  - 'explicit_response_occurrence_filters'\n  - 'derivation_and_collection_receipt_history'\nsource: tls:ja3s\ntarget: inet:fqdn\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/OSINT_TLS_JA3S_TO_FQDNS.json\n  sha256: bd010cfeca032a048a79642cee84b1db6991138562499e0726e1cf632e414e13\nhops:\n- via: named_server_response\n  direction: out\n  form: inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- tls\n",
  "OSINT_TLS_JA3_TO_FQDNS": "id: OSINT_TLS_JA3_TO_FQDNS\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: enumeration\nname: Client JA3 → Domains Named in Observed Attempts\ncategory: OSINT\ndescription: Find domains explicitly associated with actual client TLS messages matching a selected JA3. Preserve the observed exchange and leg, name-association basis and attempt state; a shared client fingerprint does not identify a server or establish a response.\nhazards:\n- 'Common TLS client libraries share JA3 fingerprints across large benign populations, so this pivot is inherently noisy.'\n- 'Middleboxes, fingerprint evolution, and collection bias can make JA3 overlap unstable across time and vantage points.'\n- 'A planned scan, DNS co-occurrence or certificate name does not prove an observed named attempt. A missing response does not establish failure.'\n- 'Source-reported fingerprints remain reported unless their actual retained material and extraction are independently reproduced. Matches establish no endpoint identity, ownership, maliciousness or accepted assessment.'\ncapability_requirements:\n  required:\n  - 'observed_client_tls_message_evidence'\n  - 'typed_ja3_selector_and_source_revision'\n  - 'exchange_leg_domain_correspondence'\n  - 'semantic_execution_contract_v1'\n  optional:\n  - 'explicit_source_class_or_exchange_filters'\n  - 'derivation_and_collection_receipt_history'\nsource: tls:ja3\ntarget: inet:fqdn\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/OSINT_TLS_JA3_TO_FQDNS.json\n  sha256: fcfa1f20e1f1ba398a1727d0edaff3380dc00fda99465a7743ef273e1cad09d9\nhops:\n- via: named_client_attempt\n  direction: out\n  form: inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- tls\n",
  "SUPPLY_MAINTAINER_EMAIL_TO_PACKAGES": "id: SUPPLY_MAINTAINER_EMAIL_TO_PACKAGES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: low\nrobustness_class: ownership_signal\nhazards:\n- 'Role accounts, relays, and marketplace-managed aliases can span unrelated packages.'\n- 'Maintainer email is weaker than publisher, repo, or signing evidence and should be treated as corroborative.'\ncapability_requirements:\n  required:\n  - 'package_metadata_collection'\n  - 'maintainer_email_normalization'\n  optional:\n  - 'privacy_relay_suppression'\n  - 'package_registry_history'\nreview:\n  last_reviewed: '2026-05-20'\n  review_cadence_days: 90\n  next_review: '2026-08-18'\nname: Maintainer Email -> Packages\ncategory: SUPPLY\ndescription: Cluster packages maintained or published by the same maintainer email while filtering privacy and relay addresses.\nsource: email:addr\ntarget: it:prod:softver\nassessment_mode: evidence_only\nhops:\n- via: maintains|publishes\n  direction: out\n  form: it:prod:softver\nconstraints:\n  temporal:\n    order:\n    - email.created <= package.created\n    window_days: 3650\n  degree_caps:\n    email:addr: 5000\n  negative_nodes:\n  - form: email:addr\n    list: package_privacy_proxy_addresses\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- package_registry\n- osint_web\n",
  "SUPPLY_PACKAGE_REPO_TO_DOMAIN_INFRA": "id: SUPPLY_PACKAGE_REPO_TO_DOMAIN_INFRA\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: domain_expansion\nhazards:\n- 'A version-specific registry declaration establishes a declared source-repository association, not verified build provenance or repository ownership.'\n- 'Preserve the exact package version, registry metadata revision, source, acquisition time, and revision-link evidence; mirrors and current HEAD cannot replace an unresolved version-to-source binding.'\n- 'A repository commit ID and source-snapshot SHA-256 identify the recorded revision and content; neither proves that the package was built from that content.'\n- 'The explicit 3650-day UTC window dates the bound infrastructure observation. Replay and later ingestion do not supply another observation or independent source.'\n- 'Package-to-repository attribution can break across forks, mirrors, or vendored source releases.'\n- 'Distribution domains may be CDN or hosting intermediaries rather than developer-controlled infrastructure.'\n- 'Common registry CDNs and shared release infrastructure require corroboration with package ownership and version context.'\ncapability_requirements:\n  required:\n  - semantic_execution_contract_v1\n  - preserved_version_declaration\n  - explicit_relationship_observation\n  - scoped_repository_control_evaluation\n  - 'package_metadata_collection'\n  - 'repo_resolution'\n  optional:\n  - 'dns_public_lookup'\n  - 'passive_dns'\n  - 'package_registry_history'\nname: Package -> Repo -> Domain or Infra\ncategory: SUPPLY\ndescription: Follow a version-specific package-registry declaration to its named source repository, then independently evidenced repository infrastructure; preserve the declaration and any exact source-snapshot binding.\nsource: it:prod:softver\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/SUPPLY_PACKAGE_REPO_TO_DOMAIN_INFRA.json\n  sha256: 12870a2606edfc6839297cdd95c23e071a86b42e83ea3e124c242c8299fdc954\nhops:\n- via: declares_source_repository\n  direction: out\n  form: code:repo\n- via: operated_via|distributed_from\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- package_registry\n- osint_web\n- pdns\n",
  "SUPPLY_RELEASE_BUCKET_TO_PACKAGES": "id: SUPPLY_RELEASE_BUCKET_TO_PACKAGES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: working_set\nprecision_tier: medium\nrobustness_class: ownership_signal\nhazards:\n- 'Shared release buckets and CDN edges can distribute artifacts for many unrelated publishers behind the same bucket reference.'\n- 'Bucket→package edges should be observed at distribution time; retroactive inference from registry metadata can be misleading after a publisher migrates or revokes a bucket.'\ncapability_requirements:\n  required:\n  - 'cloud_bucket_resolution'\n  - 'package_metadata_collection'\n  optional:\n  - 'dns_public_lookup'\n  - 'package_registry_history'\nreview:\n  last_reviewed: '2026-05-20'\n  review_cadence_days: 90\n  next_review: '2026-08-18'\nname: Release Bucket -> Packages\ncategory: SUPPLY\ndescription: Cluster packages or release artifacts distributed from the same object-storage release bucket or release endpoint.\nsource: cloud:bucket\ntarget: it:prod:softver\nassessment_mode: evidence_only\nhops:\n- via: distributes\n  direction: out\n  form: it:prod:softver\nconstraints:\n  temporal:\n    order:\n    - bucket.firstseen <= package.created\n    window_days: 3650\n  degree_caps:\n    cloud:bucket: 10000\n  negative_nodes:\n  - form: cloud:bucket\n    list: public_cdn_buckets\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- package_registry\n- cloud_asset_inventory\n",
  "ADTECH_CREATIVE_SCRIPT_TO_DELIVERY_ENDPOINT": "id: ADTECH_CREATIVE_SCRIPT_TO_DELIVERY_ENDPOINT\nversion: 0.3.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - web_content_collection\n  - web_script_extraction\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - dynamic_rendering\n  - web_fingerprinting\nrobustness_class: multi_hop_inference\nhazards:\n- Third-party scripts, verification pixels and measurement requests are common and\n  require scoped controls.\n- A qualified reference does not establish a request; an attempted request does not\n  establish completed delivery.\n- Shared scripts and endpoints do not transfer creative correspondence or establish\n  advertiser control, maliciousness or accepted assessment.\nname: Creative Script -> Delivery Endpoint\ncategory: ADTECH\ndescription: Find distinct source-qualified creative URI references or actual creative-associated\n  requests, directly or through an exactly corresponding script. Preserve request\n  stage, generic URI and suitable URL views without inferring advertiser control or\n  delivery success.\nsource: web:creative\ntarget: inet:url|evidence:creative_reference\nassessment_mode: evidence_only\nhops:\n- via: yields_evidence_for\n  direction: out\n  form: inet:url|evidence:creative_reference\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- browser_telemetry\n- proxy_logs\n- osint_web\n- adtech_logs\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/ADTECH_CREATIVE_SCRIPT_TO_DELIVERY_ENDPOINT.json\n  sha256: 84f5e7ab3ba6b8bb787434942b5a79f22e4d2fb1a54e4d7fe1759275a47a09b9\n",
  "ADTECH_DSP_ID_TO_VENDOR_BUNDLE": "id: ADTECH_DSP_ID_TO_VENDOR_BUNDLE\nversion: 0.2.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'web_request_telemetry'\n  - 'adtech_identifier_normalization'\n  optional:\n  - 'domain_normalization'\n  - 'vendor_bundle_resolution'\nrobustness_class: ownership_signal\nhazards:\n- 'DSP IDs can be local to a platform and may not resolve to globally stable vendors.'\n- 'White-label, reseller, and bidder-as-a-service deployments can make one DSP bundle serve multiple unrelated customers.'\n- 'Shared vendors, reseller redirects, and common tracking or CDN endpoints can create false matches; corroborate with platform-specific IDs.'\nname: DSP ID -> Vendor Bundle\ncategory: ADTECH\ndescription: Pivot from DSP IDs, advertiser IDs, worker domains, bolt domains, benign CDN URLs, and dynamic CDN URLs to a candidate ad-tech vendor or customer bundle.\nsource: adtech:dsp:id\ntarget: org:org|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: configured_in\n  direction: in\n  form: adtech:bundle\n- via: uses_domain\n  direction: out\n  form: inet:fqdn\n- via: associated_with\n  direction: out\n  form: org:org\nconstraints:\n  temporal:\n    order:\n    - dsp_id.seen <= bundle.seen\n    window_days: 365\n  degree_caps:\n    adtech:dsp:id: 500\n    adtech:bundle: 500\n  negative_nodes:\n  - form: org:org\n    list: major_public_ad_platforms\n  - form: inet:fqdn\n    list: shared_white_label_dsp_hosts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- dsp_id_match\n- advertiser_id_match\n- worker_domain_overlap\n- bolt_domain_overlap\n- benign_cdn_overlap\n- dynamic_cdn_overlap\n- customer_config_overlap\n- white_label_penalty\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cti_reports\n- osint_web\n- adtech_logs\n- url_corpus\n",
  "ADTECH_GEO_TARGETING_HEATMAP_TO_CAMPAIGN": "id: ADTECH_GEO_TARGETING_HEATMAP_TO_CAMPAIGN\nversion: 0.2.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'web_request_telemetry'\n  - 'geo_targeting_observation_normalization'\n  optional:\n  - 'campaign_context_enrichment'\n  - 'publisher_context'\nrobustness_class: multi_hop_inference\nhazards:\n- 'Ad traffic volume by country can reflect publisher audience composition rather than deliberate targeting.'\n- 'Location fields in bid streams may be estimated, rounded, stale, or supplied by an upstream partner.'\n- 'Shared vendor reporting, tracking pixels, and geo-CDN routing can create false targeting patterns; corroborate with campaign configuration.'\nname: Geo-Targeting Heatmap -> Campaign\ncategory: ADTECH\ndescription: Link recurring geographic concentration in ad-tech observations to candidate campaign targeting hypotheses when supported by campaign, publisher, or DSP identifiers.\nsource: geo:place\ntarget: risk:campaign\nassessment_mode: evidence_only\nhops:\n- via: observed_in\n  direction: in\n  form: http:request\n- via: carries\n  direction: out\n  form: adtech:campaign:key\n- via: groups\n  direction: out\n  form: risk:campaign\nconstraints:\n  temporal:\n    order:\n    - geo_observation.firstseen <= campaign.lastseen\n    window_days: 180\n  degree_caps:\n    geo:place: 5000\n    adtech:campaign:key: 2000\n  negative_nodes:\n  - form: geo:place\n    list: broad_publisher_audience_baselines\n  - form: inet:fqdn\n    list: high_volume_ad_exchange_endpoints\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- geo_concentration_ratio\n- campaign_id_overlap\n- dsp_id_overlap\n- publisher_specificity\n- baseline_country_traffic_delta\n- time_window_concentration\n- broad_audience_penalty\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- adtech_logs\n- proxy_logs\n- browser_telemetry\n- cti_reports\n",
  "AITS_ABUSE_LANDING_DOMAIN_CLUSTER": "id: AITS_ABUSE_LANDING_DOMAIN_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'restricted_records'\n  - 'platform_abuse_records'\n  - 'domain_normalization'\n  optional:\n  - 'web_fingerprinting'\n  - 'account_behavior_context'\nhazards:\n- Shared affiliate, linkhub, or staging domains can connect unrelated abuse accounts and create false positives.\n- Landing-domain reuse should be corroborated with account behavior, timing, and platform abuse evidence; access to account evidence may be privacy-restricted.\nname: Abuse Landing Domain -> Account Cluster\ncategory: AITS\ndescription: Link external landing, monetization, or staging domains reused by abusive account clusters.\nsource: inet:fqdn\ntarget: inet:web:acct\nassessment_mode: evidence_only\nhops:\n- via: promoted_by|referenced_by\n  direction: out\n  form: web:url|file:bytes\n- via: used_by\n  direction: out\n  form: inet:web:acct\nconstraints:\n  temporal:\n    order:\n    - fqdn.seen <= artifact.seen <= account.seen\n    window_days: 365\n  degree_caps:\n    inet:fqdn: 5000\n  negative_nodes:\n  - form: inet:fqdn\n    list: mainstream_affiliate_and_linkhub_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- platform_abuse\n- osint_web\n",
  "AITS_PHONE_OR_PAYMENT_INSTRUMENT_TO_ACCOUNT_CLUSTER": "id: AITS_PHONE_OR_PAYMENT_INSTRUMENT_TO_ACCOUNT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'restricted_records'\n  - 'identity_records'\n  - 'financial_records'\n  optional:\n  - 'phone_number_normalization'\n  - 'payment_instrument_normalization'\nhazards:\n- Family plans, prepaid phones, VoIP pools, shared corporate billing, and payment intermediaries can tie unrelated accounts to the same phone or instrument.\n- Phone and payment reuse is privacy-sensitive restricted data; corroborate it with account behavior and abuse evidence before clustering.\nname: Phone or Payment Instrument -> Account Cluster\ncategory: AITS\ndescription: Cluster abusive model accounts sharing recovery phone numbers or billing instruments across nominally distinct identities.\nsource: tel:phone|fin:instrument\ntarget: inet:web:acct\nassessment_mode: evidence_only\nhops:\n- via: used_by\n  direction: out\n  form: inet:web:acct\nconstraints:\n  temporal:\n    order:\n    - anchor.firstseen <= account.seen\n    window_days: 1825\n  degree_caps:\n    tel:phone|fin:instrument: 1000\n  negative_nodes:\n  - form: tel:phone|fin:instrument\n    list: shared_enterprise_billing_contacts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- platform_abuse\n- billing\n",
  "AITS_SHARED_PROMPT_ASSET_CLUSTER": "id: AITS_SHARED_PROMPT_ASSET_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'restricted_records'\n  - 'platform_abuse_records'\n  - 'content_fingerprinting'\n  optional:\n  - 'privacy_minimization'\n  - 'prompt_asset_normalization'\nhazards:\n- Public jailbreak corpora, copied prompt libraries, and common templates can be reused by unrelated accounts and create false positives.\n- Prompt-asset matches should be corroborated with timing, account behavior, and non-public artifacts; raw prompts may contain privacy-sensitive content.\nname: Prompt Asset -> Account Cluster\ncategory: AITS\ndescription: Cluster accounts reusing identical prompt assets, jailbreak snippets, or packaged instruction sets.\nsource: file:bytes|message:prompt\ntarget: inet:web:acct\nassessment_mode: evidence_only\nhops:\n- via: submitted_by|used_by\n  direction: out\n  form: inet:web:acct\nconstraints:\n  temporal:\n    order:\n    - asset.firstseen <= account.seen\n    window_days: 365\n  degree_caps:\n    file:bytes|message:prompt: 5000\n  negative_nodes:\n  - form: file:bytes|message:prompt\n    list: public_prompt_examples\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- platform_abuse\n- trust_safety\n",
  "AITS_SHARED_TOOL_REPO_TO_ABUSE_ACCOUNTS": "id: AITS_SHARED_TOOL_REPO_TO_ABUSE_ACCOUNTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'restricted_records'\n  - 'platform_abuse_records'\n  - 'code_search'\n  optional:\n  - 'repository_reputation'\n  - 'tool_artifact_normalization'\nhazards:\n- Public tool repositories, forks, mirrors, and tutorial code can be shared across benign and abusive accounts.\n- Corroborate repository reuse with account behavior and artifact execution; tool adoption alone can create false common-control claims.\n- Abuse-account linkage and enforcement evidence may be restricted; repository interest alone must not imply account control.\nname: Abuse Tool Repo -> Account Cluster\ncategory: AITS\ndescription: Connect shared abuse tooling or prompt-library repositories to model accounts reusing the resulting tools or artifacts.\nsource: code:repo\ntarget: inet:web:acct\nassessment_mode: evidence_only\nhops:\n- via: referenced_by\n  direction: out\n  form: risk:tool:software|file:bytes\n- via: used_by\n  direction: out\n  form: inet:web:acct\nconstraints:\n  temporal:\n    order:\n    - repo.created <= tool.seen <= account.seen\n    window_days: 730\n  degree_caps:\n    code:repo: 10000\n  negative_nodes:\n  - form: code:repo\n    list: benign_public_prompt_repos\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- platform_abuse\n- osint_web\n",
  "CROSS_APP_STORE_DEVELOPER_TO_DOMAINS": "id: CROSS_APP_STORE_DEVELOPER_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'app_store_metadata_collection'\n  - 'dns_public_lookup'\n  optional:\n  - 'web_content_collection'\n  - 'package_metadata_collection'\nhazards:\n- Shared SDKs, analytics, ad networks, and support vendors can make unrelated developer apps reference common domains.\n- Developer-account or store metadata can be stale, transferred, or reseller-managed; corroborate with app package content and current domain control.\n- Store developer links can reflect acquired accounts, white-label apps, or outsourced support; do not infer operator control without package and domain evidence.\nname: App Store Developer -> Domains\ncategory: CROSS\ndescription: Connect app-store developer accounts to websites, APIs, and support domains referenced by their published applications.\nsource: app:developer\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: publishes\n  direction: out\n  form: app:mobile\n- via: references|hosts\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - developer.firstseen <= app.firstseen <= fqdn.seen\n    window_days: 1825\n  degree_caps:\n    app:developer: 2000\n  negative_nodes:\n  - form: app:developer\n    list: major_app_marketplace_publishers\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- app_store\n- osint_web\n- pdns\n",
  "CROSS_ASN_ORG_TO_SANCTIONS": "id: CROSS_ASN_ORG_TO_SANCTIONS\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: missing_negative_controls\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - rir_whois_or_rdap\n  - sanctions_list_access\n  - semantic_execution_contract_v1\n  - source_revision_scoped_relations\n  - explicit_temporal_applicability\n  - amendment_context\n  optional:\n  - bgp_history\n  - entity_normalization\nhazards:\n- Shared cloud, hosting, reseller, and transit ASNs can map many unrelated customers\n  to the same organization or sanction-adjacent entity.\n- Sanctions and ASN organization data change over time; corroborate allocation dates\n  and customer-level evidence to avoid false positives.\n- Source-reported identity, relationship and list status require separate evidence;\n  no traversal supplies legal exposure, liability, control, source independence or\n  accepted assessment status.\n- A selected historical-status inquiry requires the actual applicable relationship\n  and list intervals. Later publication, receipt and correction do not backdate analyst\n  knowledge or refresh activity.\nname: ASN → Reported Organization → Sanctions Entries\ncategory: CROSS\ndescription: Follow an evidenced ASN/organization relationship during the selected\n  period to selected sanctions entry revisions. This does not propagate a list entry\n  to unrelated customers, hosted infrastructure or every use of the ASN.\nsource: net:asn\ntarget: sanction:entry\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CROSS_ASN_ORG_TO_SANCTIONS.json\n  sha256: 1696aa57887304e2bf42a5be0429faa9e3c10faa0a64461968c02356232098b9\nhops:\n- via: owned_by\n  direction: out\n  form: org:org\n- via: listed_as\n  direction: out\n  form: sanction:entry\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- bgp\n- sanctions\n",
  "CROSS_CERT_SUBJECT_TO_LEI_SANCTIONS": "id: CROSS_CERT_SUBJECT_TO_LEI_SANCTIONS\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: missing_negative_controls\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - certificate_normalization\n  - lei_resolution\n  - sanctions_list_access\n  - semantic_execution_contract_v1\n  - source_revision_scoped_relations\n  - explicit_temporal_applicability\n  - amendment_context\n  optional:\n  - certificate_subject_normalization\n  - entity_normalization\nhazards:\n- Certificate subject organization fields are free-form, CA-normalized, common, or\n  attacker-controlled and can collide with same-name legal entities.\n- Sanctions and LEI joins are temporal and entity-resolution sensitive; corroborate\n  current legal records and certificate ownership before risk scoring.\n- Suppress generic, same-name, and CA-normalized certificate subjects before treating\n  a certificate subject as a sanctioned legal entity.\n- Source-reported identity, relationship and list status require separate evidence;\n  no traversal supplies legal exposure, liability, control, source independence or\n  accepted assessment status.\n- A selected historical-status inquiry requires the actual applicable relationship\n  and list intervals. Later publication, receipt and correction do not backdate analyst\n  knowledge or refresh activity.\nname: Certificate Subject → Evidenced Legal Entity → Sanctions Entries\ncategory: CROSS\ndescription: Follow a preserved certificate subject assertion through evidenced legal-entity\n  correspondence to selected sanctions entry revisions. A certificate name alone supplies\n  no entity resolution, ownership or control; retrospective material reference has\n  no invented activity date.\nsource: x509:cert\ntarget: sanction:entry\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CROSS_CERT_SUBJECT_TO_LEI_SANCTIONS.json\n  sha256: 368d9ec8a2ae34424e9e8d0c31ac1891dc49658eb2bc031b43146d7a14f9b5d2\nhops:\n- via: subject_org\n  direction: out\n  form: org:org\n- via: has_lei\n  direction: out\n  form: lei:record\n- via: listed_as\n  direction: out\n  form: sanction:entry\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- ct\n- lei\n- sanctions\n",
  "CROSS_FQDN_TO_ORG_LEI_SANCTIONS": "id: CROSS_FQDN_TO_ORG_LEI_SANCTIONS\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: missing_negative_controls\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - rdap_enrichment\n  - lei_resolution\n  - sanctions_list_access\n  - semantic_execution_contract_v1\n  - source_revision_scoped_relations\n  - explicit_temporal_applicability\n  - amendment_context\n  optional:\n  - privacy_service_suppression\n  - registrar_reseller_context\nhazards:\n- RDAP registrants may be privacy-proxied, stale, reseller-owned, common service providers,\n  or same-name collisions rather than the domain controller.\n- LEI and sanctions joins are temporal; corroborate current registration evidence\n  and avoid treating intermediary links as direct control.\n- Source-reported identity, relationship and list status require separate evidence;\n  no traversal supplies legal exposure, liability, control, source independence or\n  accepted assessment status.\n- A selected historical-status inquiry requires the actual applicable relationship\n  and list intervals. Later publication, receipt and correction do not backdate analyst\n  knowledge or refresh activity.\nname: Domain → Reported Organization → Sanctions Entries\ncategory: CROSS\ndescription: Follow a dated source-reported domain/organization relationship and explicit\n  legal-entity correspondence to selected sanctions entry revisions. Preserve the\n  relationship role and period; domain association does not establish ownership or\n  liability.\nsource: inet:fqdn\ntarget: sanction:entry\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CROSS_FQDN_TO_ORG_LEI_SANCTIONS.json\n  sha256: 0405fcf986d3f87bea6cf4a3194892debaa68f48863198e68873da7e75f10a5c\nhops:\n- via: registered_to\n  direction: out\n  form: org:org\n- via: has_lei\n  direction: out\n  form: lei:record\n- via: listed_as\n  direction: out\n  form: sanction:entry\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- rdap\n- lei\n- sanctions\n",
  "CROSS_PACKAGE_REPO_TO_DOMAIN_INFRA": "id: CROSS_PACKAGE_REPO_TO_DOMAIN_INFRA\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - semantic_execution_contract_v1\n  - preserved_version_declaration\n  - explicit_relationship_observation\n  - scoped_repository_control_evaluation\n  - 'package_metadata_collection'\n  - 'repo_resolution'\n  optional:\n  - 'dns_public_lookup'\n  - 'passive_dns'\nhazards:\n- 'A version-specific registry declaration establishes a declared source-repository association, not verified build provenance or repository ownership.'\n- 'Preserve the exact package version, registry metadata revision, source, acquisition time, and revision-link evidence; mirrors and current HEAD cannot replace an unresolved version-to-source binding.'\n- 'A repository commit ID and source-snapshot SHA-256 identify the recorded revision and content; neither proves that the package was built from that content.'\n- 'The explicit 3650-day UTC window dates the bound infrastructure observation. Replay and later ingestion do not supply another observation or independent source.'\n- Package registries, mirrors, CDNs, and abandoned repositories can link unrelated projects to shared distribution infrastructure.\n- Corroborate repository ownership with signed releases, maintainer history, and current DNS or hosting control before clustering.\n- Promotion requires negative controls for registry, CDN, provider-owned infrastructure, abandoned repositories, and fork or mirror relationships.\nname: Repo -> Package -> Domain or Infra\ncategory: CROSS\ndescription: Find package versions whose registry metadata declares the source repository, then follow independently evidenced package distribution or reference infrastructure; preserve the declaration and any exact source-snapshot binding.\nsource: code:repo\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CROSS_PACKAGE_REPO_TO_DOMAIN_INFRA.json\n  sha256: bc4e9390d01ded7bcbe28c6940b32964fd363a1f12125d52081a9370d88777f6\nhops:\n- via: declares_source_repository\n  direction: in\n  form: it:prod:softver\n- via: distributed_from|referenced_by\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- package_registry\n- osint_web\n- pdns\n",
  "CROSS_PHISH_DOMAIN_TO_PAYMENT_PROCESSOR": "id: CROSS_PHISH_DOMAIN_TO_PAYMENT_PROCESSOR\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: missing_negative_controls\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'web_content_collection'\n  - 'payment_processor_artifact_extraction'\n  optional:\n  - 'financial_records'\n  - 'merchant_profile_context'\nhazards:\n- Large payment processors and checkout providers are shared by many unrelated merchants and create high false-positive risk.\n- Merchant IDs and processor artifacts are sensitive financial data; corroborate with page content, account-level evidence, and transaction timing.\n- Promotion needs negative controls for hosted checkout pages, shared processor domains, test merchant IDs, and reseller payment flows.\nname: Phish Domain → Payment Processor → Merchant Network\ncategory: CROSS\ndescription: Trace phishing pages to their payment processors and connected merchant IDs.\nsource: inet:fqdn\ntarget: fin:merchant\nassessment_mode: evidence_only\nhops:\n- via: collects_payments_via\n  direction: out\n  form: fin:processor\n- via: services\n  direction: out\n  form: fin:merchant\nconstraints:\n  temporal:\n    order:\n    - page.seen <= merchant.active_ts\n    window_days: 365\n  degree_caps:\n    fin:processor: 10000\n  negative_nodes:\n  - form: fin:merchant\n    list: test_or_sandbox_merchant_accounts\n  - form: fin:merchant\n    list: known_good_high_volume_merchants\n  - form: fin:merchant\n    list: shared_checkout_demo_merchants\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- bank_txn\n",
  "CROSS_SOCIAL_HANDLE_TO_DOMAIN_INFRA": "id: CROSS_SOCIAL_HANDLE_TO_DOMAIN_INFRA\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'social_profile_collection'\n  - 'dns_public_lookup'\n  optional:\n  - 'passive_dns'\n  - 'domain_ownership_resolution'\nname: Social Handle → Website → Infra\ncategory: CROSS\ndescription: Bridge from social handles to official websites and on to infrastructure for takedown.\nhazards:\n- 'Handle reuse across platforms is common and does not guarantee the same person or organisation controls each account.'\n- 'Domains may reference fans, impersonators, or parked assets rather than infrastructure operated by the handle owner.'\nsource: social:handle\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: links_to\n  direction: out\n  form: web:url\n- via: hosted_on\n  direction: out\n  form: inet:fqdn|inet:ipv4\nconstraints:\n  temporal:\n    order:\n    - post.ts within window\n    window_days: 365\n  degree_caps:\n    social:handle: 10000\n  negative_nodes:\n  - form: social:handle\n    list: generic_common_usernames\n  - form: social:handle\n    list: fan_impersonator_or_brand_handles\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- pdns\n",
  "CROSS_TOOL_REPO_TO_ORG": "id: CROSS_TOOL_REPO_TO_ORG\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'code_search'\n  - 'maintainer_identity_resolution'\n  optional:\n  - 'git_metadata'\n  - 'entity_normalization'\nhazards:\n- Public repositories, forks, vendor mirrors, and employment changes can misstate who controls or uses a tool.\n- Corroborate maintainer and organization links with signed commits, release ownership, and current affiliation before inferring relationship.\n- Repository or organization metadata alone must not be treated as authorship, ownership, employment, or current operational control.\nname: Toolcode Repo → Author → Organization\ncategory: CROSS\ndescription: Map tool repositories to maintainers/authors and then to their organizations (OSINT).\nsource: code:repo\ntarget: org:org\nassessment_mode: evidence_only\nhops:\n- via: maintained_by|authored_by\n  direction: out\n  form: person\n- via: employed_by|owns\n  direction: out\n  form: org:org\nconstraints:\n  temporal:\n    order:\n    - commit.ts within window\n    window_days: 1825\n  degree_caps:\n    code:repo: 100000\n  negative_nodes:\n  - form: code:repo\n    list: mass_fork_mirrors\n  - form: code:repo\n    list: vendor_mirror_or_template_repositories\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n",
  "CTI_ASN_TO_EXPLICIT_LISTING_ASSERTIONS": "id: CTI_ASN_TO_EXPLICIT_LISTING_ASSERTIONS\nversion: 1.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_downstream_capability_mapping\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\ncapability_requirements:\n  required:\n  - semantic_execution_contract_v1\n  - source_revision_preservation\n  - explicit_claim_period\n  - scoped_amendment_history\n  optional:\n  - historical_network_association\n  - scoped_investigation_controls\nhazards:\n- List publication, claimed applicability and collection receipt are distinct times;\n  later receipt does not refresh historic activity.\n- Supplied corrections, withdrawals and disputes remain visible; complete source revision\n  history and current unwithdrawn status are not certified.\n- Shared hosting, one listed tenant or network association does not establish maliciousness,\n  ownership, control, liability or accepted assessment.\nname: ASN to explicit source listing assertions\ncategory: CTI\ndescription: Retrieve source assertions explicitly about the selected ASN during an\n  analyst/case period. Listed member infrastructure does not substitute for an ASN-wide\n  publisher assertion.\nsource: net:asn\ntarget: reputation:assertion\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_ASN_TO_EXPLICIT_LISTING_ASSERTIONS.json\n  sha256: 221fd7e3a45b19355e2f1d4267a947bb18fb1e6cf354c264ae3db057e976ada0\nhops:\n- via: subject_of_listing_assertion\n  direction: out\n  form: reputation:assertion\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- bgp\n- spamhaus\n- abuse_ch\n",
  "CTI_ASN_TO_LISTED_INFRASTRUCTURE": "id: CTI_ASN_TO_LISTED_INFRASTRUCTURE\nversion: 1.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_downstream_capability_mapping\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\ncapability_requirements:\n  required:\n  - semantic_execution_contract_v1\n  - source_revision_preservation\n  - explicit_claim_period\n  - scoped_amendment_history\n  optional:\n  - historical_network_association\n  - scoped_investigation_controls\nhazards:\n- List publication, claimed applicability and collection receipt are distinct times;\n  later receipt does not refresh historic activity.\n- Supplied corrections, withdrawals and disputes remain visible; complete source revision\n  history and current unwithdrawn status are not certified.\n- Shared hosting, one listed tenant or network association does not establish maliciousness,\n  ownership, control, liability or accepted assessment.\nname: ASN to associated listed infrastructure\ncategory: CTI\ndescription: Retrieve listed addresses or ranges whose independently supported ASN\n  association applies during the source claim. Preserve association role and period\n  without inferring an ASN-wide listing or individual observations for every address.\nsource: net:asn\ntarget: inet:ipv4|inet:net4\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_ASN_TO_LISTED_INFRASTRUCTURE.json\n  sha256: aa981c698d8d3a20d41e96fb8504b45621064afcccc1399dbe6e2804ffa9bef0\nhops:\n- via: associated_listed_infrastructure\n  direction: out\n  form: inet:ipv4|inet:net4\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- bgp\n- spamhaus\n- abuse_ch\n",
  "CTI_AUTHENTICODE_HASH_CLUSTER": "id: CTI_AUTHENTICODE_HASH_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_AUTHENTICODE_HASH_CLUSTER.json\n  sha256: f0ef1392f2af63d561fe89752a19c6a44ef742b130fcae50e021dd597c97c1cb\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Equal image-content digests do not establish identical complete files, signatures, signers or behaviour. Image findings need no manufactured certificate or successful signature check.'\n- 'Primary, timestamp, chain and other material roles remain distinct. Timestamp material equality does not establish a verified timestamp or primary signer identity.'\n- 'A selected artifact-derived reference needs its own exact relationship evidence and knowledge scope. Candidate matches cannot repair a missing reference join.'\n- 'Synthetic portable fixtures do not establish native adapter acceptance, source authenticity or lane promotion.'\n- 'Certificate presence, reported signer association and a scoped source-reported check are distinct claims; this evaluator does not perform cryptographic signature verification.'\n- 'Whole-artifact, scheme-covered content, whole-certificate, SPKI and issuer/serial identities are distinct. Reuse establishes neither publisher trust, control, common ownership nor accepted assessment.'\n- 'Only an actual complete-finding establishment in the supplied collection history is dated. Reprocessing, receipt, validity dates and new sightings do not renew an older finding.'\n- 'Credential class is retained as context by default. Explicit selected class policies preserve unknown and conflicting evidence; a public certificate does not establish public access to its private key.'\n- 'Correction and withdrawal context is retained without replacing or refreshing the historical finding; absence of a supplied amendment does not establish maintained current support.'\ncapability_requirements:\n  required:\n  - 'semantic_evidence_v1'\n  - 'typed_artifact_and_material_identity'\n  - 'source_qualified_signing_or_digest_evidence'\n  - 'collection_finding_history'\n  - 'scoped_amendment_context'\n  optional:\n  - 'authenticode_metadata_extraction'\n  - 'scoped_signature_verification_reports'\n  - 'credential_classification_with_revision'\n  - 'collection_knowledge_witnesses'\nname: Typed Authenticode, Signature Material or Certificate → File Findings\ncategory: CTI\ndescription: 'Return exact file findings for an explicitly selected image-content digest, scoped signature-material digest, or certificate/key/issuer-serial relationship purpose. Candidate complete-finding availability uses a case-selected period; a separately evidenced historical artifact reference does not refresh candidate novelty. Certificate witnesses stay attached to their file findings rather than becoming an assumed terminal result.'\nsource: code:authenticode:hash|code:signature:material|x509:cert\ntarget: file:hash\nassessment_mode: evidence_only\nhops:\n- via: has_typed_comparison_finding\n  direction: out\n  form: file:hash\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- malware_corpus\n- sandbox\n- code_signing_metadata\n",
  "CTI_CAMPAIGN_TOOL_FQDN": "id: CTI_CAMPAIGN_TOOL_FQDN\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'cti_report_extraction'\n  - 'tool_family_normalization'\n  optional:\n  - 'passive_dns'\n  - 'domain_normalization'\nhazards:\n- Commodity tools and shared hosting can put unrelated campaigns on common domains or infrastructure.\n- Corroborate tool-family evidence with temporal observations and independent indicators; this pivot is not attribution by itself.\n- Campaign labels are report context, not actor ownership or control; tool and domain co-occurrence must not be converted into attribution.\nname: Campaign ↔ Tool → FQDN\ncategory: CTI\ndescription: Campaign-to-domain linkage via shared tool family evidence across sources.\nsource: risk:campaign\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: uses\n  direction: out\n  form: it:prod:soft\n- via: communicates|hosts|connects|c2\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - campaign.firstseen <= fqdn.created\n    window_days: 720\n  degree_caps:\n    it:prod:soft: 300\n  negative_nodes:\n  - form: inet:fqdn\n    list: dynamic_dns_providers\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cti_reports\n- pdns\n- siem\n",
  "CTI_CERT_ISSUER_VALIDITY_CLUSTER": "id: CTI_CERT_ISSUER_VALIDITY_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_CERT_ISSUER_VALIDITY_CLUSTER.json\n  sha256: cc241322d7d212088a5a7822294240d2b96aaf56c569b63905074a3c077159ec\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: low\nrobustness_class: multi_hop_inference\nhazards:\n- The preserved identified profile declares every compared field, exact value or inclusive\n  range and definition revision. A sparse search does not authorize silent broadening\n  or a similarity fallback.\n- Matching subject or issuer labels and declared validity duration do not establish\n  certificate/key identity, actual issuer identity, ACME issuance, deployment lifetime,\n  maliciousness or common control.\n- The same identified matching certificate must be carried into an actual service\n  presentation. CT-only names, copied fields or nearby endpoints do not supply the\n  join.\n- The analyst/case-selected UTC presentation period is independent of profile duration\n  criteria, profile creation, receipt and analytical knowledge. Presentation outside\n  declared certificate validity is retained.\n- Common/default/managed and infrastructure classifications are separate source-qualified\n  context. Exclusions require explicit scoped policies; unknown or conflicting evidence\n  is not clearance.\ncapability_requirements:\n  required:\n  - semantic_evidence_v1\n  - certificate_normalization\n  - preserved_certificate_profile_v1\n  - source_bound_certificate_fields\n  - presentation_occurrence_and_endpoint_correspondence\n  optional:\n  - collection_knowledge_witnesses\n  - source_classification_evidence\n  - tls_scanning\n  - certificate_transparency\nname: Explicit Issuer and Validity Profile → Certificate Presentations\ncategory: CTI\ndescription: Presentation of an actual identified certificate meeting an explicitly\n  preserved issuer_validity profile; profile revision, field criteria and candidate\n  occurrence period remain distinct.\nsource: x509:comparison_profile\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: explicit_profile_matches\n  direction: out\n  form: x509:cert\n- via: observed_certificate_presentation\n  direction: out\n  form: inet:service\n- via: evidenced_occurrence_endpoint\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- tls\n- ct\n",
  "CTI_CLOUD_TENANT_UID_TO_EMAIL_URLS": "id: CTI_CLOUD_TENANT_UID_TO_EMAIL_URLS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Cloud tenant to email URL pivots can cross administrative, customer, guest-user, service-principal, and multi-tenant application boundaries.'\n- 'Email URLs can include security rewrites, marketing links, CDNs, shared SaaS links, redirects, and detonation artifacts.'\n- 'A tenant-to-email-URL relationship is telemetry context only; it is not ownership, compromise, or actor attribution without message and tenant corroboration.'\ncapability_requirements:\n  required:\n  - 'cloud_tenant_uid_normalization'\n  - 'email_url_extraction'\n  optional:\n  - 'protected_url_decoding'\n  - 'message_trace_join'\n  - 'tenant_message_context'\nname: Cloud Tenant UID -> Email URLs\ncategory: CTI\ndescription: Pivot from a normalized cloud tenant identifier to URLs observed in email telemetry associated with that tenant context.\nsource: cloud:tenant:uid\ntarget: inet:url|email:message\nassessment_mode: evidence_only\nhops:\n- via: associated_message\n  direction: out\n  form: email:message\n- via: contains_url\n  direction: out\n  form: inet:url\nconstraints:\n  temporal:\n    order:\n    - tenant.observed <= message.received\n    window_days: 30\n  degree_caps:\n    cloud:tenant:uid: 100000\n    inet:url: 1000000\n  negative_nodes:\n  - form: inet:url\n    list: common_email_service_links\n  - form: inet:fqdn\n    list: common_cdn_domains\n  - form: cloud:tenant:uid\n    list: multi_tenant_provider_or_demo_tenants\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- tenant_relationship\n- message_role\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cloud_audit_logs\n- mail_telemetry\n- url_corpus\n",
  "CTI_CLUSTER_GRAPH_EDGE_EXPLAINED": "id: CTI_CLUSTER_GRAPH_EDGE_EXPLAINED\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'A proprietary cluster edge can hide high-degree nodes, weak features, or filtered evidence unless all contributing paths are exposed.'\n- 'Cluster membership is not actor attribution and should not be promoted without lower-level evidence and separate attribution confidence.'\n- 'Common high-degree features and shared default values can generate false cluster edges; require corroboration from exposed contributing evidence.'\ncapability_requirements:\n  required:\n  - 'cluster_feature_export'\n  - 'pivot_edge_provenance'\n  optional:\n  - 'negative_node_decisions'\n  - 'analyst_adjudication'\nname: Explained Cluster Graph Edge\ncategory: CTI\ndescription: Represent a proprietary cluster-graph edge only when the contributing lower-level pivot evidence, feature values, cap status, and negative-node decisions are emitted.\nsource: graph:cluster\ntarget: inet:ipv4|inet:fqdn|risk:campaign|threat:cluster\nassessment_mode: evidence_only\nhops:\n- via: supported_by\n  direction: out\n  form: graph:evidence:path\n- via: contains\n  direction: out\n  form: inet:ipv4|inet:fqdn|risk:campaign|threat:cluster\nconstraints:\n  temporal:\n    order:\n    - evidence.firstseen <= cluster.generated\n    window_days: 3650\n  degree_caps:\n    graph:cluster: 100000\n  negative_nodes:\n  - form: graph:evidence:path\n    list: unsupported_black_box_edges\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- contributing_pattern_count\n- cap_status\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cluster_graph\n- pdns\n- rdap\n- tls\n- osint_web\n",
  "CTI_COOKIE_NAME_REUSE_CLUSTER": "id: CTI_COOKIE_NAME_REUSE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- Common frameworks, consent managers, analytics SDKs, tag managers, A/B testing platforms, and security products create common cookie names across unrelated sites.\n- Third-party cookies and copied templates can link unrelated domains to the same vendor-controlled namespace.\n- Cookie values are intentionally out of scope for this pattern unless separately normalized, minimized, and reviewed for privacy impact.\n- Cookie-name reuse is a weak clustering signal and must be corroborated with page ownership, timing, content, or infrastructure evidence.\ncapability_requirements:\n  required:\n  - web_crawling\n  - http_cookie_extraction\n  - cookie_name_normalization\n  optional:\n  - javascript_rendering\n  - tag_manager_extraction\n  - common_cookie_suppression\nname: Cookie Name Reuse Cluster\ncategory: CTI\ndescription: Cluster webpages or hostnames that reuse distinctive normalized cookie names or cookie-name namespaces.\nsource: web:cookie:name\ntarget: inet:fqdn|inet:url\nassessment_mode: evidence_only\nhops:\n- via: cookie_name_observed_on\n  direction: out\n  form: inet:url\n- via: hosted_by\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - cookie_name.seen <= page.seen <= fqdn.seen\n    window_days: 365\n  degree_caps:\n    web:cookie:name: 100000\n    inet:fqdn: 1000000\n  negative_nodes:\n  - form: web:cookie:name\n    list: common_framework_or_consent_cookie_names\n  - form: web:cookie:name\n    list: analytics_or_tag_manager_cookie_names\n  - form: inet:fqdn\n    list: common_hosting_or_cdn_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- cookie_scope\n- cookie_namespace\n- first_party_flag\n- third_party_vendor_hint\n- common_cookie_penalty\n- temporal_consistency\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- web_crawl\n",
  "CTI_CVE_EXPLOIT_CAMPAIGN": "id: CTI_CVE_EXPLOIT_CAMPAIGN\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'vulnerability_intelligence'\n  - 'cti_report_extraction'\n  optional:\n  - 'tool_family_normalization'\n  - 'campaign_context_enrichment'\nhazards:\n- Public exploit reporting, opportunistic scanning, and copycat exploitation can make a CVE appear across unrelated campaigns.\n- Corroborate campaign linkage with toolmarks, timing, and victimology; CVE use alone does not prove attribution or common control.\n- Promotion needs examples that separate mass or opportunistic exploitation from campaign-specific exploitation evidence.\nname: CVE → Exploit Usage → Campaign\ncategory: CTI\ndescription: Link a CVE to campaigns reported to exploit it, to support attribution and remediation priority.\nsource: it:sec:vuln\ntarget: risk:campaign\nassessment_mode: evidence_only\nhops:\n- via: exploited_by|mentioned_with\n  direction: out\n  form: risk:campaign\nconstraints:\n  temporal:\n    order:\n    - vuln.published <= campaign.firstseen\n    window_days: 1825\n  degree_caps:\n    it:sec:vuln: 2000\n  negative_nodes:\n  - form: it:sec:vuln\n    list: mass_scanned_or_wormable_cves\n  - form: it:sec:vuln\n    list: roundup_reported_cves\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- nvd_cve\n- cti_reports\n- misp\n",
  "CTI_DOMAIN_REGISTRATION_PROFILE_CLUSTER": "id: CTI_DOMAIN_REGISTRATION_PROFILE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Registration profiles are composite, often privacy-protected, and can reflect registrar defaults or reseller workflows rather than operator behavior.'\n- 'Shared registrars, nameservers, privacy services, and hosting providers can create broad false-positive clusters.'\n- 'This pattern must not duplicate atomic RDAP, nameserver, DNS, certificate, or ASN pivots that already exist.'\ncapability_requirements:\n  required:\n  - 'rdap_or_whois_normalization'\n  - 'domain_registration_feature_extraction'\n  optional:\n  - 'privacy_service_suppression'\n  - 'registrar_reseller_context'\n  - 'nameserver_enrichment'\nname: Domain Registration Profile Cluster\ncategory: CTI\ndescription: Cluster domains that share a narrow, normalized registration profile across registrar, registrant, nameserver, timing, and hosting features.\nsource: domain:registration:profile\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: profile_matches_domain\n  direction: in\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - domain.registered <= profile.observed\n    window_days: 365\n  degree_caps:\n    domain:registration:profile: 10000\n    inet:fqdn: 100000\n  negative_nodes:\n  - form: domain:registrar\n    list: commodity_registrars\n  - form: rdap:registrant\n    list: privacy_or_proxy_registrants\n  - form: dns:nameserver\n    list: managed_dns_provider_nameservers\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- profile_component_count\n- registrar_context\n- nameserver_rarity\n- registration_time_window\n- privacy_service_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- rdap\n- whois_history\n- pdns\n- dns\n",
  "CTI_DOM_STRUCTURE_HASH_CLUSTER": "id: CTI_DOM_STRUCTURE_HASH_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- Common CMS themes, landing-page builders, parked-domain templates, consent banners, and cloned starter kits can produce unrelated DOM-structure matches.\n- JavaScript rendering mode, localization, A/B tests, anti-bot responses, and viewport-dependent markup can make the same site hash differently across crawls.\n- CDN, WAF, registrar holding, and shared SaaS front-door pages can dominate high-degree DOM hashes and must be suppressed before promotion.\n- DOM structure reuse is a clustering lead only; it must not be treated as ownership, compromise, or attribution without corroborating content or infrastructure evidence.\ncapability_requirements:\n  required:\n  - web_crawling\n  - html_normalization\n  - dom_fingerprinting\n  optional:\n  - javascript_rendering\n  - content_deduplication\n  - web_archive_lookup\nname: DOM Structure Hash Cluster\ncategory: CTI\ndescription: Cluster webpages or hostnames that share a normalized DOM structure hash after crawler and rendering settings are recorded.\nsource: web:dom:structure_hash\ntarget: inet:fqdn|inet:url\nassessment_mode: evidence_only\nhops:\n- via: dom_structure_observed_on\n  direction: out\n  form: inet:url\n- via: hosted_by\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - dom_hash.observed <= page.observed <= fqdn.seen\n    window_days: 180\n  degree_caps:\n    web:dom:structure_hash: 100000\n    inet:fqdn: 1000000\n  negative_nodes:\n  - form: web:dom:structure_hash\n    list: common_cms_or_builder_template_hashes\n  - form: web:dom:structure_hash\n    list: parked_domain_or_registrar_holding_page_hashes\n  - form: inet:fqdn\n    list: common_hosting_or_cdn_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- render_mode\n- dom_node_count\n- template_family\n- common_template_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- web_crawl\n- web_archive\n",
  "CTI_EMAIL_ATTACHMENT_AV_CLUSTER_HASH_TO_MESSAGES": "id: CTI_EMAIL_ATTACHMENT_AV_CLUSTER_HASH_TO_MESSAGES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'AV cluster hashes are implementation-specific and can change across engines, versions, or normalization choices.'\n- 'Cluster hashes can group benign families, packed files, common templates, or broad malware families too coarsely for precise pivoting.'\n- 'Mail detonation, forwarding, and bulk campaigns can inflate message counts.'\ncapability_requirements:\n  required:\n  - 'attachment_cluster_hash_normalization'\n  - 'mail_attachment_telemetry'\n  optional:\n  - 'file_hash_enrichment'\n  - 'av_engine_version_context'\n  - 'bulk_mail_suppression'\nname: Email Attachment AV Cluster Hash -> Messages\ncategory: CTI\ndescription: Pivot from an attachment AV cluster hash or similar normalized file-family fingerprint to email messages carrying matching attachments.\nsource: file:av_cluster_hash\ntarget: email:message\nassessment_mode: evidence_only\nhops:\n- via: attachment_cluster_hash\n  direction: in\n  form: email:attachment\n- via: attached_to\n  direction: in\n  form: email:message\nconstraints:\n  temporal:\n    order:\n    - attachment.scanned <= message.received\n    window_days: 90\n  degree_caps:\n    file:av_cluster_hash: 100000\n    email:message: 100000\n  negative_nodes:\n  - form: file:av_cluster_hash\n    list: broad_or_common_av_cluster_hashes\n  - form: email:message\n    list: bulk_or_detonation_generated_messages\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- engine_version\n- attachment_count\n- sender_domain_diversity\n- broad_cluster_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- file_reputation\n- malware_analysis\n",
  "CTI_EMAIL_ATTACHMENT_NAME_TO_MESSAGES": "id: CTI_EMAIL_ATTACHMENT_NAME_TO_MESSAGES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: enumeration\nhazards:\n- 'Attachment names are attacker-controlled, user-visible, localized, and frequently generic.'\n- 'Forwarding, bulk mail, newsletters, templates, and detonation can inflate message counts.'\n- 'Attachment-name matches should remain exploratory unless paired with file hash, sender, URL, or mailflow context.'\ncapability_requirements:\n  required:\n  - 'attachment_name_extraction'\n  - 'message_identifier_normalization'\n  optional:\n  - 'file_hash_enrichment'\n  - 'common_attachment_name_suppression'\n  - 'bulk_mail_suppression'\nname: Email Attachment Name -> Messages\ncategory: CTI\ndescription: Pivot from a normalized email attachment name to messages that carried attachments with that name.\nsource: email:attachment:name\ntarget: email:message\nassessment_mode: evidence_only\nhops:\n- via: attachment_named\n  direction: in\n  form: email:attachment\n- via: attached_to\n  direction: in\n  form: email:message\nconstraints:\n  temporal:\n    order:\n    - attachment.observed <= message.received\n    window_days: 30\n  degree_caps:\n    email:attachment:name: 100000\n    email:message: 100000\n  negative_nodes:\n  - form: email:attachment:name\n    list: common_attachment_names\n  - form: email:message\n    list: bulk_or_marketing_messages\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- file_extension\n- filename_entropy\n- sender_domain_diversity\n- common_name_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- file_reputation\n",
  "CTI_EMAIL_HEADER_VALUE_CLUSTER": "id: CTI_EMAIL_HEADER_VALUE_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Email header values can be spoofed, rewritten, normalized, stripped, or generated by common mail software.'\n- 'Headers can contain personal data, internal hostnames, or tenant-specific values that require minimization.'\n- 'Header-value reuse is weak unless the value is rare and corroborated by attachment, sender, URL, or relay evidence.'\ncapability_requirements:\n  required:\n  - email_header_parsing\n  - header_value_normalization\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - privacy_minimization\n  - message_body_context\nname: Email Header Value Cluster\ncategory: CTI\ndescription: Find preserved message captures containing the selected header value\n  in the selected header name and actual field occurrence. Original, gateway and export\n  representations remain distinct evidence; receipt is not extraction or knowledge\n  time.\nsource: email:header:value\ntarget: email:message\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_EMAIL_HEADER_VALUE_CLUSTER.json\n  sha256: 6638c9e648211cc7a11ce82aef2b79f7f843407dbebc25423cd5aa9cc9dc8310\nhops:\n- via: header_value_present\n  direction: in\n  form: email:message\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- mail_telemetry\n",
  "CTI_EMAIL_MESSAGE_ID_HOST_CLUSTER": "id: CTI_EMAIL_MESSAGE_ID_HOST_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Message-ID host components can be forged, templated by mailing software, or inherited from legitimate mail infrastructure.'\n- 'Large mail platforms and common libraries can produce high-degree host patterns across unrelated messages.'\n- 'A Message-ID host overlap is weak unless paired with sender, attachment, relay, or campaign context.'\ncapability_requirements:\n  required:\n  - message_id_parsing\n  - mailflow_identifier_normalization\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - sender_domain_context\n  - attachment_hash_enrichment\nname: Email Message-ID Host Cluster\ncategory: CTI\ndescription: Find preserved message captures with the selected host text in an actual\n  Message-ID field occurrence. This identifier reuse is a clue and does not establish\n  sender, relay or server identity.\nsource: email:message:id:host\ntarget: email:message\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_EMAIL_MESSAGE_ID_HOST_CLUSTER.json\n  sha256: 7b155dedcedc30910c939c7c9a7da39c91b4859ad488036a634511e7732bb71c\nhops:\n- via: appears_in_message_id\n  direction: in\n  form: email:message\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- mail_telemetry\n",
  "CTI_EMAIL_TEMPLATE_OR_ASSET_CLUSTER": "id: CTI_EMAIL_TEMPLATE_OR_ASSET_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'email_telemetry'\n  - 'content_fingerprinting'\n  optional:\n  - 'phishing_template_suppression'\n  - 'campaign_message_clustering'\nhazards:\n- Common templates, stock images, and phishing-kit boilerplate can be shared by unrelated operators or reused by defenders in tests.\n- Corroborate asset reuse with delivery infrastructure, sender context, and timing before clustering campaigns.\n- Public training material, vendor simulations, and analyst reproduction can replay the same template or asset and must remain suppressible.\nname: Email Template or Asset Hash -> Host Cluster\ncategory: CTI\ndescription: Cluster phishing or lure infrastructure reusing the same template asset, image, or packaged email content.\nsource: hash:sha256\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: embedded_in\n  direction: out\n  form: phish:kit|message:template\n- via: hosted_on|used_by\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - asset.firstseen <= template.firstseen <= fqdn.seen\n    window_days: 730\n  degree_caps:\n    hash:sha256: 5000\n  negative_nodes:\n  - form: hash:sha256\n    list: common_marketing_asset_hashes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- osint_web\n- sandbox\n",
  "CTI_EMAIL_WEBMAIL_ATTACHMENT_SENDER_DOMAIN_CLUSTER": "id: CTI_EMAIL_WEBMAIL_ATTACHMENT_SENDER_DOMAIN_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Webmail attachment origin metadata can reflect provider infrastructure, forwarding, cached attachments, or rewritten download URLs rather than sender-controlled infrastructure.'\n- 'Sender domains can be spoofed, compromised, delegated, or shared across unrelated senders, so this pivot needs strong message and file corroboration.'\ncapability_requirements:\n  required:\n  - 'mail_attachment_telemetry'\n  - 'file_hash_normalization'\n  optional:\n  - 'sender_authentication_results'\n  - 'endpoint_file_origin_telemetry'\nname: Webmail Attachment Sender Domain -> Files\ncategory: CTI\ndescription: Pivot from a sender domain seen in webmail attachment telemetry to attachment file hashes and endpoint observations.\nsource: email:sender:domain\ntarget: file:bytes|endpoint:uid\nassessment_mode: evidence_only\nhops:\n- via: sent_attachment\n  direction: out\n  form: file:bytes\n- via: observed_on\n  direction: out\n  form: endpoint:uid\nconstraints:\n  temporal:\n    order:\n    - message.received <= file.firstseen <= endpoint.observed\n    window_days: 30\n  degree_caps:\n    email:sender:domain: 100000\n  negative_nodes:\n  - form: email:sender:domain\n    list: consumer_webmail_provider_domains\n  - form: file:origin:url\n    list: webmail_provider_attachment_urls\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- sender_auth_alignment\n- endpoint_spread\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- mail_telemetry\n- edr\n- endpoint\n",
  "CTI_ENDPOINT_PROCESS_TO_REMOTE_CONNECTIONS": "id: CTI_ENDPOINT_PROCESS_TO_REMOTE_CONNECTIONS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Process-to-remote-connection joins can be distorted by proxy processes, browser helpers, service hosts, injected code, log forwarding, and endpoint telemetry gaps.'\n- 'Remote endpoints can be CDNs, update services, identity providers, scanners, or shared infrastructure rather than adversary-controlled destinations.'\n- 'Promotion needs fixtures for parent/child process context, proxy-process suppression, and destination negative controls before operational use.'\ncapability_requirements:\n  required:\n  - 'endpoint_process_telemetry'\n  - 'endpoint_network_telemetry'\n  optional:\n  - 'process_tree_reconstruction'\n  - 'proxy_process_classification'\nname: Endpoint Process -> Remote Connections\ncategory: CTI\ndescription: Pivot from an endpoint process observation to remote network destinations connected by that process.\nsource: endpoint:process\ntarget: inet:ipv4|inet:fqdn|network:connection\nassessment_mode: evidence_only\nhops:\n- via: opened_connection\n  direction: out\n  form: network:connection\n- via: connected_to\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - process.started <= connection.observed\n    window_days: 7\n  degree_caps:\n    endpoint:process: 100000\n    network:connection: 1000000\n  negative_nodes:\n  - form: endpoint:process\n    list: common_proxy_or_browser_helper_processes\n  - form: inet:fqdn\n    list: common_cdn_or_update_domains\n  - form: network:connection\n    list: scanner_or_security_product_connections\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- process_tree_depth\n- destination_role\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- edr\n- endpoint\n- netflow\n",
  "CTI_FILE_LSHASH_CLUSTER": "id: CTI_FILE_LSHASH_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Locality-sensitive hashes can overcluster files that share boilerplate, packers, libraries, templates, or benign build artifacts.'\n- 'Distance thresholds, hash-family configuration, and corpus composition strongly affect matches; promotion needs fixtures for positive, near-miss, and common-benign cases.'\n- 'An LSH match is a similarity lead, not proof of common authorship, common control, or actor attribution.'\ncapability_requirements:\n  required:\n  - 'file_lshash_extraction'\n  - 'file_hash_normalization'\n  optional:\n  - 'packer_detection'\n  - 'benign_corpus_prevalence'\nname: File LSHASH Cluster\ncategory: CTI\ndescription: Cluster files by locality-sensitive hash values while preserving threshold, corpus, and exact-hash context.\nsource: file:lshash\ntarget: file:hash\nassessment_mode: evidence_only\nhops:\n- via: similar_to\n  direction: out\n  form: file:hash\nconstraints:\n  temporal:\n    order:\n    - file.firstseen <= lshash.observed\n    window_days: 3650\n  degree_caps:\n    file:lshash: 100000\n    file:hash: 1000000\n  negative_nodes:\n  - form: file:lshash\n    list: common_library_or_packer_lshashes\n  - form: file:hash\n    list: common_benign_software_hashes\n  - form: file:lshash\n    list: low_entropy_or_short_lshash_values\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- similarity_threshold\n- corpus_scope\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- malware_corpus\n- sandbox\n- edr\n",
  "CTI_FILE_NAME_TO_HASHES": "id: CTI_FILE_NAME_TO_HASHES\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: enumeration\nhazards:\n- 'File names are highly reusable, localized, user-controlled, and often generic.'\n- 'Common tool names, archive contents, installers, and renamed malware can create large false-positive clusters.'\n- 'File-name pivots should remain exploratory unless paired with path, hash, signature, or behavioral evidence.'\ncapability_requirements:\n  required:\n  - 'file_name_normalization'\n  - 'file_hash_observation'\n  optional:\n  - 'common_filename_suppression'\n  - 'endpoint_context'\n  - 'sample_prevalence_enrichment'\nname: File Name -> Hashes\ncategory: CTI\ndescription: Pivot from a normalized file name to file hashes observed with that name in endpoint, malware-analysis, or file-reputation telemetry.\nsource: file:name\ntarget: file:hash\nassessment_mode: evidence_only\nhops:\n- via: observed_as_name\n  direction: in\n  form: file:hash\nconstraints:\n  temporal:\n    order:\n    - filename.observed <= file.observed\n    window_days: 180\n  degree_caps:\n    file:name: 100000\n    file:hash: 1000000\n  negative_nodes:\n  - form: file:name\n    list: common_system_or_tool_filenames\n  - form: file:hash\n    list: common_benign_file_hashes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- extension\n- filename_entropy\n- prevalence\n- common_filename_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- endpoint_telemetry\n- malware_analysis\n- file_reputation\n",
  "CTI_HTTP_HEADER_FINGERPRINT_CLUSTER": "id: CTI_HTTP_HEADER_FINGERPRINT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- Shared hosting, CDNs, reverse proxies, WAFs, load balancers, and managed application platforms can stamp common header sets across unrelated tenants.\n- Header order, casing, compression, cache state, redirect depth, and scanner request headers can change the observed fingerprint.\n- Generic framework, security, and server headers can cluster default deployments rather than operator-controlled infrastructure.\n- HTTP header fingerprints are weak structural selectors and should be corroborated with content, certificate, DNS, or timing evidence before analyst action.\ncapability_requirements:\n  required:\n  - http_response_collection\n  - header_normalization\n  - web_fingerprinting\n  optional:\n  - tls_scanning\n  - redirect_following\n  - historical_http_collection\nname: HTTP Header Fingerprint Cluster\ncategory: CTI\ndescription: Cluster webpages or services that expose the same normalized HTTP response-header fingerprint.\nsource: http:headers:fingerprint\ntarget: inet:fqdn|inet:url\nassessment_mode: evidence_only\nhops:\n- via: header_fingerprint_observed_on\n  direction: out\n  form: inet:url\n- via: served_by_host\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - header_fingerprint.seen <= response.seen <= host.seen\n    window_days: 180\n  degree_caps:\n    http:headers:fingerprint: 100000\n    inet:fqdn: 1000000\n  negative_nodes:\n  - form: http:headers:fingerprint\n    list: common_cdn_waf_or_framework_header_profiles\n  - form: http:headers:fingerprint\n    list: default_security_header_sets\n  - form: inet:fqdn\n    list: common_hosting_or_cdn_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- header_count\n- normalized_header_order\n- redirect_depth\n- platform_hint\n- common_header_profile_penalty\n- temporal_consistency\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- http_scanning\n- tls\n",
  "CTI_IMAGE_TEXT_REUSE_CLUSTER": "id: CTI_IMAGE_TEXT_REUSE_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- Stock imagery, memes, common logos, boilerplate text, reused screenshots, and public templates can overcluster unrelated actors or campaigns.\n- OCR output is sensitive to language, font, compression, cropping, watermarking, and model or extractor version.\n- Bounded semantic descriptions are model- and prompt-dependent; any future use must record extractor and prompt version before promotion.\n- Image-derived text reuse is a weak lead and must not be treated as common control or attribution without independent corroboration.\ncapability_requirements:\n  required:\n  - image_extraction\n  - ocr_extraction\n  - text_normalization\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - perceptual_hashing\n  - bounded_image_description\n  - language_detection\nname: Image Text Reuse Cluster\ncategory: CTI\ndescription: Find the particular preserved images whose evidenced OCR output has the\n  selected digest. A page result separately requires the exact page capture and image\n  association; crops and renders retain their own identities.\nsource: image:ocr:text_hash\ntarget: file:image|inet:url\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_IMAGE_TEXT_REUSE_CLUSTER.json\n  sha256: 2429a9a957e11d1267ae69ea89a81b0a28e5c24f4b33be9bedea61377c9ec587\nhops:\n- via: ocr_text_extracted_from\n  direction: in\n  form: file:image\n- via: image_observed_on\n  direction: out\n  form: inet:url\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- image_corpus\n- osint_web\n",
  "CTI_IP_TO_LISTING_ASSERTIONS": "id: CTI_IP_TO_LISTING_ASSERTIONS\nversion: 1.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_downstream_capability_mapping\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\ncapability_requirements:\n  required:\n  - semantic_execution_contract_v1\n  - source_revision_preservation\n  - explicit_claim_period\n  - scoped_amendment_history\n  optional:\n  - historical_network_association\n  - scoped_investigation_controls\nhazards:\n- List publication, claimed applicability and collection receipt are distinct times;\n  later receipt does not refresh historic activity.\n- Supplied corrections, withdrawals and disputes remain visible; complete source revision\n  history and current unwithdrawn status are not certified.\n- Shared hosting, one listed tenant or network association does not establish maliciousness,\n  ownership, control, liability or accepted assessment.\nname: IP to source listing assertions\ncategory: CTI\ndescription: Retrieve exact-address or explicitly applicable covering-prefix listing\n  claims for the selected IP and analyst/case period. Preserve source entry, revision\n  and all supplied amendments; no neighborhood, ASN-wide or current-unwithdrawn claim.\nsource: inet:ipv4\ntarget: reputation:assertion\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_IP_TO_LISTING_ASSERTIONS.json\n  sha256: fdeb8af7e172256e4c392a849543ba092b26fe389cced300151fc4ad28780c74\nhops:\n- via: subject_of_listing_assertion\n  direction: out\n  form: reputation:assertion\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- bgp\n- spamhaus\n- abuse_ch\n",
  "CTI_PE_SECTION_HASH_CLUSTER": "id: CTI_PE_SECTION_HASH_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'PE section hashes can reflect common runtimes, packers, resource templates, linked libraries, or compiler output rather than shared malicious logic.'\n- 'Section extraction is sensitive to malformed headers, overlay data, packing, and normalization choices.'\n- 'Promotion needs fixtures for exact section reuse, packed/benign suppressions, and near-collision cases before treating the pivot as operationally useful.'\ncapability_requirements:\n  required:\n  - 'pe_section_hash_extraction'\n  - 'file_hash_normalization'\n  optional:\n  - 'packer_detection'\n  - 'section_entropy_analysis'\nname: PE Section Hash Cluster\ncategory: CTI\ndescription: Cluster PE files by normalized section hashes while retaining section name, entropy, and file-hash context.\nsource: file:pe:section:hash\ntarget: file:hash\nassessment_mode: evidence_only\nhops:\n- via: section_observed_in\n  direction: out\n  form: file:hash\nconstraints:\n  temporal:\n    order:\n    - file.firstseen <= section_hash.observed\n    window_days: 3650\n  degree_caps:\n    file:pe:section:hash: 100000\n    file:hash: 1000000\n  negative_nodes:\n  - form: file:pe:section:hash\n    list: common_runtime_or_library_section_hashes\n  - form: file:pe:section:hash\n    list: packer_stub_section_hashes\n  - form: file:hash\n    list: common_benign_software_hashes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- section_name\n- entropy_bucket\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- malware_corpus\n- sandbox\n- edr\n",
  "CTI_PHISHKIT_TO_HOSTING_CLUSTER": "id: CTI_PHISHKIT_TO_HOSTING_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - web_content_collection\n  - phishing_kit_hashing\n  - semantic_execution_contract_v1\n  - exact_content_hash_reproduction\n  - exact_file_set_manifest_v1\n  - source_qualified_deployment_correspondence\n  - scoped_control_evaluation\n  optional:\n  - passive_dns\n  - hosting_provider_classification\nhazards:\n- Public kits, generic paths and shared components can connect unrelated deployments;\n  actual correspondence must remain scoped.\n- A matching archive offered for download, bare request, DNS record or peer address\n  does not establish deployment of its contents.\n- Research/test/sinkhole controls apply to the evidenced occurrence; shared hosting\n  is context, not blanket exclusion.\n- Receipt and source-reported substantive derivation guide search only; copies do\n  not create deployment, novelty, independent origins or actor identity.\nname: Phish Kit → Hosting Domain/IP Cluster\ncategory: CTI\ndescription: Compare preserved kit representations, then require separately evidenced\n  deployment of the same candidate for infrastructure results. Preserve generic/component\n  clues and explicit baseline references; 180 days guides evidence search priority,\n  not activity eligibility.\nsource: phish:kit\ntarget: inet:fqdn|inet:ipv4|evidence:deployment_reference|evidence:kit_comparison_clue\nassessment_mode: evidence_only\nhops:\n- via: yields_evidence_for\n  direction: out\n  form: inet:fqdn|inet:ipv4|evidence:deployment_reference|evidence:kit_comparison_clue\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- phishtank\n- abuse_ch\n- osint_web\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_PHISHKIT_TO_HOSTING_CLUSTER.json\n  sha256: 8a2928f2ac514e3242f3676e67052dc3cd6589e922a7569a457a7927c38b6784\n",
  "CTI_QR_PAYLOAD_REUSE_CLUSTER": "id: CTI_QR_PAYLOAD_REUSE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- Public QR generators, demo payloads, venue signage, shared payment flows, and URL shorteners can create unrelated decoded-payload reuse.\n- Image quality, cropping, rotation, compression, and QR error correction can change decode success or produce partial payloads.\n- Decoded payloads may contain personal, payment, access-token, or invite-link material and require minimization before publication or sharing.\n- QR payload reuse is a lead for follow-on analysis only; it does not imply common control, campaign membership, or malicious intent without corroboration.\ncapability_requirements:\n  required:\n  - image_extraction\n  - qr_decode\n  - payload_normalization\n  optional:\n  - barcode_decode\n  - ocr_extraction\n  - url_unshortening\n  - payment_address_parsing\nname: QR Payload Reuse Cluster\ncategory: CTI\ndescription: Cluster campaign assets or webpages that reuse the same normalized decoded QR payload.\nsource: visual:qr_payload\ntarget: inet:url|payment:address|identity:account|file:image\nassessment_mode: evidence_only\nhops:\n- via: decoded_from_image\n  direction: in\n  form: file:image\n- via: payload_resolves_to\n  direction: out\n  form: inet:url|payment:address|identity:account\nconstraints:\n  temporal:\n    order:\n    - qr_payload.decoded <= asset.observed\n    window_days: 365\n  degree_caps:\n    visual:qr_payload: 10000\n    inet:url: 1000000\n  negative_nodes:\n  - form: visual:qr_payload\n    list: demo_or_test_qr_payloads\n  - form: inet:url\n    list: mainstream_url_shorteners_or_shared_payment_landing_pages\n  - form: payment:address\n    list: high_volume_shared_payment_or_bridge_addresses\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- payload_type\n- decode_confidence_bucket\n- image_context\n- shared_provider_penalty\n- sensitive_payload_flag\n- temporal_consistency\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- image_corpus\n- document_assets\n",
  "CTI_SAMPLE_COMPILATION_TIMESTAMP_CLUSTER": "id: CTI_SAMPLE_COMPILATION_TIMESTAMP_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Compilation timestamps can be forged, zeroed, rounded, inherited from templates, or rewritten by packers.'\n- 'Common build pipelines can create many samples in tight time windows without shared malicious provenance.'\n- 'Timestamp clustering should remain exploratory unless combined with stronger static or infrastructure selectors.'\ncapability_requirements:\n  required:\n  - 'sample_static_analysis'\n  - 'compilation_timestamp_extraction'\n  optional:\n  - 'timestamp_anomaly_detection'\n  - 'packer_detection'\n  - 'sample_prevalence_enrichment'\nname: Sample Compilation Timestamp Cluster\ncategory: CTI\ndescription: Cluster samples with matching or tightly bounded compilation timestamps after normalization and common-build suppression.\nsource: file:metadata:compile_time\ntarget: file:hash\nassessment_mode: evidence_only\nhops:\n- via: compile_time_of\n  direction: in\n  form: file:hash\nconstraints:\n  temporal:\n    order:\n    - compile_time.value <= sample.observed\n    window_days: 365\n  degree_caps:\n    file:metadata:compile_time: 100000\n    file:hash: 1000000\n  negative_nodes:\n  - form: file:metadata:compile_time\n    list: forged_or_default_compile_timestamps\n  - form: file:hash\n    list: common_benign_file_hashes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- time_bucket\n- timestamp_plausibility\n- packer_flag\n- prevalence\n- common_timestamp_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- malware_analysis\n- file_reputation\n",
  "CTI_SAMPLE_FUNCTION_NAME_CLUSTER": "id: CTI_SAMPLE_FUNCTION_NAME_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Function names can come from public source, libraries, debug symbols, decompiler guesses, or common frameworks.'\n- 'Stripped binaries and compiler optimization can remove or distort function-name evidence.'\n- 'Function-name clusters need library suppression and corroborating static or behavioral evidence.'\ncapability_requirements:\n  required:\n  - sample_static_analysis\n  - function_name_extraction\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - symbol_source_context\n  - sample_prevalence_enrichment\nname: Sample Function Name Cluster\ncategory: CTI\ndescription: Find preserved samples with the selected recovered function name. External\n  debug material additionally requires preserved symbol bytes and explicit sample\n  correspondence; later processing does not refresh an equivalent finding.\nsource: file:feature:function_name\ntarget: file:hash\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_SAMPLE_FUNCTION_NAME_CLUSTER.json\n  sha256: d3dd52dcb6475f0982b62e7cda22a83458f1d6d6363664ff4e7cfb88ea3708c0\nhops:\n- via: function_name_extracted_from\n  direction: in\n  form: file:hash\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- malware_analysis\n- file_reputation\n",
  "CTI_SAMPLE_RESOURCE_SECTION_HASH_CLUSTER": "id: CTI_SAMPLE_RESOURCE_SECTION_HASH_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Resource section hashes can group common packers, compilers, icons, manifests, or benign library resources.'\n- 'Minor rebuilds and localization changes can alter resource hashes while preserving functional similarity.'\n- 'The pivot should be paired with prevalence and negative controls for common toolchains before promotion.'\ncapability_requirements:\n  required:\n  - sample_static_analysis\n  - resource_section_hashing\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - packer_detection\n  - sample_prevalence_enrichment\nname: Sample Resource Section Hash Cluster\ncategory: CTI\ndescription: Find samples with the SHA-256 of actual preserved selected resource-section\n  bytes. The declared section and selection recipe remain evidence context; normalized\n  or fuzzy hashes require another explicit contract.\nsource: file:resource_section:hash\ntarget: file:hash\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_SAMPLE_RESOURCE_SECTION_HASH_CLUSTER.json\n  sha256: ae6f23a5a0b4524d0fb530083868877715046cc6b3a829cd93b9ca747e298aa0\nhops:\n- via: resource_section_hash_of\n  direction: in\n  form: file:hash\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- malware_analysis\n- file_reputation\n",
  "CTI_SAMPLE_UNIQUE_STRING_CLUSTER": "id: CTI_SAMPLE_UNIQUE_STRING_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Strings can be copied from public source, libraries, compiler output, debug text, or benign dependencies.'\n- 'Short, localized, encoded, or common strings create noisy clusters.'\n- 'String pivots require rarity, context, and negative controls before they should influence analyst conclusions.'\ncapability_requirements:\n  required:\n  - sample_string_extraction\n  - string_normalization\n  - semantic_execution_contract_v1\n  - preserved_extraction_v1\n  - exact_content_hash_reproduction\n  - complete_finding_history\n  - scoped_control_evaluation\n  optional:\n  - sample_prevalence_enrichment\nname: Sample Unique String Cluster\ncategory: CTI\ndescription: Find preserved samples with an evidenced extraction of the exact representation-qualified\n  string. A rare or incongruent string is a candidate clue; reuse alone does not establish\n  common control or attribution.\nsource: file:feature:string\ntarget: file:hash\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_SAMPLE_UNIQUE_STRING_CLUSTER.json\n  sha256: a0e0478b5d89a59a76aa232fe2fdcba203cbb1a7d50566baa6b4c289433ec619\nhops:\n- via: string_extracted_from\n  direction: in\n  form: file:hash\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- malware_analysis\n- file_reputation\n",
  "CTI_SBL_HOSTING_RISK": "id: CTI_SBL_HOSTING_RISK\nversion: 3.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'explicit_successor_selection'\n  optional:\n  - 'passive_dns'\n  - 'hosting_provider_classification'\nhazards:\n- Deprecated compatibility definition without executable semantics. Select the IP listing, explicit ASN listing, or ASN-associated infrastructure successor; no automatic rewrite is valid.\n- Abuse blocklists, SBL entries, and hosting ASN reputation can lag cleanup or reflect one customer inside shared infrastructure.\n- Corroborate listing history with current observations; risk scoring should not label all tenants of a provider as malicious.\n- Provider-level reputation is hosting-risk context only and must not be treated as tenant-specific maliciousness, ownership, or control.\nname: Deprecated IP/ASN Hosting Reputation Compatibility Definition\ncategory: CTI\ndescription: Retained historical identifier only. Use CTI_IP_TO_LISTING_ASSERTIONS for publisher assertions about an IP, CTI_ASN_TO_EXPLICIT_LISTING_ASSERTIONS for assertions explicitly naming an ASN, or CTI_ASN_TO_LISTED_INFRASTRUCTURE for separately evidenced ASN-associated listed infrastructure. No scoring, provider-wide risk, tenant inference, or executable traversal is defined here.\nsource: inet:ipv4\ntarget: net:asn\nassessment_mode: evidence_only\nhops:\n- via: bgp_origin|asn_of\n  direction: out\n  form: net:asn\n- via: reputation_of\n  direction: out\n  form: reputation:list\nconstraints:\n  provenance:\n    min_unique_sources: 1\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- bgp\n- spamhaus\n- abuse_ch\n",
  "CTI_SHORT_LIVED_CERT_INFRA_CLUSTER": "id: CTI_SHORT_LIVED_CERT_INFRA_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_SHORT_LIVED_CERT_INFRA_CLUSTER.json\n  sha256: 110bf1752bdc67ea58c1c8eee0472a328693c125792e87f2f87c013710cba4a0\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- The preserved identified profile declares every compared field, exact value or inclusive\n  range and definition revision. A sparse search does not authorize silent broadening\n  or a similarity fallback.\n- Matching subject or issuer labels and declared validity duration do not establish\n  certificate/key identity, actual issuer identity, ACME issuance, deployment lifetime,\n  maliciousness or common control.\n- The same identified matching certificate must be carried into an actual service\n  presentation. CT-only names, copied fields or nearby endpoints do not supply the\n  join.\n- The analyst/case-selected UTC presentation period is independent of profile duration\n  criteria, profile creation, receipt and analytical knowledge. Presentation outside\n  declared certificate validity is retained.\n- Common/default/managed and infrastructure classifications are separate source-qualified\n  context. Exclusions require explicit scoped policies; unknown or conflicting evidence\n  is not clearance.\ncapability_requirements:\n  required:\n  - semantic_evidence_v1\n  - certificate_normalization\n  - preserved_certificate_profile_v1\n  - source_bound_certificate_fields\n  - presentation_occurrence_and_endpoint_correspondence\n  optional:\n  - collection_knowledge_witnesses\n  - source_classification_evidence\n  - tls_scanning\n  - certificate_transparency\nname: Explicit Declared-Validity Duration Profile → Certificate Presentations\ncategory: CTI\ndescription: Presentation of an actual identified certificate meeting an explicitly\n  preserved short_lived profile; profile revision, field criteria and candidate occurrence\n  period remain distinct.\nsource: x509:comparison_profile\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: explicit_profile_matches\n  direction: out\n  form: x509:cert\n- via: observed_certificate_presentation\n  direction: out\n  form: inet:service\n- via: evidenced_occurrence_endpoint\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- tls\n- ct\n",
  "CTI_THREAT_CVE_TOOL_IP": "id: CTI_THREAT_CVE_TOOL_IP\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'cti_report_extraction'\n  - 'vulnerability_intelligence'\n  - 'passive_dns'\n  optional:\n  - 'tool_family_normalization'\n  - 'ip_normalization'\nhazards:\n- Named threat, CVE, and tool reports can be broad, stale, or based on public exploit adoption by unrelated actors.\n- Corroborate IP links with observation time, tool telemetry, and independent reporting; the chain does not prove threat attribution.\n- Named-threat labels are report context; do not infer actor ownership or operational control of infrastructure from co-mentions.\nname: Threat → CVE → Tool → IP\ncategory: CTI\ndescription: Pivot from a report-derived named-threat, CVE, and tool-family co-mention to contextual IP infrastructure observations.\nsource: risk:threat\ntarget: inet:ipv4\nassessment_mode: evidence_only\nhops:\n- via: refs\n  direction: out\n  form: it:sec:vuln\n- via: uses|delivers|exploits\n  direction: out\n  form: it:prod:soft\n- via: communicates|hosts|connects\n  direction: out\n  form: inet:ipv4\nconstraints:\n  temporal:\n    order:\n    - threat.firstseen <= vuln.published\n    - vuln.published <= ip.seen\n    window_days: 540\n  degree_caps:\n    it:prod:soft: 300\n  negative_nodes:\n  - form: inet:ipv4\n    list: known_vpn_exits\n  - form: inet:ipv4\n    list: cdn_edges\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cti_reports\n- nvd_cve\n- pdns\n- siem\n",
  "CTI_THREAT_TOOLS_SHARED_INFRA": "id: CTI_THREAT_TOOLS_SHARED_INFRA\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'cti_report_extraction'\n  - 'tool_family_normalization'\n  optional:\n  - 'passive_dns'\n  - 'cluster_feature_export'\nhazards:\n- Commodity tools and public malware builders can create common infrastructure features across unrelated threats.\n- Corroborate shared infrastructure with campaign timing and multiple evidence paths; do not infer actor relationship from tool overlap alone.\n- Threat labels and tool overlap must remain reported context and must not imply shared operator identity, sponsorship, or common control.\nname: Threat ↔ Threat via Shared Tool/Infra\ncategory: CTI\ndescription: Suggest related threats when their tool families lead to overlapping infrastructure.\nsource: risk:threat\ntarget: risk:threat\nassessment_mode: evidence_only\nhops:\n- via: uses\n  direction: out\n  form: it:prod:soft\n- via: communicates|c2|hosts\n  direction: out\n  form: inet:fqdn|inet:ipv4\n- via: hosts|resolves|pdns_resolves\n  direction: in\n  form: it:prod:soft\n- via: used_by\n  direction: in\n  form: risk:threat\nconstraints:\n  temporal:\n    order:\n    - threatA.firstseen <= infra.seen\n    - infra.seen <= threatB.lastseen\n    window_days: 540\n  degree_caps:\n    it:prod:soft: 300\n  negative_nodes:\n  - form: inet:ipv4\n    list: cdn_edges\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n- siem\n- cti_reports\n",
  "CTI_THREAT_TOOL_FQDN_IP": "id: CTI_THREAT_TOOL_FQDN_IP\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'cti_report_extraction'\n  - 'passive_dns'\n  optional:\n  - 'tool_family_normalization'\n  - 'ip_normalization'\nhazards:\n- DNS history can include sinkholes, shared hosting, CDNs, parking, and reassigned IPs unrelated to the tool operator.\n- Corroborate domain-to-IP timing with tool-family evidence; current resolutions alone are not attribution.\n- Named-threat and tool labels are report context; do not infer actor ownership or control of FQDNs or IPs from the chain.\nname: Threat → Tool → FQDN → IP\ncategory: CTI\ndescription: Tool-family infrastructure discovery via observed domains and their current/previous IPs.\nsource: risk:threat\ntarget: inet:ipv4\nassessment_mode: evidence_only\nhops:\n- via: uses\n  direction: out\n  form: it:prod:soft\n- via: communicates|hosts|connects|c2\n  direction: out\n  form: inet:fqdn\n- via: resolves|pdns_resolves\n  direction: out\n  form: inet:ipv4\nconstraints:\n  temporal:\n    order:\n    - threat.firstseen <= fqdn.created\n    - fqdn.created <= ip.seen\n    window_days: 720\n  degree_caps:\n    it:prod:soft: 300\n    inet:fqdn: 500\n  negative_nodes:\n  - form: inet:fqdn\n    list: dynamic_dns_providers\n  - form: inet:fqdn\n    list: public_resolvers\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n- siem\n- misp\n- abuse_ch\n- cti_reports\n",
  "CTI_TLS_CERT_SUBJECT_PROFILE_TO_INFRA": "id: CTI_TLS_CERT_SUBJECT_PROFILE_TO_INFRA\nversion: 3.0.0\npattern_schema_version: 1.6\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/CTI_TLS_CERT_SUBJECT_PROFILE_TO_INFRA.json\n  sha256: 390a1d45491538848dfe2f16dc3cd8e049116aa701520feb35c6f204057182d8\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- The preserved identified profile declares every compared field, exact value or inclusive\n  range and definition revision. A sparse search does not authorize silent broadening\n  or a similarity fallback.\n- Matching subject or issuer labels and declared validity duration do not establish\n  certificate/key identity, actual issuer identity, ACME issuance, deployment lifetime,\n  maliciousness or common control.\n- The same identified matching certificate must be carried into an actual service\n  presentation. CT-only names, copied fields or nearby endpoints do not supply the\n  join.\n- The analyst/case-selected UTC presentation period is independent of profile duration\n  criteria, profile creation, receipt and analytical knowledge. Presentation outside\n  declared certificate validity is retained.\n- Common/default/managed and infrastructure classifications are separate source-qualified\n  context. Exclusions require explicit scoped policies; unknown or conflicting evidence\n  is not clearance.\ncapability_requirements:\n  required:\n  - semantic_evidence_v1\n  - certificate_normalization\n  - preserved_certificate_profile_v1\n  - source_bound_certificate_fields\n  - presentation_occurrence_and_endpoint_correspondence\n  optional:\n  - collection_knowledge_witnesses\n  - source_classification_evidence\n  - tls_scanning\n  - certificate_transparency\nname: Explicit Subject Profile → Certificate Presentations\ncategory: CTI\ndescription: Presentation of an actual identified certificate meeting an explicitly\n  preserved subject profile; profile revision, field criteria and candidate occurrence\n  period remain distinct.\nsource: x509:comparison_profile\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: explicit_profile_matches\n  direction: out\n  form: x509:cert\n- via: observed_certificate_presentation\n  direction: out\n  form: inet:service\n- via: evidenced_occurrence_endpoint\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- certificate_transparency\n- internet_scan_archives\n- osint_web\n",
  "CTI_TOOL_RELAY_INFRA_CLUSTER": "id: CTI_TOOL_RELAY_INFRA_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'tool_family_normalization'\n  - 'passive_dns'\n  optional:\n  - 'asn_enrichment'\n  - 'hosting_provider_classification'\nhazards:\n- Relay infrastructure may use shared VPNs, proxies, cloud providers, or commodity tooling reused by unrelated operators.\n- Corroborate ASN and PDNS co-location with temporal overlap and tool-specific evidence; common hosting is a false-positive source.\n- Relay co-location should be suppressed for provider VPN, proxy, and cloud infrastructure and is not proof of operator ownership.\nname: Tool Family → Relay/Proxy Infra Cluster\ncategory: CTI\ndescription: Find relay infrastructure linked to a tool family via shared hosting, ASN, and pdns co-location.\nsource: it:prod:soft\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: communicates|relays_through\n  direction: out\n  form: inet:ipv4|inet:fqdn\n- via: bgp_origin|asn_of\n  direction: out\n  form: net:asn\n- via: announces|hosts_many\n  direction: out\n  form: inet:ipv4\nconstraints:\n  temporal:\n    order:\n    - tool.firstseen <= infra.seen\n    window_days: 540\n  degree_caps:\n    net:asn: 1000\n  negative_nodes:\n  - form: net:asn\n    list: known_scanner_asns\n  - form: inet:ipv4\n    list: shared_hosting_ranges\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n- bgp\n- siem\n",
  "CTI_URLHAUS_REPO_COOCCURRENCE_INFRA": "id: CTI_URLHAUS_REPO_COOCCURRENCE_INFRA\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Code repositories frequently contain copied indicators, sample configs, blocklists, tests, or security research artifacts unrelated to operator infrastructure.'\n- 'Repository co-occurrence can inflate weak associations unless commit provenance, file context, and benign-project filters are preserved.'\n- 'Common sample repositories and shared indicator lists need corroboration with commit context before linking infrastructure.'\ncapability_requirements:\n  required:\n  - 'abuse_ch_urlhaus'\n  - 'code_search'\n  - 'git_metadata'\n  optional:\n  - 'secret_scanning_context'\n  - 'repository_reputation'\nname: URLhaus Repo Co-Occurrence -> Infra\ncategory: CTI\ndescription: Pivot from abuse-listed infrastructure through code-repository co-occurrence to additional domains or IPs, preserving repository and extraction provenance.\nsource: inet:ipv4|inet:fqdn|inet:url\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: listed_by\n  direction: out\n  form: abuse:urlhaus:record\n- via: appears_in\n  direction: out\n  form: code:repo\n- via: co_occurs_with\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - abuse.firstseen <= repo.commit_time <= target.firstseen\n    window_days: 3650\n  degree_caps:\n    abuse:urlhaus:record: 1000\n    code:repo: 5000\n  negative_nodes:\n  - form: code:repo\n    list: mass_fork_mirrors\n  - form: code:repo\n    list: benign_security_research_repos\n  - form: inet:fqdn\n    list: package_registry_domains\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- repo_file_context_weight\n- cooccurrence_count\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- abuse_ch\n- code_search\n- git_metadata\n- url_corpus\n",
  "CTI_WEBPAGE_SCRIPT_BEHAVIOR_CLUSTER": "id: CTI_WEBPAGE_SCRIPT_BEHAVIOR_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Script behavior can be framework-driven, environment-dependent, obfuscated, or shared by benign templates.'\n- 'Dynamic analysis can observe scanner artifacts, consent banners, anti-bot logic, or security products rather than malicious page logic.'\n- 'Behavior clusters require negative controls and should not imply page ownership or actor attribution.'\ncapability_requirements:\n  required:\n  - 'webpage_dynamic_analysis'\n  - 'script_behavior_fingerprinting'\n  optional:\n  - 'javascript_hashing'\n  - 'dom_snapshot_collection'\n  - 'benign_template_suppression'\nname: Webpage Script Behavior Cluster\ncategory: CTI\ndescription: Cluster webpages that exhibit the same normalized script behavior fingerprint during rendering or interaction.\nsource: web:behavior:fingerprint\ntarget: inet:url|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: behavior_observed_on_page\n  direction: in\n  form: inet:url\n- via: has_host\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - behavior.observed <= page.observed\n    window_days: 90\n  degree_caps:\n    web:behavior:fingerprint: 100000\n    inet:url: 1000000\n  negative_nodes:\n  - form: web:behavior:fingerprint\n    list: common_framework_or_consent_behaviors\n  - form: inet:fqdn\n    list: common_hosting_or_cdn_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- behavior_event_count\n- dom_context\n- dynamic_rendering_flag\n- benign_template_penalty\n- temporal_consistency\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- url_corpus\n- web_dynamic_analysis\n",
  "CTI_WEB_CLIENT_UID_TO_ENDPOINTS": "id: CTI_WEB_CLIENT_UID_TO_ENDPOINTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Browser/client identifiers do not inherently identify an endpoint; they can map to browser profiles, accounts, cookie jars, devices, or vendor-local telemetry identities.'\n- 'Endpoint joins can be inflated by shared devices, roaming profiles, virtual desktops, proxy attribution, log forwarding, or stale inventory bindings.'\n- 'A browser/client UID to endpoint match is not actor attribution and needs independent endpoint telemetry before operational use.'\ncapability_requirements:\n  required:\n  - 'browser_client_uid_normalization'\n  - 'endpoint_binding_telemetry'\n  optional:\n  - 'edr_device_identity_resolution'\n  - 'proxy_endpoint_join'\n  - 'identity_inventory_join'\nname: Web Client UID -> Endpoints\ncategory: CTI\ndescription: Pivot from a normalized browser or web client identifier to endpoint identities only when telemetry provides an explicit client-to-endpoint binding.\nsource: web:client:uid\ntarget: endpoint:uid\nassessment_mode: evidence_only\nhops:\n- via: observed_in_request\n  direction: out\n  form: http:request\n- via: bound_to\n  direction: out\n  form: endpoint:uid\nconstraints:\n  temporal:\n    order:\n    - client_uid.observed <= endpoint_binding.observed\n    window_days: 30\n  degree_caps:\n    web:client:uid: 100000\n    endpoint:uid: 10000\n  negative_nodes:\n  - form: endpoint:uid\n    list: shared_or_kiosk_endpoints\n  - form: endpoint:uid\n    list: virtual_desktop_or_terminal_hosts\n  - form: http:request\n    list: proxy_attributed_requests\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- binding_source_type\n- endpoint_binding_stability\n- shared_endpoint_penalty\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- proxy_logs\n- browser_telemetry\n- edr\n- endpoint\n",
  "CTI_WEB_SEARCH_QUERY_TO_CLIENT_UIDS": "id: CTI_WEB_SEARCH_QUERY_TO_CLIENT_UIDS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Web search query pivots are privacy-sensitive and should remain deferred unless queries are minimized to a narrow atomic relationship with strict publication controls.'\n- 'Queries can be generic, copied, suggested, auto-completed, translated, or generated by scanners and browser features.'\n- 'A shared query and client UID relationship is behavioral context, not actor attribution or proof of user intent.'\ncapability_requirements:\n  required:\n  - 'web_search_query_telemetry'\n  - 'browser_client_uid_normalization'\n  optional:\n  - 'query_minimization'\n  - 'scanner_prefetch_suppression'\nname: Web Search Query -> Client UIDs\ncategory: CTI\ndescription: Pivot from a minimized web search query observation to browser or web client identifiers seen with that query.\nsource: web:search:query\ntarget: web:client:uid\nassessment_mode: evidence_only\nhops:\n- via: observed_with_client\n  direction: out\n  form: web:client:uid\nconstraints:\n  temporal:\n    order:\n    - query.observed <= client_uid.observed\n    window_days: 7\n  degree_caps:\n    web:search:query: 10000\n    web:client:uid: 100000\n  negative_nodes:\n  - form: web:search:query\n    list: common_or_autocomplete_queries\n  - form: web:search:query\n    list: privacy_sensitive_queries_excluded_from_publication\n  - form: web:client:uid\n    list: scanner_or_automation_client_ids\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- query_minimization_level\n- client_context\n- novelty_flag\noutputs:\n  top_paths: 10\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- restricted_search_telemetry\n- browser_telemetry\n",
  "FIN_BANK_TXN_TO_SANCTIONED_COUNTERPART": "id: FIN_BANK_TXN_TO_SANCTIONED_COUNTERPART\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - financial_records\n  - sanctions_list_access\n  - semantic_execution_contract_v1\n  - source_revision_scoped_relations\n  - explicit_temporal_applicability\n  - amendment_context\n  optional:\n  - kyc_context\n  - payment_chain_context\nhazards:\n- Sanctions screening and transaction data are sensitive, regulated, and time-dependent;\n  list membership can change after the transaction date.\n- Shared accounts, correspondents, and intermediaries can create false positives;\n  corroborate with KYC and payment-chain context.\n- Source-reported identity, relationship and list status require separate evidence;\n  no traversal supplies legal exposure, liability, control, source independence or\n  accepted assessment status.\n- A selected historical-status inquiry requires the actual applicable relationship\n  and list intervals. Later publication, receipt and correction do not backdate analyst\n  knowledge or refresh activity.\nname: Bank Transaction → Counterparty Sanctions Entries\ncategory: FIN\ndescription: Follow the reported counterparty of an individual bank transaction to\n  selected sanctions entry revisions. Preserve party direction, actual event time,\n  identity correspondence and corrections; the traversal makes no legal determination.\nsource: fin:account\ntarget: sanction:entry\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/FIN_BANK_TXN_TO_SANCTIONED_COUNTERPART.json\n  sha256: 5b9bea0d53b5db19efcfbc9ddb3e7edf100889f2b7372c69d44c354f1c0f6772\nhops:\n- via: transfers_to|transfers_from\n  direction: out\n  form: fin:transaction\n- via: counterparty\n  direction: out\n  form: org:org|person\n- via: listed_as\n  direction: out\n  form: sanction:entry\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- bank_txn\n- sanctions\n",
  "FIN_BENEFICIAL_OWNER_TO_SANCTIONS": "id: FIN_BENEFICIAL_OWNER_TO_SANCTIONS\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - financial_records\n  - identity_records\n  - sanctions_list_access\n  - semantic_execution_contract_v1\n  - source_revision_scoped_relations\n  - explicit_temporal_applicability\n  - amendment_context\n  optional:\n  - beneficial_ownership_resolution\n  - entity_normalization\nhazards:\n- Beneficial-ownership records can be stale, nominee-based, shared by service providers,\n  jurisdiction-limited, or inconsistent across registries.\n- Source-reported identity, relationship and list status require separate evidence;\n  no traversal supplies legal exposure, liability, control, source independence or\n  accepted assessment status.\n- A selected historical-status inquiry requires the actual applicable relationship\n  and list intervals. Later publication, receipt and correction do not backdate analyst\n  knowledge or refresh activity.\nname: Reported Beneficial Owner → Entities → Sanctions Entries\ncategory: FIN\ndescription: Follow a source-reported beneficial-owner relationship to the named entity\n  and selected sanctions entry revisions. Preserve the reported category, basis, interest\n  and applicable period; beneficial ownership alone does not establish control.\nsource: person\ntarget: sanction:entry\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/FIN_BENEFICIAL_OWNER_TO_SANCTIONS.json\n  sha256: 6d02d253a098f7e9b3484bb3d27b103e7be3cd7badd264e885ad70c0e5986ef0\nhops:\n- via: beneficial_owner_of\n  direction: out\n  form: org:org\n- via: listed_as\n  direction: out\n  form: sanction:entry\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- lei\n- opencorp\n- sanctions\n",
  "FIN_CRYPTO_OFFRAMP_COUNTERPARTY_CLUSTER": "id: FIN_CRYPTO_OFFRAMP_COUNTERPARTY_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'crypto_transaction_enrichment'\n  optional:\n  - 'kyc_context'\n  - 'offramp_account_resolution'\nhazards:\n- Exchange deposit addresses, processors, mixers, and omnibus accounts can group unrelated crypto users.\n- Off-ramp data is restricted financial and KYC evidence; corroborate shared account links with timing and transaction context to avoid false positives.\nname: Crypto Address -> Off-Ramp Counterparty Cluster\ncategory: FIN\ndescription: Trace recurring crypto addresses through withdrawal or cash-out paths to shared off-ramp accounts, merchants, or beneficiary entities.\nsource: crypto:address\ntarget: fin:account|fin:merchant|org:org\nassessment_mode: evidence_only\nhops:\n- via: transfers_to|transfers_from\n  direction: out\n  form: ledger:tx\n- via: cashed_out_via\n  direction: out\n  form: fin:account|fin:merchant|org:org\nconstraints:\n  temporal:\n    order:\n    - address.firstseen <= tx.ts\n    window_days: 3650\n  degree_caps:\n    ledger:tx: 100000\n  negative_nodes:\n  - form: crypto:address\n    list: exchange_hot_wallets\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- blockchain\n- bank_txn\n- payments\n",
  "FIN_CRYPTO_TX_TO_SANCTIONED": "id: FIN_CRYPTO_TX_TO_SANCTIONED\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - financial_records\n  - crypto_transaction_enrichment\n  - sanctions_list_access\n  - semantic_execution_contract_v1\n  - source_revision_scoped_relations\n  - explicit_temporal_applicability\n  - amendment_context\n  optional:\n  - address_cluster_context\n  - transaction_timing_context\nhazards:\n- Blockchain heuristics can over-attribute flows through mixers, exchanges, bridges,\n  or shared custody accounts.\n- Sanctions lists and address clusters are temporal; corroborate transaction timing\n  and ownership before drawing compliance conclusions.\n- Compliance, exchange, and customer-identification evidence may be regulated or restricted\n  and must be governed before use.\n- Source-reported identity, relationship and list status require separate evidence;\n  no traversal supplies legal exposure, liability, control, source independence or\n  accepted assessment status.\n- A selected historical-status inquiry requires the actual applicable relationship\n  and list intervals. Later publication, receipt and correction do not backdate analyst\n  knowledge or refresh activity.\nname: Crypto Transaction → Referenced Sanctions Entries\ncategory: FIN\ndescription: Follow an actual source-reported transaction endpoint and separately\n  evidenced listed-subject correspondence to selected sanctions entry revisions. Retrospective\n  discovery and source-stated historical status are explicit distinct inquiries.\nsource: crypto:address\ntarget: sanction:entry\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/FIN_CRYPTO_TX_TO_SANCTIONED.json\n  sha256: 00ad8eb37c88937a35b72bf86d8481d50a8b1aabda668c63cf3c099598af0045\nhops:\n- via: transfers_to|transfers_from\n  direction: out\n  form: ledger:tx\n- via: to|from\n  direction: out\n  form: crypto:address\n- via: listed_as\n  direction: out\n  form: sanction:entry\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- blockchain\n- sanctions\n",
  "FIN_KYC_DOCUMENT_REUSE_CLUSTER": "id: FIN_KYC_DOCUMENT_REUSE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'identity_records'\n  - 'document_hash_normalization'\n  optional:\n  - 'kyc_context'\n  - 'document_template_suppression'\nhazards:\n- Shared scanners, stock document samples, templates, or document-theft victims can create false identity clusters.\n- KYC documents are sensitive personal data; use only with lawful access and corroborate with account behavior and verified fraud context.\nname: KYC Document Hash -> Identity Cluster\ncategory: FIN\ndescription: Cluster people or accounts reusing the same KYC document image, scan, or canonical document hash.\nsource: file:bytes\ntarget: person|fin:account\nassessment_mode: evidence_only\nhops:\n- via: submitted_for\n  direction: out\n  form: person|fin:account\nconstraints:\n  temporal:\n    order:\n    - document.seen <= account.opened\n    window_days: 3650\n  degree_caps:\n    file:bytes: 500\n  negative_nodes:\n  - form: file:bytes\n    list: known_template_documents\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- kyc\n- fraud_ops\n",
  "FIN_MULE_RECRUITMENT_SOCIAL_TO_PAYOUT": "id: FIN_MULE_RECRUITMENT_SOCIAL_TO_PAYOUT\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'social_profile_collection'\n  optional:\n  - 'payout_account_normalization'\n  - 'recruitment_context_extraction'\nhazards:\n- Recruitment posts, handles, and payment instructions can be copied, impersonated, or reused by intermediaries.\n- Payout account data is restricted financial evidence; corroborate temporal account control and recruitment context before identifying mule networks.\nname: Recruitment Persona -> Payout Account\ncategory: FIN\ndescription: Tie mule-recruitment personas or social handles to payout accounts advertised, routed, or onboarded through recruitment channels.\nsource: social:handle\ntarget: fin:account\nassessment_mode: evidence_only\nhops:\n- via: advertises\n  direction: out\n  form: web:url|message:channel\n- via: routes_to\n  direction: out\n  form: fin:account\nconstraints:\n  temporal:\n    order:\n    - persona.seen <= channel.seen <= account.firstseen\n    window_days: 730\n  degree_caps:\n    social:handle: 10000\n  negative_nodes:\n  - form: social:handle\n    list: benign_job_recruiters\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- social\n- osint_web\n- bank_txn\n",
  "FIN_ORG_LEI_PARENT_SANCTIONS": "id: FIN_ORG_LEI_PARENT_SANCTIONS\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - financial_records\n  - lei_resolution\n  - sanctions_list_access\n  - semantic_execution_contract_v1\n  - source_revision_scoped_relations\n  - explicit_temporal_applicability\n  - amendment_context\n  optional:\n  - beneficial_ownership_resolution\n  - entity_normalization\nhazards:\n- LEI parent relationships, shared holding structures, and sanctions lists can lag\n  restructures, ownership changes, or jurisdiction-specific legal interpretations.\n- Corroborate temporal ownership, control, and sanctions effective dates; do not treat\n  a parent link as automatic prohibited activity.\n- LEI ownership chains, beneficial-ownership disclosures, and sanctions-list access\n  may be jurisdiction-restricted or commercially sensitive and require governance\n  review before risk scoring.\n- Source-reported identity, relationship and list status require separate evidence;\n  no traversal supplies legal exposure, liability, control, source independence or\n  accepted assessment status.\n- A selected historical-status inquiry requires the actual applicable relationship\n  and list intervals. Later publication, receipt and correction do not backdate analyst\n  knowledge or refresh activity.\nname: Organization → Reported LEI Parent → Sanctions Entries\ncategory: FIN\ndescription: Follow source-qualified legal-entity correspondence and a reported LEI\n  parent relationship to selected sanctions entry revisions. Preserve the particular\n  parent relation and its applicability; registration, issuance and discovery dates\n  do not substitute for relationship time.\nsource: org:org\ntarget: sanction:entry\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/FIN_ORG_LEI_PARENT_SANCTIONS.json\n  sha256: 48fec6ad0a71fe53e8fdad53ce8a4ee310ece44cddb29f669cdd513800f02d14\nhops:\n- via: has_lei\n  direction: out\n  form: lei:record\n- via: parent_of|ultimate_parent\n  direction: out\n  form: lei:record\n- via: listed_as\n  direction: out\n  form: sanction:entry\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- lei\n- sanctions\n",
  "FIN_ORG_OFFICER_SHARE_CLUSTER": "id: FIN_ORG_OFFICER_SHARE_CLUSTER\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - financial_records\n  - identity_records\n  - semantic_execution_contract_v1\n  - scoped_identity_correspondence\n  - source_qualified_appointment_service\n  - scoped_control_evaluation\n  optional:\n  - officer_record_normalization\n  - company_registry_context\nhazards:\n- Common names, jurisdictional identifiers and stale registry data require exact person/organization/appointment\n  scope.\n- Professional, nominee and capacity classifications attach to the particular appointment;\n  they do not exclude the whole person.\n- Separate historical appointments need not overlap and do not establish shell companies,\n  beneficial ownership or control.\nname: Org Officer/Director → Cross‑Directorship Cluster\ncategory: FIN\ndescription: Find organizations connected by directly evidenced officer/director appointments\n  of the selected person within an explicit service scope. Preserve historical and\n  nonconcurrent appointments without co-appointee expansion, shell-network or control\n  inference.\nsource: person\ntarget: org:org\nassessment_mode: evidence_only\nhops:\n- via: officer_of|director_of\n  direction: out\n  form: org:org\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- opencorp\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/FIN_ORG_OFFICER_SHARE_CLUSTER.json\n  sha256: 10ec7a3e7e89de84b2707f0867a5025556f460742bd9b2bbeabd7a131a98bd4d\n",
  "FIN_REFUND_DESTINATION_ACCOUNT_CLUSTER": "id: FIN_REFUND_DESTINATION_ACCOUNT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'payout_account_normalization'\n  optional:\n  - 'merchant_profile_context'\n  - 'refund_timing_context'\nhazards:\n- Refund receivers, processors, and settlement accounts can be shared legitimately by marketplaces or service providers.\n- Bank account data is restricted; corroborate account control, refund timing, and merchant context before treating reuse as fraud.\nname: Refund Destination Account -> Merchant Cluster\ncategory: FIN\ndescription: Cluster merchants or actors whose refunds repeatedly terminate in the same beneficiary account or refund receiver.\nsource: fin:account\ntarget: fin:merchant|person\nassessment_mode: evidence_only\nhops:\n- via: receives_refund_for\n  direction: out\n  form: fin:merchant|person\nconstraints:\n  temporal:\n    order:\n    - account.firstseen <= refund.ts\n    window_days: 1825\n  degree_caps:\n    fin:account: 500\n  negative_nodes:\n  - form: fin:account\n    list: merchant_customer_support_accounts\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- payments\n- bank_txn\n- ecommerce\n",
  "FIN_REGISTERED_ADDRESS_CLUSTER": "id: FIN_REGISTERED_ADDRESS_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'address_normalization'\n  optional:\n  - 'identity_records'\n  - 'company_registry_context'\nhazards:\n- Registered agents, mail drops, coworking spaces, and residential blocks can create common address clusters at scale.\n- Address data can be privacy-sensitive and stale; corroborate with officer, account, and temporal registry context before inferring control.\nname: Registered Address → Company Cluster\ncategory: FIN\ndescription: Identify mass‑registration addresses linked to many entities (possible formation agents).\nsource: geo:address\ntarget: org:org\nassessment_mode: evidence_only\nhops:\n- via: registered_address_of\n  direction: out\n  form: org:org\nconstraints:\n  temporal:\n    order:\n    - address.firstseen <= org.created\n    window_days: 3650\n  degree_caps:\n    geo:address: 10000\n  negative_nodes:\n  - form: geo:address\n    list: registered_agent_addresses\n  - form: geo:address\n    list: virtual_office_or_maildrop_addresses\n  - form: geo:address\n    list: large_residential_or_coworking_addresses\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- opencorp\n",
  "FIN_SUPPLIER_SPLIT_PAYMENTS": "id: FIN_SUPPLIER_SPLIT_PAYMENTS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'payment_chain_context'\n  optional:\n  - 'beneficial_ownership_resolution'\n  - 'kyc_context'\nhazards:\n- Shared officers or addresses can reflect procurement agents, affiliates, or registration services rather than coordinated structuring.\n- Payment records are restricted financial data; corroborate order timing, account control, and sanctions or KYC context before flagging split payments.\nname: Supplier → Split Payments Pattern\ncategory: FIN\ndescription: Detect order splitting or structuring across suppliers linked by officers/addresses.\nsource: org:org\ntarget: org:org\nassessment_mode: evidence_only\nhops:\n- via: received_payment_from\n  direction: in\n  form: fin:transaction\n- via: shares_officer|shares_address\n  direction: out\n  form: org:org\nconstraints:\n  temporal:\n    order:\n    - txn.ts <= now()\n    window_days: 3650\n  degree_caps:\n    org:org: 10000\n  negative_nodes:\n  - form: org:org\n    list: shared_procurement_agents\n  - form: org:org\n    list: registration_service_shared_entities\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- bank_txn\n- opencorp\n",
  "FIN_SYNTHETIC_IDENTITY_ATTRIBUTE_CLUSTER": "id: FIN_SYNTHETIC_IDENTITY_ATTRIBUTE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'financial_records'\n  - 'identity_records'\n  optional:\n  - 'attribute_normalization'\n  - 'kyc_context'\nhazards:\n- Shared phones, addresses, IPs, or devices can come from families, dorms, employers, proxies, or reused data brokers.\n- Identity attributes are privacy-sensitive; corroborate with KYC, account behavior, and temporal patterns before clustering synthetic identities.\nname: Synthetic Identity -> Shared Attribute Cluster\ncategory: FIN\ndescription: Link synthetic or mule identities reusing the same contact, address, or profile attributes across nominally distinct personas.\nsource: person\ntarget: person\nassessment_mode: evidence_only\nhops:\n- via: uses_attribute\n  direction: out\n  form: email:addr|tel:phone|geo:address\n- via: used_by\n  direction: out\n  form: person\nconstraints:\n  temporal:\n    order:\n    - person.created <= attribute.seen <= linked_person.seen\n    window_days: 3650\n  degree_caps:\n    person: 1000\n  negative_nodes:\n  - form: email:addr\n    list: disposable_email_domains\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- kyc\n- fraud_ops\n",
  "FIN_TRADE_PARTNER_SANCTIONS": "id: FIN_TRADE_PARTNER_SANCTIONS\nversion: 3.0.0\npattern_schema_version: 1.6\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - financial_records\n  - sanctions_list_access\n  - semantic_execution_contract_v1\n  - source_revision_scoped_relations\n  - explicit_temporal_applicability\n  - amendment_context\n  optional:\n  - trade_record_normalization\n  - beneficial_ownership_resolution\nhazards:\n- Trade counterparties, shared intermediaries, ownership chains, and sanctions lists\n  change over time and vary by jurisdiction.\n- Corroborate shipment date, beneficial ownership, and account or payment context;\n  avoid false positives from same-name or intermediary partners.\n- Trade, shipment, payment, and counterparty records may be commercially sensitive\n  or restricted and need explicit governance before use.\n- Source-reported identity, relationship and list status require separate evidence;\n  no traversal supplies legal exposure, liability, control, source independence or\n  accepted assessment status.\n- A selected historical-status inquiry requires the actual applicable relationship\n  and list intervals. Later publication, receipt and correction do not backdate analyst\n  knowledge or refresh activity.\nname: Trade Event → Partner Sanctions Entries\ncategory: FIN\ndescription: Follow an individual reported trade event between the selected organization\n  and an evidenced partner to selected sanctions entry revisions. A transaction report\n  is distinct from a standing trade relationship and from status at the event time.\nsource: org:org\ntarget: sanction:entry\nassessment_mode: evidence_only\nexecution:\n  contract: everypivot.semantic_pattern\n  version: '1.0'\n  path: contracts/semantics/FIN_TRADE_PARTNER_SANCTIONS.json\n  sha256: b005fc1d983f6361400ecf8bbd2319d910cae7ea0d900f32e08a77ee10a1afc7\nhops:\n- via: trades_with\n  direction: out\n  form: org:org\n- via: listed_as\n  direction: out\n  form: sanction:entry\nconstraints:\n  provenance:\n    min_unique_sources: 1\nfeatures: []\noutputs:\n  yield:\n  - source\n  - target\n  - evidence_paths\ndatasets:\n- sanctions\n- osint_web\n",
  "HUM_BLUETOOTH_PROXIMITY": "id: HUM_BLUETOOTH_PROXIMITY\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\nname: Device → Bluetooth Proximity → Device\ncategory: HUMINT_SIGINT\ndescription: Proximity graph from Bluetooth beacon observations to infer meetings.\nhazards:\n- 'Dense public venues, transit, and office environments create near-certain false positives for co-presence.'\n- 'Bluetooth collection can carry significant privacy and consent implications depending on jurisdiction and collection method.'\ncapability_requirements:\n  required:\n  - 'bluetooth_observation_collection'\n  - 'spatiotemporal_correlation'\n  optional:\n  - 'venue_context'\n  - 'legal_review'\nsource: device:device\ntarget: device:device\nassessment_mode: evidence_only\nhops:\n- via: bt_seen_within\n  direction: out\n  form: device:device\nconstraints:\n  temporal:\n    order:\n    - bt.ts within window\n    window_days: 7\n  degree_caps:\n    device:device: 100000\n  negative_nodes:\n  - form: device:device\n    list: transit_hub_observations\n  - form: device:device\n    list: conference_or_public_venue_devices\n  - form: device:device\n    list: beacon_or_kiosk_devices\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- siem\n",
  "HUM_CDR_COLOCATION_LINK": "id: HUM_CDR_COLOCATION_LINK\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\nname: Phone → CDR → Co‑Location Link\ncategory: HUMINT_SIGINT\ndescription: Infer links between MSISDNs via repeated co‑location in time and space (tower/sector).\nhazards:\n- 'CDR access is regulated in many jurisdictions and may require lawful-intercept or similarly restricted authority.'\n- 'Dense urban tower coverage, roaming, and shared sectors create systemic false positives without strong temporal controls.'\ncapability_requirements:\n  required:\n  - 'cdr_access'\n  - 'spatiotemporal_correlation'\n  optional:\n  - 'tower_geography'\n  - 'legal_review'\nsource: telecom:msisdn\ntarget: telecom:msisdn\nassessment_mode: evidence_only\nhops:\n- via: cdr_event\n  direction: out\n  form: telecom:cdr\n- via: same_cell_same_time\n  direction: in\n  form: telecom:cdr\n- via: for\n  direction: in\n  form: telecom:msisdn\nconstraints:\n  temporal:\n    order:\n    - cdr.ts within window\n    window_days: 30\n  degree_caps:\n    telecom:cdr: 200000\n  negative_nodes:\n  - form: telecom:cdr\n    list: dense_urban_sector_observations\n  - form: telecom:cdr\n    list: roaming_gateway_records\n  - form: telecom:cdr\n    list: mass_event_tower_observations\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- cdr\n",
  "HUM_PERSON_EMAIL_ORG_LINK": "id: HUM_PERSON_EMAIL_ORG_LINK\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\nname: Person Email → Organization Link\ncategory: HUMINT_SIGINT\ndescription: Associate a person to an organization via corporate email domains observed in communications.\nhazards:\n- 'Corporate email usage can reflect contractors, temporary roles, or historical affiliations rather than current membership.'\n- 'Forwarders, aliases, and consumer mailboxes using branded domains can misstate organisational control.'\n- 'Lawful authority, jurisdiction, privacy constraints, and corroboration are required because shared aliases and stale emails create false positives.'\ncapability_requirements:\n  required:\n  - 'communication_metadata'\n  - 'domain_ownership_resolution'\n  optional:\n  - 'employment_context'\nsource: person\ntarget: org:org\nassessment_mode: evidence_only\nhops:\n- via: uses_email\n  direction: out\n  form: email:addr\n- via: domain_of\n  direction: out\n  form: inet:fqdn\n- via: owned_by\n  direction: out\n  form: org:org\nconstraints:\n  temporal:\n    order:\n    - email.firstseen <= org.created\n    window_days: 1095\n  degree_caps:\n    email:addr: 1000\n  negative_nodes:\n  - form: email:addr\n    list: role_or_shared_mailboxes\n  - form: email:addr\n    list: contractor_or_alumni_aliases\n  - form: email:addr\n    list: consumer_forwarding_aliases\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n- rdap\n",
  "HUM_PERSON_FIN_ACCOUNTS_LINK": "id: HUM_PERSON_FIN_ACCOUNTS_LINK\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\nname: Person → Financial Accounts Link\ncategory: HUMINT_SIGINT\ndescription: Link persons by shared devices/IPs used to access multiple accounts within short windows.\nhazards:\n- 'CGNAT, shared Wi-Fi, and corporate NAT create systemic false matches when IP reuse is interpreted as person-level linkage.'\n- 'Financial-access telemetry is highly sensitive and may be legally restricted or require explicit governance approval.'\ncapability_requirements:\n  required:\n  - 'regulated_account_access_logs'\n  - 'device_or_network_correlation'\n  optional:\n  - 'kyc_context'\n  - 'legal_review'\nsource: person\ntarget: person\nassessment_mode: evidence_only\nhops:\n- via: owns_account\n  direction: out\n  form: fin:account\n- via: accessed_from_ip\n  direction: out\n  form: inet:ipv4\n- via: accessed_from_ip\n  direction: in\n  form: fin:account\n- via: owned_by\n  direction: in\n  form: person\nconstraints:\n  temporal:\n    order:\n    - access.ts within window\n    window_days: 30\n  degree_caps:\n    inet:ipv4: 10000\n  negative_nodes:\n  - form: inet:ipv4\n    list: public_proxies_vpns\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- bank_txn\n- siem\n",
  "HUM_PNR_COTRAVEL_LINK": "id: HUM_PNR_COTRAVEL_LINK\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\nname: PNR → Co‑Travel Link\ncategory: HUMINT_SIGINT\ndescription: Identify co‑travelers via shared PNR/segments within a time window.\nhazards:\n- 'Shared itineraries do not by themselves establish association, intent, or operational collaboration.'\n- 'PNR data is regulated and often restricted to travel operators or law-enforcement-style access models.'\n- 'Use only under lawful authority and jurisdiction-specific privacy controls; corroborate co-travel to avoid false positives from group bookings.'\ncapability_requirements:\n  required:\n  - 'pnr_access'\n  - 'itinerary_correlation'\n  optional:\n  - 'seat_or_booking_context'\n  - 'legal_review'\nsource: travel:pnr\ntarget: person\nassessment_mode: evidence_only\nhops:\n- via: includes_passenger\n  direction: out\n  form: person\n- via: same_segment_within_window\n  direction: in\n  form: person\nconstraints:\n  temporal:\n    order:\n    - segment.dep_ts within window\n    window_days: 30\n  degree_caps:\n    travel:pnr: 100000\n  negative_nodes:\n  - form: travel:pnr\n    list: group_booking_records\n  - form: travel:pnr\n    list: package_tour_or_crew_itineraries\n  - form: travel:pnr\n    list: mass_delay_or_rebooking_events\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pnr\n",
  "HUM_WIFI_BSSID_CONTACT_CHAIN": "id: HUM_WIFI_BSSID_CONTACT_CHAIN\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: restricted_data_access\nprecision_tier: exploratory\nname: Device → Wi‑Fi BSSID → Co‑Presence\ncategory: HUMINT_SIGINT\ndescription: Detect co‑presence via devices seen on the same BSSID within time windows.\nhazards:\n- 'Public hotspots and enterprise guest networks create extremely high-degree noise for shared-BSSID inference.'\n- 'MAC randomization, reused access-point identifiers, and venue churn can distort apparent contact chains.'\n- 'Lawful access, jurisdiction, and privacy controls are required; corroborate shared BSSID contact chains to avoid false positives in dense venues.'\ncapability_requirements:\n  required:\n  - 'wifi_observation_data'\n  - 'spatiotemporal_correlation'\n  optional:\n  - 'venue_context'\n  - 'legal_review'\nsource: device:device\ntarget: device:device\nassessment_mode: evidence_only\nhops:\n- via: observed_on_bssid\n  direction: out\n  form: net:wifi:bssid\n- via: observed_on_bssid\n  direction: in\n  form: device:device\nconstraints:\n  temporal:\n    order:\n    - obs.ts within window\n    window_days: 14\n  degree_caps:\n    net:wifi:bssid: 10000\n  negative_nodes:\n  - form: net:wifi:bssid\n    list: public_hotspot_bssids\n  - form: net:wifi:bssid\n    list: enterprise_guest_network_bssids\n  - form: net:wifi:bssid\n    list: reused_or_randomized_ap_identifiers\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- siem\n",
  "IO_CONTENT_HASH_TO_ACCOUNT_CLUSTER": "id: IO_CONTENT_HASH_TO_ACCOUNT_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'platform_abuse_records'\n  - 'content_fingerprinting'\n  optional:\n  - 'social_profile_collection'\n  - 'campaign_context_enrichment'\nhazards:\n- Stock media, memes, templates, and reposted documents can be common across unrelated accounts.\n- Corroborate exact content-hash reuse with timing, behavior, and campaign context; identical media alone is not common control.\n- Public datasets, moderation queues, analyst uploads, and training artifacts can reproduce hashes and must remain suppressible.\nname: Content Hash -> Account Cluster\ncategory: IO\ndescription: Cluster coordinated accounts reusing identical media assets, documents, or attachments across posts and campaigns.\nsource: hash:sha256\ntarget: inet:web:acct\nassessment_mode: evidence_only\nhops:\n- via: posted_by|used_by\n  direction: out\n  form: inet:web:acct\nconstraints:\n  temporal:\n    order:\n    - content.firstseen <= account.seen\n    window_days: 365\n  degree_caps:\n    hash:sha256: 5000\n  negative_nodes:\n  - form: hash:sha256\n    list: stock_media_hashes\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- social\n- osint_web\n",
  "IO_CROSS_PLATFORM_HANDLE_CLUSTER": "id: IO_CROSS_PLATFORM_HANDLE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'platform_abuse_records'\n  - 'social_profile_collection'\n  optional:\n  - 'handle_normalization'\n  - 'profile_metadata_extraction'\nhazards:\n- Common usernames, fan accounts, impersonators, and namespace collisions can create false cross-platform links.\n- Corroborate handle reuse with profile metadata, timing, and behavioral evidence before clustering accounts.\n- Human or brand handle matches can create reputational harm; block person identity, authorship, ownership, or attribution conclusions.\nname: Cross-Platform Handle -> Account Cluster\ncategory: IO\ndescription: Link common handle strings or aliases reused across platforms by coordinated or inauthentic personas.\nsource: social:handle\ntarget: inet:web:acct\nassessment_mode: evidence_only\nhops:\n- via: resolves_to\n  direction: out\n  form: inet:web:acct\nconstraints:\n  temporal:\n    order:\n    - handle.firstseen <= account.seen\n    window_days: 1825\n  degree_caps:\n    social:handle: 10000\n  negative_nodes:\n  - form: social:handle\n    list: generic_common_usernames\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- social\n",
  "IO_FORGED_DOCUMENT_TEMPLATE_CLUSTER": "id: IO_FORGED_DOCUMENT_TEMPLATE_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'platform_abuse_records'\n  - 'content_fingerprinting'\n  optional:\n  - 'document_template_suppression'\n  - 'campaign_context_enrichment'\nhazards:\n- Public templates, copied seals, and common editing tools can produce similar documents across unrelated accounts or campaigns.\n- Defender, analyst, or researcher reproduction and replay of forged-document templates can create benign matches unless testing and training artifacts are suppressed.\n- Corroborate template reuse with distribution timing, account behavior, and additional artifacts; template match alone is weak evidence.\nname: Forged Document Template -> Operator Cluster\ncategory: IO\ndescription: Cluster operators or campaigns reusing the same forged-document templates, seals, or layout artifacts.\nsource: file:bytes\ntarget: inet:web:acct|risk:campaign\nassessment_mode: evidence_only\nhops:\n- via: observed_in\n  direction: out\n  form: forged:document\n- via: distributed_by|attributed_to\n  direction: out\n  form: inet:web:acct|risk:campaign\nconstraints:\n  temporal:\n    order:\n    - template.firstseen <= document.firstseen <= operator.seen\n    window_days: 1825\n  degree_caps:\n    file:bytes: 2000\n  negative_nodes:\n  - form: file:bytes\n    list: public_press_release_templates\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- social\n- media_monitoring\n- osint_web\n",
  "IO_SHARED_SHORTENER_OR_TRACKING_CLUSTER": "id: IO_SHARED_SHORTENER_OR_TRACKING_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'platform_abuse_records'\n  - 'redirect_resolution'\n  optional:\n  - 'web_fingerprinting'\n  - 'tracking_id_extraction'\nhazards:\n- Public shorteners, campaign platforms, and tracking vendors are shared across many unrelated accounts and domains.\n- Corroborate redirect and tracking reuse with landing content, timing, and operator-controlled artifacts; expect false positives.\n- Shared vendor IDs, link shorteners, and hosted tracking platforms need suppression before any campaign or operator-control claim.\nname: Shortener or Tracking Domain -> IO Property Cluster\ncategory: IO\ndescription: Cluster IO properties reusing the same shortener, redirector, or campaign-tracking domain across accounts or sites.\nsource: inet:fqdn\ntarget: inet:web:acct|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: embedded_in\n  direction: out\n  form: web:url\n- via: posted_by|redirects_to\n  direction: out\n  form: inet:web:acct|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - tracker.seen <= url.seen <= property.seen\n    window_days: 365\n  degree_caps:\n    inet:fqdn: 2000\n  negative_nodes:\n  - form: inet:fqdn\n    list: mainstream_link_shorteners\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- social\n- osint_web\n",
  "OSINT_REVERSE_DNS_HOST_CLUSTER": "id: OSINT_REVERSE_DNS_HOST_CLUSTER\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\ncapability_requirements:\n  required:\n  - 'dns_public_lookup'\n  - 'passive_dns'\n  optional:\n  - 'reverse_dns_lookup'\n  - 'hosting_provider_classification'\nhazards:\n- Provider default PTR names, recycled hostnames, and cloud templates can create common reverse-DNS values across unrelated hosts.\n- Corroborate PTR reuse with DNS timing, service banners, certificates, and hosting context; reverse DNS alone is weak.\n- Provider-managed naming schemes need negative controls; do not infer tenant identity or control from PTR text alone.\nname: Reverse DNS Hostname -> Host Cluster\ncategory: OSINT\ndescription: Cluster hosts reusing uncommon PTR or reverse-DNS hostnames while filtering commodity provider naming patterns.\nsource: inet:fqdn\ntarget: inet:ipv4|inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: reverse_resolves\n  direction: out\n  form: inet:ipv4\n- via: hosts\n  direction: out\n  form: inet:ipv4|inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - ptr.seen <= ipv4.seen <= host.seen\n    window_days: 365\n  degree_caps:\n    inet:fqdn: 10000\n  negative_nodes:\n  - form: inet:fqdn\n    list: provider_reverse_dns_zones\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- dns\n- pdns\n",
  "OSINT_SHARED_IP_TO_DOMAINS": "id: OSINT_SHARED_IP_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: needs_fixtures\nprecision_tier: exploratory\nrobustness_class: multi_hop_inference\nhazards:\n- 'Shared hosting, CDN edges, parking providers, and recycled cloud IPs can connect thousands of unrelated domains.'\n- 'Co-hosting only has evidentiary value when the DNS observation windows overlap the investigated activity and the IP is not provider-dominated.'\ncapability_requirements:\n  required:\n  - 'passive_dns'\n  - 'temporal_dns_history'\n  - 'asn_enrichment'\n  optional:\n  - 'active_resolution'\n  - 'hosting_provider_classification'\nname: Shared IP -> Co-Hosted Domains\ncategory: OSINT\ndescription: Enumerate domains co-hosted on the same IP address during an overlapping observation window.\nsource: inet:ipv4\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: hosted\n  direction: in\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - source.firstseen <= target.lastseen\n    - target.firstseen <= source.lastseen\n    window_days: 90\n  degree_caps:\n    inet:ipv4: 500\n  negative_nodes:\n  - form: inet:ipv4\n    list: cdn_edges\n  - form: inet:ipv4\n    list: shared_hosting_edges\n  - form: inet:ipv4\n    list: parking_infrastructure\n  provenance:\n    min_unique_sources: 2\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- co_residence_overlap_days\n- novelty_flag\noutputs:\n  top_paths: 5\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- pdns\n- dns\n- asn\n",
  "OSINT_TRACKING_ID_TO_DOMAINS": "id: OSINT_TRACKING_ID_TO_DOMAINS\nversion: 2.0.0\npattern_schema_version: 1.5\nvalidation_state: deferred\ndeferred_reason: high_cardinality\nprecision_tier: exploratory\nrobustness_class: enumeration\ncapability_requirements:\n  required:\n  - 'web_fingerprinting'\n  - 'tracking_id_extraction'\n  optional:\n  - 'web_crawling'\n  - 'tag_manager_extraction'\n  - 'tracking_id_normalization'\n  - 'domain_ownership_resolution'\nhazards:\n- Analytics tags, ad pixels, agency-managed accounts, and shared tracking vendors can appear on many unrelated domains.\n- Corroborate tracking-ID reuse with page ownership, timing, and content or infrastructure evidence; high-degree IDs produce false positives.\n- Demo IDs, staging containers, copied templates, and tag-manager defaults can make unrelated domains look connected.\n- Treat tracking-ID reuse as weak correlation or fan-out context, not as ownership proof or attribution.\nname: Tracking ID (GA/FB Pixel) → Domains\ncategory: OSINT\ndescription: Cluster domains/pages sharing the same analytics or ad-tracking identifier.\nsource: web:tracking:id\ntarget: inet:fqdn\nassessment_mode: evidence_only\nhops:\n- via: present_on\n  direction: out\n  form: inet:fqdn\nconstraints:\n  temporal:\n    order:\n    - trackingid.seen <= fqdn.seen\n    window_days: 1095\n  degree_caps:\n    web:tracking:id: 10000\n  negative_nodes:\n  - form: web:tracking:id\n    list: common_analytics_or_ad_network_ids\n  - form: web:tracking:id\n    list: agency_or_tag_manager_container_ids\n  - form: web:tracking:id\n    list: shared_testing_or_demo_tracking_ids\n  provenance:\n    min_unique_sources: 1\nfeatures:\n- path_length\n- rarity_idf\n- path_count_capped\n- vendor_diversity\n- multi_source_ratio\n- temporal_consistency\n- days_since_support\n- popular_tool_penalty\n- novelty_flag\noutputs:\n  top_paths: 3\n  yield:\n  - source\n  - target\n  - features\n  - evidence_paths\n  - storm_query\ndatasets:\n- osint_web\n"
};
